HT.CDF["G04"] = {"bang":[{"i":0,"tieu_de_bang":"Sài Gòn – Bến Nhà Rồng","tieu_de":"Sài Gòn 1911: bốn tháng mở cánh cửa ra biển lớn của người thanh niên Nguyễn Tất Thành","sapo":"Trưa ngày 5/6/1911, một con tàu buôn Pháp rời Sài Gòn, mang theo một phụ bếp vừa nhận việc hai hôm trước. Không ai trên tàu biết người thanh niên hai mươi mốt tuổi ấy vừa khép lại bốn tháng chuẩn bị lặng lẽ ở thành phố cảng. Vì sao lại là Sài Gòn, vì sao lại là phương Tây, và anh đã mang theo những gì? Gian trưng bày này mở ra từ những câu hỏi ấy.","bia":{"src":"textures/bai/G04_v1.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Trưa ngày 5 tháng 6 năm 1911","text":"Trưa ngày 5/6/1911, tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis nhổ neo rời cảng Sài Gòn, xuôi dòng sông ra biển. Con tàu buôn kiêm chở khách ấy chỉ dừng ở Sài Gòn chừng ba ngày, kể từ hôm cập bến 2/6. Trong mấy ngày ngắn ngủi đó, tàu nhận thêm một phụ bếp người Việt, vào làm từ ngày 3/6 với cái tên Văn Ba và đồng lương 45 franc mỗi tháng.\n\nNgười phụ bếp ấy là Nguyễn Tất Thành, vừa bước sang tuổi hai mươi mốt được mười bảy ngày. Anh không có vé tàu, không có người bảo lãnh, không có tiền dành dụm. Thứ anh mang theo là sức lao động, vốn chữ Hán học từ nhỏ, vốn tiếng Pháp học ở các trường Pháp – Việt, và một câu hỏi lớn về vận mệnh của dân tộc. Chuyến đi bắt đầu từ trưa hôm ấy sẽ kéo dài ba mươi năm. Vì sao một thanh niên có học, từng đứng lớp dạy học trò, lại chọn ra đi theo cách của người làm thuê? Để hiểu điều đó, ta phải trở lại bốn tháng trước, khi anh lần đầu đặt chân đến thành phố cảng lớn nhất xứ Nam Kỳ.","doc":1},{"loai":"anh","src":"textures/bang_w/G04_0_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sài Gòn – Bến Nhà Rồng”, nhìn từ xa."},{"loai":"doan","tieu_de":"Con đường xuôi phương Nam","text":"Con đường dẫn tới Sài Gòn bắt đầu từ Huế. Tháng 9/1906, Nguyễn Tất Thành vào học Trường tiểu học Pháp – Việt ở Huế. Tháng 4/1908, anh tham gia cuộc biểu tình chống thuế của nông dân tỉnh Thừa Thiên. Tháng 9 năm ấy, anh học lớp trung đẳng tại Trường Quốc học Huế. Khoảng tháng 6/1909, anh rời Quốc học, theo cha là cụ Phó bảng Nguyễn Sinh Sắc vào Bình Định, rồi học tiếp ở Trường tiểu học Pháp – Việt Quy Nhơn.\n\nTháng 6/1910, anh hoàn thành chương trình tiểu học thì nghe tin cha bị cách chức tri huyện Bình Khê. Không theo cha trở ra Huế, anh quyết định đi tiếp về phía Nam. Ở Phan Thiết, anh xin làm trợ giáo tại Trường Dục Thanh, trường tư thục do các ông Nguyễn Trọng Lội và Nguyễn Quý Anh lập năm 1907. Anh được giao dạy một số môn và phụ trách hoạt động ngoại khóa. Trong tủ sách của cụ Nguyễn Thông, anh tìm đọc những cuốn sách quý, tiếp cận tư tưởng tiến bộ của các nhà khai sáng Pháp như Rousseau, Voltaire, Montesquieu. Tháng 2/1911, anh rời Phan Thiết vào Sài Gòn. Đó là chặng cuối của con đường bộ, và cũng là cửa ngõ của con đường biển.","doc":2},{"loai":"doan","tieu_de":"Thủ phủ của một xứ thuộc địa","text":"Sài Gòn mà Nguyễn Tất Thành đặt chân tới là thành phố do người Pháp quy hoạch lại trên đất Gia Định xưa. Ngày 17/2/1859, quân Pháp đánh chiếm thành Gia Định. Ba năm sau, Hòa ước Nhâm Tuất buộc triều Nguyễn nhượng ba tỉnh miền Đông Nam Kỳ. Sài Gòn trở thành thủ phủ xứ Nam Kỳ thuộc địa. Có thời, đây còn là nơi đặt bộ máy cai trị cao nhất của người Pháp ở Đông Dương, trước khi thủ phủ Liên bang Đông Dương dời ra Hà Nội vào đầu thế kỷ XX.\n\nThành phố sống nhờ dòng sông. Từ khi kênh Suez khánh thành năm 1869, đường biển từ Marseille sang Viễn Đông rút ngắn hẳn, và tàu của các hãng Pháp đi về đều đặn giữa Sài Gòn với chính quốc. Lúa gạo từ đồng bằng sông Cửu Long theo kênh rạch về các nhà máy xay xát ở Chợ Lớn, rồi xuống tàu ra nước ngoài. Dọc bờ sông là kho hàng, xưởng máy, cầu tàu, nơi phu bốc vác làm việc nặng nhọc với đồng lương thấp. Bên cạnh những đại lộ, dinh thự và tiệm cà phê của người Âu là những xóm trọ chật chội của thợ thuyền, người làm thuê. Sự tương phản ấy là bài học đầu tiên mà Sài Gòn dành cho người thanh niên xứ Nghệ.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_saigon_la_pointe_des_blagueurs_le_paul_lecat_sur.jpg","chu_thich":"Bến cảng Sài Gòn đầu thế kỷ XX, tàu viễn dương neo trên sông. Bưu ảnh chụp đoạn mũi Pointe des Blagueurs với con tàu Paul-Lecat, không phải tàu Amiral Latouche-Tréville.","credit":"Ảnh: Francis Alexandre Decoly · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Vì sao là phương Tây?","text":"Những năm đầu thế kỷ XX, các con đường cứu nước của thế hệ đi trước lần lượt gặp bế tắc. Phong trào Đông Du của cụ Phan Bội Châu đưa thanh niên sang Nhật học tập, rồi tan rã khi chính phủ Nhật trục xuất du học sinh Việt Nam theo thỏa thuận với Pháp. Năm 1908, phong trào chống thuế ở Trung Kỳ bị đàn áp; cụ Phan Châu Trinh bị bắt và đày ra Côn Đảo.\n\nTheo sách của Trần Dân Tiên, người thanh niên Nguyễn Tất Thành rất khâm phục các bậc tiền bối, nhưng không tán thành cách làm của các cụ. Cụ Phan Bội Châu hy vọng Nhật giúp đuổi Pháp; anh cho rằng điều đó rất nguy hiểm, chẳng khác gì “đưa hổ cửa trước, rước beo cửa sau”. Cụ Phan Châu Trinh chỉ yêu cầu người Pháp thực hiện cải lương; anh cho rằng như thế chẳng khác gì “xin giặc rủ lòng thương”. Cụ Hoàng Hoa Thám trực tiếp đấu tranh chống Pháp nên thực tế hơn, nhưng theo lời người ta kể thì còn nặng cốt cách phong kiến. Từ đó, anh chọn một hướng đi khác: tự mình sang phương Tây, sang chính nước Pháp, để tìm hiểu tận gốc sức mạnh của kẻ đang cai trị dân tộc mình, và cả những khẩu hiệu mà họ vẫn rao giảng.","doc":4},{"loai":"trich","text":"Vào trạc tuổi mười ba, lần đầu tiên tôi được nghe những từ Pháp: Tự do, Bình đẳng, Bác ái… Và từ thuở ấy, tôi rất muốn làm quen với nền văn minh Pháp, muốn tìm xem những gì ẩn giấu đằng sau những từ ấy.","nguoi":"Nguyễn Ái Quốc","nguon_ten":"Trả lời nhà báo Ô-xíp Man-đen-xtam, bài “Thăm một chiến sĩ Quốc tế Cộng sản – Nguyễn Ái Quốc”, tạp chí Ogoniok (Liên Xô), 23/12/1923","doc":5},{"loai":"doan","tieu_de":"Sống giữa những người lao động","text":"Ở Sài Gòn, Nguyễn Tất Thành không phải người xa lạ không nơi nương tựa. Anh ở tạm tại các chi nhánh của Liên Thành, tổ chức kinh doanh do các sĩ phu Duy Tân ở Phan Thiết lập nên: một chi nhánh trên đường Tổng đốc Phương ở Chợ Lớn, một chi nhánh ở Khánh Hội. Khánh Hội là vùng bến bãi bên kia rạch Bến Nghé, cũng là nơi tòa Nhà Rồng soi bóng xuống sông. Những người của Liên Thành cũng chính là những người đã lập trường Dục Thanh, nơi anh vừa dạy học.\n\nTừ những căn nhà ấy, anh đi vào các xóm thợ nghèo, lui tới các cửa hàng gần bến cảng để dò hỏi việc làm trên tàu. Anh tận mắt chứng kiến đời sống cực nhọc của người lao động dưới chế độ thuộc địa. Cũng trong những tháng này, anh tìm một người bạn cùng đi, và câu chuyện ấy được kể trong một chuyên đề riêng (xem chuyên đề Lời rủ ra đi và người bạn tên Lê). Bốn tháng ở Sài Gòn vì thế không phải thời gian chờ đợi thụ động. Đó là bốn tháng chuẩn bị, với ba việc phải làm: có chỗ dựa, có một nghề, và tìm được một con tàu sang Pháp.","doc":6},{"loai":"ban_co_biet","text":"Người phỏng vấn Nguyễn Ái Quốc cho tạp chí Ogoniok năm 1923 là Ô-xíp Man-đen-xtam, về sau được coi là một trong những nhà thơ Nga lớn của thế kỷ XX. Bài phỏng vấn ghi lại lời chính Người kể về ước muốn từ thuở thiếu thời: tìm hiểu những gì ẩn sau ba chữ Tự do, Bình đẳng, Bác ái.","nguon_ten":"Ô. Man-đen-xtam, “Thăm một chiến sĩ Quốc tế Cộng sản – Nguyễn Ái Quốc”, tạp chí Ogoniok, 23/12/1923","doc":7},{"loai":"doan","tieu_de":"Một cái nghề ở trường Bá Nghệ","text":"Việc thứ hai là học một cái nghề. Trong khoảng ba tháng đầu năm 1911, Nguyễn Tất Thành theo học Trường Cơ khí Á châu, tên tiếng Pháp là École des Mécaniciens Asiatiques, người Sài Gòn quen gọi là trường Bá Nghệ. Trường được thành lập ngày 20/2/1906, nằm trong khu vực giữa các đường Hàm Nghi, Lê Lợi và chợ Bến Thành ngày nay. Người Pháp lập trường để đào tạo thợ máy và nhân lực cho ngành hàng hải, đáp ứng nhu cầu của bộ máy cai trị thuộc địa và kỹ nghệ địa phương.\n\nVới người thanh niên đang tìm đường ra biển, ngôi trường ấy có ý nghĩa rất thiết thực. Theo Hoài Thanh và Thanh Tịnh trong bài “Quê hương và thời niên thiếu”, học ở đây vừa khỏi bị nghi ngờ, vừa có cơm ăn, vừa biết ít nhiều về máy móc. Anh học ở trường khoảng ba tháng rồi rời đi để lo việc xuống tàu. Thời gian ngắn ngủi ấy cho anh thêm một vốn liếng quan trọng bên cạnh chữ nghĩa: sự quen thuộc với xưởng máy, với lao động chân tay và với đời sống của người thợ.","doc":8},{"loai":"anh","src":"textures/bang_w/G04_0_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sài Gòn – Bến Nhà Rồng”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Hai hãng tàu và một cơ hội","text":"Việc thứ ba là tìm được một con tàu. Ở cảng Sài Gòn khi ấy, người Việt quen gọi hai hãng tàu Pháp lớn bằng những cái tên dân dã. Hãng Messageries Maritimes, chủ tòa Nhà Rồng, là “hãng Đầu Ngựa”. Hãng Chargeurs Réunis là “hãng Năm Sao”, theo biểu trưng năm ngôi sao trên ống khói tàu. Với một người không có tiền mua vé, cách duy nhất để lên những con tàu ấy là xin làm việc trên tàu, bất kể việc gì.\n\nCơ hội đến rất nhanh. Tàu Amiral Latouche-Tréville của hãng Năm Sao cập Sài Gòn ngày 2/6/1911. Ngày 3/6, anh được nhận làm phụ bếp; trưa ngày 5/6, tàu rời bến. Chỉ vài ngày, nhưng đó là mấy ngày đã được chuẩn bị bằng bốn tháng. Chuyện anh xin việc và những ngày làm phụ bếp trên tàu được kể riêng (xem chuyên đề Người phụ bếp Văn Ba). Còn con tàu neo ở cầu tàu nào của thương cảng hôm ấy, các nhà nghiên cứu vẫn đang bàn luận (xem chuyên đề Bến cảng Sài Gòn). Dù vậy, Bến Nhà Rồng từ lâu đã trở thành biểu tượng của cuộc ra đi, và gian trưng bày này mang tên bến cảng ấy.","doc":9},{"loai":"ban_co_biet","text":"Trường Bá Nghệ còn có một học trò nổi tiếng khác: người thợ máy Tôn Đức Thắng, học khóa 1915 – 1917. Hai học trò của ngôi trường này về sau đều trở thành Chủ tịch nước. Ngày nay, trường mang tên Trường Cao đẳng Kỹ thuật Cao Thắng.","nguon_ten":"Báo Nhân Dân – “Ngôi trường có hai Chủ tịch nước từng theo học”","doc":10},{"loai":"doan","tieu_de":"Ba mươi năm bắt đầu từ một ngày tháng Sáu","text":"Cuộc ra đi năm 1911 mở đầu ba mươi năm Người bôn ba qua nhiều châu lục. Người làm thuê trên tàu biển, sống giữa những người lao động ở Pháp, ở Anh, ở Mỹ, rồi đến với chủ nghĩa Mác – Lênin. Từ ngày 6/1 đến ngày 7/2/1930, tại Cửu Long, Hương Cảng, Người chủ trì hội nghị hợp nhất các tổ chức cộng sản, thành lập Đảng Cộng sản Việt Nam. Ngày 28/1/1941, Người trở về Tổ quốc qua cột mốc 108 ở biên giới Cao Bằng, rồi lãnh đạo toàn dân tiến tới Cách mạng Tháng Tám. Ngày 2/9/1945, tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa.\n\nNhìn lại từ những mốc ấy, trưa ngày 5/6/1911 là khởi điểm của cả một con đường. Người thanh niên ra đi với câu hỏi “họ làm như thế nào”, và trở về với câu trả lời cho dân tộc mình. Bởi vậy, ngày 5/6 hằng năm được kỷ niệm là Ngày Bác Hồ ra đi tìm đường cứu nước, và Bến Nhà Rồng là một trong những địa chỉ tưởng niệm quen thuộc của người dân Thành phố Hồ Chí Minh.","doc":11},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_museum_saigon.jpg","chu_thich":"Bến Nhà Rồng ngày nay — Bảo tàng Hồ Chí Minh, chi nhánh TP. Hồ Chí Minh (ảnh năm 2013).","credit":"Ảnh: Gary Todd · CC0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Đi qua gian trưng bày","text":"Gian trưng bày tái hiện một bến cảng Sài Gòn đầu thế kỷ XX trong không gian 3D, với kho hàng, thùng gỗ, thùng phuy, đèn treo và những chiếc xe kéo. Đây là không gian dựng minh họa để gợi không khí thời đại, không phải bản sao chính xác của một cầu tàu cụ thể. Trong không gian ấy, câu chuyện được kể theo hai dòng song song. Dòng thứ nhất là của một nơi chốn: bến cảng và tòa Nhà Rồng, gắn với sự có mặt của người Pháp từ giữa thế kỷ XIX. Dòng thứ hai là của một con người: người thanh niên từ Phan Thiết vào Sài Gòn, học nghề, tìm bạn đồng hành, xin việc rồi rời bến.\n\nBạn có thể bắt đầu với hai câu chuyện về người bạn tên Lê và người phụ bếp Văn Ba, rồi đến bảng mốc thời gian. Tiếp đó là bốn ảnh tư liệu: Nhà Rồng xưa và nay, bến cảng đầu thế kỷ và pho tượng Nguyễn Tất Thành. Cuối cùng là bốn hiện vật: tòa Nhà Rồng, con tàu Amiral Latouche-Tréville, hình ảnh hai bàn tay và bến cảng Sài Gòn. Nếu có dịp đến Thành phố Hồ Chí Minh, bạn có thể tìm lại những địa chỉ thật của câu chuyện. Đó là Bến Nhà Rồng, nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh; nhà số 5 Châu Văn Liêm; và Trường Cao đẳng Kỹ thuật Cao Thắng (xem chuyên đề Bến Nhà Rồng ngày nay – Bảo tàng Hồ Chí Minh).","doc":12},{"loai":"anh","src":"textures/bang_w/G04_0_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Sài Gòn – Bến Nhà Rồng”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Hai bàn tay và một câu hỏi","text":"Điều đọng lại sau bốn tháng ở Sài Gòn không phải một sự kiện ồn ào. Không có lễ tiễn đưa, không có lời tuyên bố nào được ghi lại trên cầu tàu. Chỉ có một người thanh niên lặng lẽ học nghề, lặng lẽ dò hỏi các hãng tàu, lặng lẽ rủ bạn rồi lặng lẽ đi một mình khi bạn không theo. Chính sự bình dị ấy làm nên sức nặng của câu chuyện.\n\nNgười ra đi năm 1911 mang theo hai thứ. Thứ nhất là đôi bàn tay, tức là quyết tâm sống bằng lao động của chính mình ở bất cứ nơi đâu. Thứ hai là một câu hỏi: vì sao nước mình mất, và các nước khác họ làm thế nào. Cả gian trưng bày này được dựng quanh hai thứ hành trang ấy. Đi qua từng bảng, bạn sẽ gặp lại chúng trong lời rủ bạn ở Sài Gòn, trong những đêm đọc sách dưới bếp tàu, trong lá đơn xin học viết từ Marseille. Và bạn sẽ hiểu vì sao một bến cảng thuộc địa lại trở thành nơi khởi đầu của con đường giành độc lập cho cả một dân tộc.","doc":13}],"nguon":["Hồ Chí Minh – Tiểu sử, Bảo tàng Hồ Chí Minh, NXB Chính trị quốc gia, 2008: https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/book/ho-chi-minh/tieu-su-cuoc-doi-va-su-nghiep/ho-chi-minh-tieu-su-bao-tang-ho-chi-minh-nxb-chinh-tri-quoc-gia-ha-noi-nam-2008-20","Tư liệu – Văn kiện Đảng: “Thời niên thiếu của Chủ tịch Hồ Chí Minh (1890 – 1911)”: https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/ho-chi-minh/tieu-su-cuoc-doi-va-su-nghiep/thoi-nien-thieu-cua-chu-tich-ho-chi-minh-1890-1911-3487","Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”","Tạp chí Hồ Chí Minh học – “Về một số con tàu trong những hải trình của Chủ tịch Hồ Chí Minh”: https://tapchihochiminh.hcma.vn/Content/ve-mot-so-con-tau-trong-nhung-hai-trinh-cua-chu-tich-ho-chi-minh-01318","Báo Nhân Dân – “Ngôi trường có hai Chủ tịch nước từng theo học”: https://nhandan.vn/ngoi-truong-co-hai-chu-tich-nuoc-tung-theo-hoc-post548579.html","Báo Thanh Niên – “Ngôi trường người thanh niên yêu nước Nguyễn Tất Thành học tập”: https://thanhnien.vn/ngoi-truong-nguoi-thanh-nien-yeu-nuoc-nguyen-tat-thanh-hoc-tap-185260511200325872.htm"],"doc":[{"t":"Sài Gòn 1911: bốn tháng mở cánh cửa ra biển lớn của người thanh niên Nguyễn Tất Thành. Trưa ngày 5/6/1911, một con tàu buôn Pháp rời Sài Gòn, mang theo một phụ bếp vừa nhận việc hai hôm trước. Không ai trên tàu biết người thanh niên hai mươi mốt tuổi ấy vừa khép lại bốn tháng chuẩn bị lặng lẽ ở thành phố cảng. Vì sao lại là Sài Gòn, vì sao lại là phương Tây, và anh đã mang theo những gì? Gian trưng bày này mở ra từ những câu hỏi ấy."},{"t":"Trưa ngày 5 tháng 6 năm 1911. Trưa ngày 5/6/1911, tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis nhổ neo rời cảng Sài Gòn, xuôi dòng sông ra biển. Con tàu buôn kiêm chở khách ấy chỉ dừng ở Sài Gòn chừng ba ngày, kể từ hôm cập bến 2/6. Trong mấy ngày ngắn ngủi đó, tàu nhận thêm một phụ bếp người Việt, vào làm từ ngày 3/6 với cái tên Văn Ba và đồng lương 45 franc mỗi tháng. Người phụ bếp ấy là Nguyễn Tất Thành, vừa bước sang tuổi hai mươi mốt được mười bảy ngày. Anh không có vé tàu, không có người bảo lãnh, không có tiền dành dụm. Thứ anh mang theo là sức lao động, vốn chữ Hán học từ nhỏ, vốn tiếng Pháp học ở các trường Pháp – Việt, và một câu hỏi lớn về vận mệnh của dân tộc. Chuyến đi bắt đầu từ trưa hôm ấy sẽ kéo dài ba mươi năm. Vì sao một thanh niên có học, từng đứng lớp dạy học trò, lại chọn ra đi theo cách của người làm thuê? Để hiểu điều đó, ta phải trở lại bốn tháng trước, khi anh lần đầu đặt chân đến thành phố cảng lớn nhất xứ Nam Kỳ."},{"t":"Con đường xuôi phương Nam. Con đường dẫn tới Sài Gòn bắt đầu từ Huế. Tháng 9/1906, Nguyễn Tất Thành vào học Trường tiểu học Pháp – Việt ở Huế. Tháng 4/1908, anh tham gia cuộc biểu tình chống thuế của nông dân tỉnh Thừa Thiên. Tháng 9 năm ấy, anh học lớp trung đẳng tại Trường Quốc học Huế. Khoảng tháng 6/1909, anh rời Quốc học, theo cha là cụ Phó bảng Nguyễn Sinh Sắc vào Bình Định, rồi học tiếp ở Trường tiểu học Pháp – Việt Quy Nhơn. Tháng 6/1910, anh hoàn thành chương trình tiểu học thì nghe tin cha bị cách chức tri huyện Bình Khê. Không theo cha trở ra Huế, anh quyết định đi tiếp về phía Nam. Ở Phan Thiết, anh xin làm trợ giáo tại Trường Dục Thanh, trường tư thục do các ông Nguyễn Trọng Lội và Nguyễn Quý Anh lập năm 1907. Anh được giao dạy một số môn và phụ trách hoạt động ngoại khóa. Trong tủ sách của cụ Nguyễn Thông, anh tìm đọc những cuốn sách quý, tiếp cận tư tưởng tiến bộ của các nhà khai sáng Pháp như Rousseau, Voltaire, Montesquieu. Tháng 2/1911, anh rời Phan Thiết vào Sài Gòn. Đó là chặng cuối của con đường bộ, và cũng là cửa ngõ của con đường biển."},{"t":"Thủ phủ của một xứ thuộc địa. Sài Gòn mà Nguyễn Tất Thành đặt chân tới là thành phố do người Pháp quy hoạch lại trên đất Gia Định xưa. Ngày 17/2/1859, quân Pháp đánh chiếm thành Gia Định. Ba năm sau, Hòa ước Nhâm Tuất buộc triều Nguyễn nhượng ba tỉnh miền Đông Nam Kỳ. Sài Gòn trở thành thủ phủ xứ Nam Kỳ thuộc địa. Có thời, đây còn là nơi đặt bộ máy cai trị cao nhất của người Pháp ở Đông Dương, trước khi thủ phủ Liên bang Đông Dương dời ra Hà Nội vào đầu thế kỷ XX. Thành phố sống nhờ dòng sông. Từ khi kênh Suez khánh thành năm 1869, đường biển từ Marseille sang Viễn Đông rút ngắn hẳn, và tàu của các hãng Pháp đi về đều đặn giữa Sài Gòn với chính quốc. Lúa gạo từ đồng bằng sông Cửu Long theo kênh rạch về các nhà máy xay xát ở Chợ Lớn, rồi xuống tàu ra nước ngoài. Dọc bờ sông là kho hàng, xưởng máy, cầu tàu, nơi phu bốc vác làm việc nặng nhọc với đồng lương thấp. Bên cạnh những đại lộ, dinh thự và tiệm cà phê của người Âu là những xóm trọ chật chội của thợ thuyền, người làm thuê. Sự tương phản ấy là bài học đầu tiên mà Sài Gòn dành cho người thanh niên xứ Nghệ."},{"t":"Vì sao là phương Tây?. Những năm đầu thế kỷ XX, các con đường cứu nước của thế hệ đi trước lần lượt gặp bế tắc. Phong trào Đông Du của cụ Phan Bội Châu đưa thanh niên sang Nhật học tập, rồi tan rã khi chính phủ Nhật trục xuất du học sinh Việt Nam theo thỏa thuận với Pháp. Năm 1908, phong trào chống thuế ở Trung Kỳ bị đàn áp; cụ Phan Châu Trinh bị bắt và đày ra Côn Đảo. Theo sách của Trần Dân Tiên, người thanh niên Nguyễn Tất Thành rất khâm phục các bậc tiền bối, nhưng không tán thành cách làm của các cụ. Cụ Phan Bội Châu hy vọng Nhật giúp đuổi Pháp; anh cho rằng điều đó rất nguy hiểm, chẳng khác gì “đưa hổ cửa trước, rước beo cửa sau”. Cụ Phan Châu Trinh chỉ yêu cầu người Pháp thực hiện cải lương; anh cho rằng như thế chẳng khác gì “xin giặc rủ lòng thương”. Cụ Hoàng Hoa Thám trực tiếp đấu tranh chống Pháp nên thực tế hơn, nhưng theo lời người ta kể thì còn nặng cốt cách phong kiến. Từ đó, anh chọn một hướng đi khác: tự mình sang phương Tây, sang chính nước Pháp, để tìm hiểu tận gốc sức mạnh của kẻ đang cai trị dân tộc mình, và cả những khẩu hiệu mà họ vẫn rao giảng."},{"t":"Vào trạc tuổi mười ba, lần đầu tiên tôi được nghe những từ Pháp: Tự do, Bình đẳng, Bác ái… Và từ thuở ấy, tôi rất muốn làm quen với nền văn minh Pháp, muốn tìm xem những gì ẩn giấu đằng sau những từ ấy. — Nguyễn Ái Quốc"},{"t":"Sống giữa những người lao động. Ở Sài Gòn, Nguyễn Tất Thành không phải người xa lạ không nơi nương tựa. Anh ở tạm tại các chi nhánh của Liên Thành, tổ chức kinh doanh do các sĩ phu Duy Tân ở Phan Thiết lập nên: một chi nhánh trên đường Tổng đốc Phương ở Chợ Lớn, một chi nhánh ở Khánh Hội. Khánh Hội là vùng bến bãi bên kia rạch Bến Nghé, cũng là nơi tòa Nhà Rồng soi bóng xuống sông. Những người của Liên Thành cũng chính là những người đã lập trường Dục Thanh, nơi anh vừa dạy học. Từ những căn nhà ấy, anh đi vào các xóm thợ nghèo, lui tới các cửa hàng gần bến cảng để dò hỏi việc làm trên tàu. Anh tận mắt chứng kiến đời sống cực nhọc của người lao động dưới chế độ thuộc địa. Cũng trong những tháng này, anh tìm một người bạn cùng đi, và câu chuyện ấy được kể trong một chuyên đề riêng (xem chuyên đề Lời rủ ra đi và người bạn tên Lê). Bốn tháng ở Sài Gòn vì thế không phải thời gian chờ đợi thụ động. Đó là bốn tháng chuẩn bị, với ba việc phải làm: có chỗ dựa, có một nghề, và tìm được một con tàu sang Pháp."},{"t":"Bạn có biết? Người phỏng vấn Nguyễn Ái Quốc cho tạp chí Ogoniok năm 1923 là Ô-xíp Man-đen-xtam, về sau được coi là một trong những nhà thơ Nga lớn của thế kỷ XX. Bài phỏng vấn ghi lại lời chính Người kể về ước muốn từ thuở thiếu thời: tìm hiểu những gì ẩn sau ba chữ Tự do, Bình đẳng, Bác ái."},{"t":"Một cái nghề ở trường Bá Nghệ. Việc thứ hai là học một cái nghề. Trong khoảng ba tháng đầu năm 1911, Nguyễn Tất Thành theo học Trường Cơ khí Á châu, tên tiếng Pháp là École des Mécaniciens Asiatiques, người Sài Gòn quen gọi là trường Bá Nghệ. Trường được thành lập ngày 20/2/1906, nằm trong khu vực giữa các đường Hàm Nghi, Lê Lợi và chợ Bến Thành ngày nay. Người Pháp lập trường để đào tạo thợ máy và nhân lực cho ngành hàng hải, đáp ứng nhu cầu của bộ máy cai trị thuộc địa và kỹ nghệ địa phương. Với người thanh niên đang tìm đường ra biển, ngôi trường ấy có ý nghĩa rất thiết thực. Theo Hoài Thanh và Thanh Tịnh trong bài “Quê hương và thời niên thiếu”, học ở đây vừa khỏi bị nghi ngờ, vừa có cơm ăn, vừa biết ít nhiều về máy móc. Anh học ở trường khoảng ba tháng rồi rời đi để lo việc xuống tàu. Thời gian ngắn ngủi ấy cho anh thêm một vốn liếng quan trọng bên cạnh chữ nghĩa: sự quen thuộc với xưởng máy, với lao động chân tay và với đời sống của người thợ."},{"t":"Hai hãng tàu và một cơ hội. Việc thứ ba là tìm được một con tàu. Ở cảng Sài Gòn khi ấy, người Việt quen gọi hai hãng tàu Pháp lớn bằng những cái tên dân dã. Hãng Messageries Maritimes, chủ tòa Nhà Rồng, là “hãng Đầu Ngựa”. Hãng Chargeurs Réunis là “hãng Năm Sao”, theo biểu trưng năm ngôi sao trên ống khói tàu. Với một người không có tiền mua vé, cách duy nhất để lên những con tàu ấy là xin làm việc trên tàu, bất kể việc gì. Cơ hội đến rất nhanh. Tàu Amiral Latouche-Tréville của hãng Năm Sao cập Sài Gòn ngày 2/6/1911. Ngày 3/6, anh được nhận làm phụ bếp; trưa ngày 5/6, tàu rời bến. Chỉ vài ngày, nhưng đó là mấy ngày đã được chuẩn bị bằng bốn tháng. Chuyện anh xin việc và những ngày làm phụ bếp trên tàu được kể riêng (xem chuyên đề Người phụ bếp Văn Ba). Còn con tàu neo ở cầu tàu nào của thương cảng hôm ấy, các nhà nghiên cứu vẫn đang bàn luận (xem chuyên đề Bến cảng Sài Gòn). Dù vậy, Bến Nhà Rồng từ lâu đã trở thành biểu tượng của cuộc ra đi, và gian trưng bày này mang tên bến cảng ấy."},{"t":"Bạn có biết? Trường Bá Nghệ còn có một học trò nổi tiếng khác: người thợ máy Tôn Đức Thắng, học khóa 1915 – 1917. Hai học trò của ngôi trường này về sau đều trở thành Chủ tịch nước. Ngày nay, trường mang tên Trường Cao đẳng Kỹ thuật Cao Thắng."},{"t":"Ba mươi năm bắt đầu từ một ngày tháng Sáu. Cuộc ra đi năm 1911 mở đầu ba mươi năm Người bôn ba qua nhiều châu lục. Người làm thuê trên tàu biển, sống giữa những người lao động ở Pháp, ở Anh, ở Mỹ, rồi đến với chủ nghĩa Mác – Lênin. Từ ngày 6/1 đến ngày 7/2/1930, tại Cửu Long, Hương Cảng, Người chủ trì hội nghị hợp nhất các tổ chức cộng sản, thành lập Đảng Cộng sản Việt Nam. Ngày 28/1/1941, Người trở về Tổ quốc qua cột mốc 108 ở biên giới Cao Bằng, rồi lãnh đạo toàn dân tiến tới Cách mạng Tháng Tám. Ngày 2/9/1945, tại Quảng trường Ba Đình, Chủ tịch Hồ Chí Minh đọc bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa. Nhìn lại từ những mốc ấy, trưa ngày 5/6/1911 là khởi điểm của cả một con đường. Người thanh niên ra đi với câu hỏi “họ làm như thế nào”, và trở về với câu trả lời cho dân tộc mình. Bởi vậy, ngày 5/6 hằng năm được kỷ niệm là Ngày Bác Hồ ra đi tìm đường cứu nước, và Bến Nhà Rồng là một trong những địa chỉ tưởng niệm quen thuộc của người dân Thành phố Hồ Chí Minh."},{"t":"Đi qua gian trưng bày. Gian trưng bày tái hiện một bến cảng Sài Gòn đầu thế kỷ XX trong không gian 3D, với kho hàng, thùng gỗ, thùng phuy, đèn treo và những chiếc xe kéo. Đây là không gian dựng minh họa để gợi không khí thời đại, không phải bản sao chính xác của một cầu tàu cụ thể. Trong không gian ấy, câu chuyện được kể theo hai dòng song song. Dòng thứ nhất là của một nơi chốn: bến cảng và tòa Nhà Rồng, gắn với sự có mặt của người Pháp từ giữa thế kỷ XIX. Dòng thứ hai là của một con người: người thanh niên từ Phan Thiết vào Sài Gòn, học nghề, tìm bạn đồng hành, xin việc rồi rời bến. Bạn có thể bắt đầu với hai câu chuyện về người bạn tên Lê và người phụ bếp Văn Ba, rồi đến bảng mốc thời gian. Tiếp đó là bốn ảnh tư liệu: Nhà Rồng xưa và nay, bến cảng đầu thế kỷ và pho tượng Nguyễn Tất Thành. Cuối cùng là bốn hiện vật: tòa Nhà Rồng, con tàu Amiral Latouche-Tréville, hình ảnh hai bàn tay và bến cảng Sài Gòn. Nếu có dịp đến Thành phố Hồ Chí Minh, bạn có thể tìm lại những địa chỉ thật của câu chuyện. Đó là Bến Nhà Rồng, nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh; nhà số 5 Châu Văn Liêm; và Trường Cao đẳng Kỹ thuật Cao Thắng (xem chuyên đề Bến Nhà Rồng ngày nay – Bảo tàng Hồ Chí Minh)."},{"t":"Hai bàn tay và một câu hỏi. Điều đọng lại sau bốn tháng ở Sài Gòn không phải một sự kiện ồn ào. Không có lễ tiễn đưa, không có lời tuyên bố nào được ghi lại trên cầu tàu. Chỉ có một người thanh niên lặng lẽ học nghề, lặng lẽ dò hỏi các hãng tàu, lặng lẽ rủ bạn rồi lặng lẽ đi một mình khi bạn không theo. Chính sự bình dị ấy làm nên sức nặng của câu chuyện. Người ra đi năm 1911 mang theo hai thứ. Thứ nhất là đôi bàn tay, tức là quyết tâm sống bằng lao động của chính mình ở bất cứ nơi đâu. Thứ hai là một câu hỏi: vì sao nước mình mất, và các nước khác họ làm thế nào. Cả gian trưng bày này được dựng quanh hai thứ hành trang ấy. Đi qua từng bảng, bạn sẽ gặp lại chúng trong lời rủ bạn ở Sài Gòn, trong những đêm đọc sách dưới bếp tàu, trong lá đơn xin học viết từ Marseille. Và bạn sẽ hiểu vì sao một bến cảng thuộc địa lại trở thành nơi khởi đầu của con đường giành độc lập cho cả một dân tộc."}],"so_chu":2415},{"i":1,"tieu_de_bang":"Lời rủ ra đi và người bạn tên Lê","tieu_de":"“Anh có yêu nước không?” – cuộc trò chuyện bí mật ở Sài Gòn năm 1911","sapo":"Trước khi bước lên tàu, người thanh niên ấy từng rủ một người bạn cùng đi. Anh không nói ngay dự định, mà hỏi trước hai câu để thử lòng. Khi bạn hỏi lấy đâu ra tiền, anh chỉ giơ hai bàn tay. Câu chuyện được ghi lại trong sách của Trần Dân Tiên cho thấy chuyến đi năm 1911 đã được chuẩn bị bằng cả sự thận trọng lẫn một quyết tâm hiếm có.","bia":{"src":"textures/bai/G04_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Đèn điện, chiếu bóng và ly kem đầu tiên","text":"Câu chuyện bắt đầu trước một tiệm cà phê của người Pháp ở Sài Gòn. Cuốn “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” của Trần Dân Tiên ghi lại lời kể của một người tên Lê. Khi còn học ở trường Chasseloup-Laubat, anh Lê quen một người thanh niên. Vì cùng một lứa tuổi, hai người lập tức trở thành đôi bạn thân.\n\nAnh Lê đưa bạn đến trước tiệm cà phê của người Pháp để xem đèn điện, xem chiếu bóng và máy nước, những thứ trước kia người bạn ấy chưa hề thấy. Một hôm, anh mời bạn ăn kem. Người bạn thấy rất lạ, vì đó là lần đầu tiên anh nếm mùi kem. Những chi tiết nhỏ ấy vẽ nên một bức tranh cụ thể. Người thanh niên hai mươi mốt tuổi đã đọc Rousseau, Montesquieu, đã dạy học ở Phan Thiết, nhưng vẫn lần đầu chạm vào những tiện nghi mà người Pháp mang tới thuộc địa. Câu hỏi anh nói với bạn ít lâu sau cho thấy anh không chỉ tò mò trước những điều mới lạ. Anh muốn biết người ta đã làm như thế nào, và dân tộc mình phải làm gì để tự đứng trên đôi chân của mình.","doc":1},{"loai":"anh","src":"textures/bang_w/G04_1_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời rủ ra đi và người bạn tên Lê”, nhìn từ xa."},{"loai":"doan","tieu_de":"Người kể chuyện và cuốn sách","text":"Người kể chuyện được Trần Dân Tiên giới thiệu là “một vị trí thức ở Sài Gòn”. Sách không cho biết họ tên đầy đủ, quê quán hay cuộc đời về sau của anh. Đến nay, danh tính người bạn tên Lê vẫn chưa được xác định. Trường Chasseloup-Laubat nơi anh theo học là một trường trung học lớn của người Pháp ở Sài Gòn thời ấy.\n\nCuốn sách của Trần Dân Tiên ra đời vào cuối những năm 1940, gồm nhiều mẩu chuyện do những người từng gặp gỡ, làm việc với Người kể lại. Vì là lời kể theo trí nhớ, các đoạn đối thoại trong sách cần được đọc như hồi ức của nhân chứng, không phải như biên bản. Các nhà nghiên cứu vì thế thường đối chiếu sách với những tư liệu khác, như hồ sơ về con tàu năm 1911 hay thư từ do chính Người viết. Câu chuyện với anh Lê chủ yếu được biết đến qua cuốn sách này. Giá trị của nó không nằm ở từng câu chữ, mà ở chỗ khắc họa rất rõ tính cách của người thanh niên sắp ra đi: tò mò, thận trọng, thẳng thắn và tin vào sức mình.","doc":2},{"loai":"ban_co_biet","text":"Sách của Trần Dân Tiên được in lần đầu bằng tiếng Trung tại Thượng Hải năm 1949, do Nhà xuất bản Bát Nguyệt ấn hành. Năm 2023, Nhà xuất bản Chính trị quốc gia Sự thật giới thiệu bản dịch mới từ bản tiếng Trung ấy, với nhiều tư liệu không có trong bản tiếng Việt quen thuộc.","nguon_ten":"Báo Tuổi Trẻ – “Thêm tư liệu mới về Bác Hồ từ cuốn sách của Trần Dân Tiên xuất bản tại Trung Quốc năm 1949” (2023)","doc":3},{"loai":"doan","tieu_de":"Căn nhà của hội Liên Thành","text":"Những tháng ở Sài Gòn, Nguyễn Tất Thành ở tạm tại các chi nhánh của Liên Thành. Liên Thành thương quán được các sĩ phu Duy Tân ở Phan Thiết như Hồ Tá Bang, Nguyễn Trọng Lội, Nguyễn Quý Anh lập năm 1906. Bề ngoài, đó là một cơ sở buôn bán, nổi tiếng với nước mắm. Bên trong, đó là cơ sở kinh tài và nơi liên lạc hợp pháp của những người yêu nước. Cũng chính những người của Liên Thành đã mở trường Dục Thanh, nơi anh vừa dạy học.\n\nChi nhánh ở Chợ Lớn nằm trên đường Tổng đốc Phương, nay là ngôi nhà số 5 Châu Văn Liêm. Đó là một căn nhà phố hai tầng, ngang chừng bốn mét, sâu chừng chín mét, có ban công nhìn ra đường. Nơi đây là chỗ lui tới của nhiều nhà yêu nước trong phong trào Duy Tân. Trong một môi trường như vậy, mọi dự định liên quan đến việc cứu nước đều phải được giữ kín. Người ta có thể gặp nhau, bàn chuyện buôn bán, nhưng những điều hệ trọng chỉ được nói với người thật sự tin cậy. Chính trong bối cảnh ấy, cuộc trò chuyện với người bạn tên Lê đã diễn ra.","doc":4},{"loai":"anh","src":"textures/ht/ht_anh_tuong_nguyen_ai_quoc_nguyen_tat_thanh_nha_tuong_.jpg","chu_thich":"Tượng Nguyễn Tất Thành tại Bến Nhà Rồng, khắc họa người thanh niên trong năm 1911 (ảnh năm 2010).","credit":"Ảnh: vi:User:TDA · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Hai câu hỏi trước một bí mật","text":"Theo lời anh Lê, một hôm người bạn hỏi anh: “Anh Lê, anh có yêu nước không?”. Anh Lê ngạc nhiên và đáp: “Tất nhiên là có chứ!”. Người bạn hỏi tiếp: “Anh có thể giữ bí mật không?”. Chỉ khi nghe câu trả lời “Có”, anh mới nói ra điều mình ấp ủ.\n\nCách mở đầu ấy đáng để dừng lại. Hai câu hỏi không phải lời xã giao, mà là hai điều kiện. Người được rủ đi phải là người yêu nước, vì đây không phải một chuyến du lịch hay một chuyến đi làm ăn. Người ấy cũng phải biết giữ bí mật, vì dưới chế độ thuộc địa, ý định ra nước ngoài tìm đường cứu nước là điều nguy hiểm. Người thanh niên ấy từng tham gia cuộc biểu tình chống thuế ở Thừa Thiên năm 1908. Anh đã chứng kiến các phong trào yêu nước bị đàn áp, các sĩ phu bị bắt, bị đày ra Côn Đảo. Vì thế, có thể hiểu vì sao anh thận trọng đến vậy, ngay cả với một người bạn thân. Sự thận trọng ấy về sau trở thành nếp làm việc của Người suốt những năm hoạt động bí mật ở nước ngoài.","doc":5},{"loai":"trich","text":"Tôi muốn đi ra ngoài, xem nước Pháp và các nước khác. Sau khi xem xét họ làm như thế nào, tôi sẽ trở về giúp đồng bào chúng ta.","nguoi":"Nguyễn Tất Thành (theo lời anh Lê kể trong sách của Trần Dân Tiên)","nguon_ten":"Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”","doc":6},{"loai":"doan","tieu_de":"Nỗi lo ốm đau nơi đất khách","text":"Sau khi nói ra dự định, người bạn thẳng thắn thừa nhận một điều ít ai nói khi rủ bạn phiêu lưu: đi một mình cũng có điều mạo hiểm, chẳng hạn khi đau ốm nơi đất khách. Vì thế anh muốn có người cùng đi, và hỏi anh Lê có muốn đi với mình không.\n\nChi tiết ấy cho thấy người thanh niên nhìn chuyến đi bằng con mắt thực tế. Anh không tô vẽ tương lai, không hứa hẹn thành công; anh nói rõ cả mục đích lẫn rủi ro. Mục đích là xem nước Pháp và các nước khác, xem họ làm như thế nào, rồi trở về giúp đồng bào. Rủi ro là những lúc ốm đau không người chăm sóc ở một nơi xa lạ. Đặt cạnh nhau, hai điều ấy cho thấy quyết định ra đi không phải một phút bốc đồng của tuổi trẻ. Đó là một lựa chọn đã được cân nhắc, trong đó người thanh niên chấp nhận trước những gian khổ mà anh chưa thể lường hết. Những năm sau, ở London, ở Paris, những gian khổ ấy đã đến thật. Anh đã đi qua chúng mà không có người bạn đồng hành từ Sài Gòn (xem chuyên đề Hai bàn tay).","doc":7},{"loai":"anh","src":"textures/bang_w/G04_1_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời rủ ra đi và người bạn tên Lê”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"“Đây, tiền đây”","text":"Anh Lê hưởng ứng, nhưng băn khoăn một điều rất thực tế: hai người lấy đâu ra tiền mà đi? Theo lời anh kể, người bạn vừa nói “Đây, tiền đây” vừa giơ hai bàn tay lên. Rồi anh giải thích: “Chúng ta sẽ làm việc. Chúng ta sẽ làm bất cứ việc gì để sống và để đi”.\n\nCâu trả lời ấy gói trọn kế hoạch của chuyến đi. Phong trào Đông Du trước đó từng dựa vào tiền quyên góp của các nhà yêu nước để đưa thanh niên sang Nhật. Còn hai người bạn trẻ ở Sài Gòn năm 1911 không có học bổng, không có người bảo trợ, không có quỹ quyên góp nào. Họ chỉ có thể đi bằng sức lao động của chính mình. Làm việc gì cũng được, miễn là có chỗ trên một con tàu sang Pháp và có cái ăn ở nơi đến. Hình ảnh đôi bàn tay giơ lên năm ấy về sau trở thành biểu tượng của ý chí tự lực, và được chọn làm một hiện vật của gian trưng bày này (xem chuyên đề Hai bàn tay). Còn với anh Lê, đó là lúc phải quyết định có cùng bước vào cuộc phiêu lưu hay không.","doc":8},{"loai":"doan","tieu_de":"Người ở lại","text":"Theo lời kể, bị cuốn theo lòng hăng hái của bạn, anh Lê nhận lời. Nhưng sau khi suy nghĩ kỹ về một cuộc phiêu lưu đầy bất trắc, anh không đủ can đảm để giữ lời hứa. Vài ngày sau, anh không gặp lại người bạn ấy nữa, và đoán rằng bạn đã đi ngoại quốc.\n\nThật khó trách người ở lại. Năm 1911, rời Sài Gòn sang Pháp mà không có tiền, không biết sẽ làm gì khi đặt chân lên đất lạ, là một quyết định rất ít người dám đưa ra. Chính sự lùi bước của anh Lê càng làm nổi bật quyết tâm của người thanh niên kia. Anh không vì mất bạn đồng hành mà hoãn chuyến đi. Anh tiếp tục lui tới bến cảng, dò hỏi các con tàu, và ngày 3/6/1911 được nhận làm phụ bếp trên tàu Amiral Latouche-Tréville với cái tên Văn Ba (xem chuyên đề Người phụ bếp Văn Ba). Người kể chuyện chỉ biết bạn mình đã đi ngoại quốc. Những điều anh Lê không rõ được Trần Dân Tiên bổ sung qua lời kể của một nhân chứng khác: ông Mai ở Hải Phòng, nhân viên cũ trên một chiếc tàu Pháp.","doc":9},{"loai":"anh","src":"textures/bang_w/G04_1_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Lời rủ ra đi và người bạn tên Lê”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Hai phẩm chất, một con đường","text":"Câu chuyện nhỏ về anh Lê cho thấy hai phẩm chất của người thanh niên hai mươi mốt tuổi. Thứ nhất là sự thận trọng: hỏi trước khi nói, chọn người trước khi rủ, giữ kín dự định cho tới lúc cần. Thứ hai là tinh thần tự lực: không trông vào tiền bạc, người đỡ đầu hay sự giúp đỡ của một nước khác, mà đặt niềm tin vào sức lao động của chính mình.\n\nHai phẩm chất ấy gắn chặt với lựa chọn con đường. Theo sách của Trần Dân Tiên, anh không tán thành việc trông vào Nhật để đuổi Pháp, cũng không tin vào việc xin người Pháp cải lương (xem chuyên đề Sài Gòn – Bến Nhà Rồng). Muốn tự mình đi xem các nước làm như thế nào, trước hết phải tự lo được cho mình ở nơi đất khách. Lời rủ bạn ở Sài Gòn vì thế không chỉ là một lời mời đi xa. Đó là bản phác thảo đầu tiên của cách nghĩ mà Người theo đuổi suốt đời: dựa vào sức mình là chính. Người bạn có thể ở lại, nhưng con đường vẫn phải được đi tiếp.","doc":10},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Ngày nay, căn nhà của chi nhánh Liên Thành ở Chợ Lớn vẫn còn, mang số 5 đường Châu Văn Liêm. Ngày 16/11/1988, Bộ Văn hóa công nhận nơi đây là di tích lịch sử cấp quốc gia, theo Quyết định số 1288-VH/QĐ. Căn nhà nhỏ được bảo tồn và bố trí thành khu trưng bày. Tầng trệt đặt bàn thờ Chủ tịch Hồ Chí Minh cùng ảnh và bản đồ tư liệu; tầng lầu trưng bày hình ảnh, tài liệu về cuộc đời và sự nghiệp của Người. Khu di tích mở cửa hằng ngày đón khách tham quan.\n\nSách của Trần Dân Tiên không cho biết tiệm cà phê nơi anh Lê đưa bạn xem đèn điện nằm ở đâu, cũng không cho biết cuộc trò chuyện về hai bàn tay diễn ra ở góc phố nào. Nhưng người đến thăm căn nhà số 5 Châu Văn Liêm có thể hình dung những ngày người thanh niên ở đây, đi về giữa Chợ Lớn, trường học nghề và bến cảng. Từ căn nhà ấy ra đến bờ sông Sài Gòn chỉ là một quãng đường trong thành phố. Nhưng quãng đường từ lời rủ bạn đến bước chân lên tàu, người thanh niên đã phải đi một mình.","doc":11},{"loai":"ban_co_biet","text":"Liên Thành, nơi Nguyễn Tất Thành ở tạm những ngày ở Sài Gòn, vốn là cơ sở làm nước mắm của các sĩ phu Duy Tân Phan Thiết, lập năm 1906. Thương hiệu nước mắm Liên Thành vẫn còn đến ngày nay.","nguon_ten":"Doanh nhân Sài Gòn – “Doanh nhân Hồ Tá Bang: Một trụ cột của phong trào Duy Tân và luôn tìm hướng mở rộng thị trường”","doc":12}],"nguon":["Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”","Hồ Chí Minh – Tiểu sử, Bảo tàng Hồ Chí Minh, NXB Chính trị quốc gia, 2008: https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/book/ho-chi-minh/tieu-su-cuoc-doi-va-su-nghiep/ho-chi-minh-tieu-su-bao-tang-ho-chi-minh-nxb-chinh-tri-quoc-gia-ha-noi-nam-2008-20","Báo Tuổi Trẻ – “Thêm tư liệu mới về Bác Hồ từ cuốn sách của Trần Dân Tiên xuất bản tại Trung Quốc năm 1949”: https://tuoitre.vn/them-tu-lieu-moi-ve-bac-ho-tu-cuon-sach-cua-tran-dan-tien-xuat-ban-tai-trung-quoc-nam-1949-20231023194401302.htm","Doanh nhân Sài Gòn – “Doanh nhân Hồ Tá Bang: Một trụ cột của phong trào Duy Tân…”: https://htv.vn/doanhnhansaigon/doanh-nhan-ho-ta-bang-mot-tru-cot-cua-phong-trao-duy-tan-va-luon-tim-huong-mo-rong-thi-truong-313229.html","Quận 5 – Nhà lưu niệm Bác Hồ, số 5 Châu Văn Liêm: https://quan5xinchao.vn/en/nha-luu-niem-bac-ho/","Văn hóa & Phát triển – “Giá trị lịch sử từ Di tích quốc gia Nhà số 5 Châu Văn Liêm”: https://vanhoavaphattrien.vn/tp-ho-chi-minh-gia-tri-lich-su-tu-di-tich-quoc-gia-nha-so-5-chau-van-liem-a33966.html"],"doc":[{"t":"“Anh có yêu nước không?” – cuộc trò chuyện bí mật ở Sài Gòn năm 1911. Trước khi bước lên tàu, người thanh niên ấy từng rủ một người bạn cùng đi. Anh không nói ngay dự định, mà hỏi trước hai câu để thử lòng. Khi bạn hỏi lấy đâu ra tiền, anh chỉ giơ hai bàn tay. Câu chuyện được ghi lại trong sách của Trần Dân Tiên cho thấy chuyến đi năm 1911 đã được chuẩn bị bằng cả sự thận trọng lẫn một quyết tâm hiếm có."},{"t":"Đèn điện, chiếu bóng và ly kem đầu tiên. Câu chuyện bắt đầu trước một tiệm cà phê của người Pháp ở Sài Gòn. Cuốn “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch” của Trần Dân Tiên ghi lại lời kể của một người tên Lê. Khi còn học ở trường Chasseloup-Laubat, anh Lê quen một người thanh niên. Vì cùng một lứa tuổi, hai người lập tức trở thành đôi bạn thân. Anh Lê đưa bạn đến trước tiệm cà phê của người Pháp để xem đèn điện, xem chiếu bóng và máy nước, những thứ trước kia người bạn ấy chưa hề thấy. Một hôm, anh mời bạn ăn kem. Người bạn thấy rất lạ, vì đó là lần đầu tiên anh nếm mùi kem. Những chi tiết nhỏ ấy vẽ nên một bức tranh cụ thể. Người thanh niên hai mươi mốt tuổi đã đọc Rousseau, Montesquieu, đã dạy học ở Phan Thiết, nhưng vẫn lần đầu chạm vào những tiện nghi mà người Pháp mang tới thuộc địa. Câu hỏi anh nói với bạn ít lâu sau cho thấy anh không chỉ tò mò trước những điều mới lạ. Anh muốn biết người ta đã làm như thế nào, và dân tộc mình phải làm gì để tự đứng trên đôi chân của mình."},{"t":"Người kể chuyện và cuốn sách. Người kể chuyện được Trần Dân Tiên giới thiệu là “một vị trí thức ở Sài Gòn”. Sách không cho biết họ tên đầy đủ, quê quán hay cuộc đời về sau của anh. Đến nay, danh tính người bạn tên Lê vẫn chưa được xác định. Trường Chasseloup-Laubat nơi anh theo học là một trường trung học lớn của người Pháp ở Sài Gòn thời ấy. Cuốn sách của Trần Dân Tiên ra đời vào cuối những năm 1940, gồm nhiều mẩu chuyện do những người từng gặp gỡ, làm việc với Người kể lại. Vì là lời kể theo trí nhớ, các đoạn đối thoại trong sách cần được đọc như hồi ức của nhân chứng, không phải như biên bản. Các nhà nghiên cứu vì thế thường đối chiếu sách với những tư liệu khác, như hồ sơ về con tàu năm 1911 hay thư từ do chính Người viết. Câu chuyện với anh Lê chủ yếu được biết đến qua cuốn sách này. Giá trị của nó không nằm ở từng câu chữ, mà ở chỗ khắc họa rất rõ tính cách của người thanh niên sắp ra đi: tò mò, thận trọng, thẳng thắn và tin vào sức mình."},{"t":"Bạn có biết? Sách của Trần Dân Tiên được in lần đầu bằng tiếng Trung tại Thượng Hải năm 1949, do Nhà xuất bản Bát Nguyệt ấn hành. Năm 2023, Nhà xuất bản Chính trị quốc gia Sự thật giới thiệu bản dịch mới từ bản tiếng Trung ấy, với nhiều tư liệu không có trong bản tiếng Việt quen thuộc."},{"t":"Căn nhà của hội Liên Thành. Những tháng ở Sài Gòn, Nguyễn Tất Thành ở tạm tại các chi nhánh của Liên Thành. Liên Thành thương quán được các sĩ phu Duy Tân ở Phan Thiết như Hồ Tá Bang, Nguyễn Trọng Lội, Nguyễn Quý Anh lập năm 1906. Bề ngoài, đó là một cơ sở buôn bán, nổi tiếng với nước mắm. Bên trong, đó là cơ sở kinh tài và nơi liên lạc hợp pháp của những người yêu nước. Cũng chính những người của Liên Thành đã mở trường Dục Thanh, nơi anh vừa dạy học. Chi nhánh ở Chợ Lớn nằm trên đường Tổng đốc Phương, nay là ngôi nhà số 5 Châu Văn Liêm. Đó là một căn nhà phố hai tầng, ngang chừng bốn mét, sâu chừng chín mét, có ban công nhìn ra đường. Nơi đây là chỗ lui tới của nhiều nhà yêu nước trong phong trào Duy Tân. Trong một môi trường như vậy, mọi dự định liên quan đến việc cứu nước đều phải được giữ kín. Người ta có thể gặp nhau, bàn chuyện buôn bán, nhưng những điều hệ trọng chỉ được nói với người thật sự tin cậy. Chính trong bối cảnh ấy, cuộc trò chuyện với người bạn tên Lê đã diễn ra."},{"t":"Hai câu hỏi trước một bí mật. Theo lời anh Lê, một hôm người bạn hỏi anh: “Anh Lê, anh có yêu nước không?”. Anh Lê ngạc nhiên và đáp: “Tất nhiên là có chứ!”. Người bạn hỏi tiếp: “Anh có thể giữ bí mật không?”. Chỉ khi nghe câu trả lời “Có”, anh mới nói ra điều mình ấp ủ. Cách mở đầu ấy đáng để dừng lại. Hai câu hỏi không phải lời xã giao, mà là hai điều kiện. Người được rủ đi phải là người yêu nước, vì đây không phải một chuyến du lịch hay một chuyến đi làm ăn. Người ấy cũng phải biết giữ bí mật, vì dưới chế độ thuộc địa, ý định ra nước ngoài tìm đường cứu nước là điều nguy hiểm. Người thanh niên ấy từng tham gia cuộc biểu tình chống thuế ở Thừa Thiên năm 1908. Anh đã chứng kiến các phong trào yêu nước bị đàn áp, các sĩ phu bị bắt, bị đày ra Côn Đảo. Vì thế, có thể hiểu vì sao anh thận trọng đến vậy, ngay cả với một người bạn thân. Sự thận trọng ấy về sau trở thành nếp làm việc của Người suốt những năm hoạt động bí mật ở nước ngoài."},{"t":"Tôi muốn đi ra ngoài, xem nước Pháp và các nước khác. Sau khi xem xét họ làm như thế nào, tôi sẽ trở về giúp đồng bào chúng ta. — Nguyễn Tất Thành (theo lời anh Lê kể trong sách của Trần Dân Tiên)"},{"t":"Nỗi lo ốm đau nơi đất khách. Sau khi nói ra dự định, người bạn thẳng thắn thừa nhận một điều ít ai nói khi rủ bạn phiêu lưu: đi một mình cũng có điều mạo hiểm, chẳng hạn khi đau ốm nơi đất khách. Vì thế anh muốn có người cùng đi, và hỏi anh Lê có muốn đi với mình không. Chi tiết ấy cho thấy người thanh niên nhìn chuyến đi bằng con mắt thực tế. Anh không tô vẽ tương lai, không hứa hẹn thành công; anh nói rõ cả mục đích lẫn rủi ro. Mục đích là xem nước Pháp và các nước khác, xem họ làm như thế nào, rồi trở về giúp đồng bào. Rủi ro là những lúc ốm đau không người chăm sóc ở một nơi xa lạ. Đặt cạnh nhau, hai điều ấy cho thấy quyết định ra đi không phải một phút bốc đồng của tuổi trẻ. Đó là một lựa chọn đã được cân nhắc, trong đó người thanh niên chấp nhận trước những gian khổ mà anh chưa thể lường hết. Những năm sau, ở London, ở Paris, những gian khổ ấy đã đến thật. Anh đã đi qua chúng mà không có người bạn đồng hành từ Sài Gòn (xem chuyên đề Hai bàn tay)."},{"t":"“Đây, tiền đây”. Anh Lê hưởng ứng, nhưng băn khoăn một điều rất thực tế: hai người lấy đâu ra tiền mà đi? Theo lời anh kể, người bạn vừa nói “Đây, tiền đây” vừa giơ hai bàn tay lên. Rồi anh giải thích: “Chúng ta sẽ làm việc. Chúng ta sẽ làm bất cứ việc gì để sống và để đi”. Câu trả lời ấy gói trọn kế hoạch của chuyến đi. Phong trào Đông Du trước đó từng dựa vào tiền quyên góp của các nhà yêu nước để đưa thanh niên sang Nhật. Còn hai người bạn trẻ ở Sài Gòn năm 1911 không có học bổng, không có người bảo trợ, không có quỹ quyên góp nào. Họ chỉ có thể đi bằng sức lao động của chính mình. Làm việc gì cũng được, miễn là có chỗ trên một con tàu sang Pháp và có cái ăn ở nơi đến. Hình ảnh đôi bàn tay giơ lên năm ấy về sau trở thành biểu tượng của ý chí tự lực, và được chọn làm một hiện vật của gian trưng bày này (xem chuyên đề Hai bàn tay). Còn với anh Lê, đó là lúc phải quyết định có cùng bước vào cuộc phiêu lưu hay không."},{"t":"Người ở lại. Theo lời kể, bị cuốn theo lòng hăng hái của bạn, anh Lê nhận lời. Nhưng sau khi suy nghĩ kỹ về một cuộc phiêu lưu đầy bất trắc, anh không đủ can đảm để giữ lời hứa. Vài ngày sau, anh không gặp lại người bạn ấy nữa, và đoán rằng bạn đã đi ngoại quốc. Thật khó trách người ở lại. Năm 1911, rời Sài Gòn sang Pháp mà không có tiền, không biết sẽ làm gì khi đặt chân lên đất lạ, là một quyết định rất ít người dám đưa ra. Chính sự lùi bước của anh Lê càng làm nổi bật quyết tâm của người thanh niên kia. Anh không vì mất bạn đồng hành mà hoãn chuyến đi. Anh tiếp tục lui tới bến cảng, dò hỏi các con tàu, và ngày 3/6/1911 được nhận làm phụ bếp trên tàu Amiral Latouche-Tréville với cái tên Văn Ba (xem chuyên đề Người phụ bếp Văn Ba). Người kể chuyện chỉ biết bạn mình đã đi ngoại quốc. Những điều anh Lê không rõ được Trần Dân Tiên bổ sung qua lời kể của một nhân chứng khác: ông Mai ở Hải Phòng, nhân viên cũ trên một chiếc tàu Pháp."},{"t":"Hai phẩm chất, một con đường. Câu chuyện nhỏ về anh Lê cho thấy hai phẩm chất của người thanh niên hai mươi mốt tuổi. Thứ nhất là sự thận trọng: hỏi trước khi nói, chọn người trước khi rủ, giữ kín dự định cho tới lúc cần. Thứ hai là tinh thần tự lực: không trông vào tiền bạc, người đỡ đầu hay sự giúp đỡ của một nước khác, mà đặt niềm tin vào sức lao động của chính mình. Hai phẩm chất ấy gắn chặt với lựa chọn con đường. Theo sách của Trần Dân Tiên, anh không tán thành việc trông vào Nhật để đuổi Pháp, cũng không tin vào việc xin người Pháp cải lương (xem chuyên đề Sài Gòn – Bến Nhà Rồng). Muốn tự mình đi xem các nước làm như thế nào, trước hết phải tự lo được cho mình ở nơi đất khách. Lời rủ bạn ở Sài Gòn vì thế không chỉ là một lời mời đi xa. Đó là bản phác thảo đầu tiên của cách nghĩ mà Người theo đuổi suốt đời: dựa vào sức mình là chính. Người bạn có thể ở lại, nhưng con đường vẫn phải được đi tiếp."},{"t":"Dấu tích hôm nay. Ngày nay, căn nhà của chi nhánh Liên Thành ở Chợ Lớn vẫn còn, mang số 5 đường Châu Văn Liêm. Ngày 16/11/1988, Bộ Văn hóa công nhận nơi đây là di tích lịch sử cấp quốc gia, theo Quyết định số 1288-VH/QĐ. Căn nhà nhỏ được bảo tồn và bố trí thành khu trưng bày. Tầng trệt đặt bàn thờ Chủ tịch Hồ Chí Minh cùng ảnh và bản đồ tư liệu; tầng lầu trưng bày hình ảnh, tài liệu về cuộc đời và sự nghiệp của Người. Khu di tích mở cửa hằng ngày đón khách tham quan. Sách của Trần Dân Tiên không cho biết tiệm cà phê nơi anh Lê đưa bạn xem đèn điện nằm ở đâu, cũng không cho biết cuộc trò chuyện về hai bàn tay diễn ra ở góc phố nào. Nhưng người đến thăm căn nhà số 5 Châu Văn Liêm có thể hình dung những ngày người thanh niên ở đây, đi về giữa Chợ Lớn, trường học nghề và bến cảng. Từ căn nhà ấy ra đến bờ sông Sài Gòn chỉ là một quãng đường trong thành phố. Nhưng quãng đường từ lời rủ bạn đến bước chân lên tàu, người thanh niên đã phải đi một mình."},{"t":"Bạn có biết? Liên Thành, nơi Nguyễn Tất Thành ở tạm những ngày ở Sài Gòn, vốn là cơ sở làm nước mắm của các sĩ phu Duy Tân Phan Thiết, lập năm 1906. Thương hiệu nước mắm Liên Thành vẫn còn đến ngày nay."}],"so_chu":2072},{"i":2,"tieu_de_bang":"Người phụ bếp Văn Ba","tieu_de":"Người phụ bếp tên Ba: từ bốn giờ sáng dưới bếp tàu đến quán cà phê ở Marseille","sapo":"Người cùng tàu nhớ anh chỉ lĩnh mười quan; các nhà nghiên cứu ghi bốn mươi lăm franc mỗi tháng. Dù con số nào đúng, đó vẫn là một đồng lương ít ỏi. Người phụ bếp trẻ làm từ bốn giờ sáng đến chín giờ tối, rồi thức tới khuya để đọc và viết. Ba mươi mốt ngày sau, ở Marseille, lần đầu tiên anh được một người Pháp gọi bằng “ông”.","bia":{"src":"textures/bai/G04_v4.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một buổi trưa, một người trai trẻ lên tàu","text":"Trong sách của Trần Dân Tiên, những ngày đầu của người phụ bếp được kể qua lời ông Mai ở Hải Phòng, nhân viên cũ trên một chiếc tàu Pháp. Ông làm việc ở phòng ăn của các sĩ quan trên tàu. Theo lời ông, một buổi trưa, một người trai trẻ lên tàu. Sau một phút ngập ngừng, anh ta hỏi xin việc. Những người trên tàu trả lời là không có việc, và dù có đi nữa, họ cũng không có quyền nhận anh.\n\nÔng Mai kể rằng không hiểu vì sao ông thấy thương người thanh niên, và bảo: “Đi theo tôi”. Chủ tàu hỏi: “Anh có thể làm việc gì?”. Chàng trai trả lời: “Tôi có thể làm bất cứ việc gì!”. Anh được nhận làm phụ bếp, và xưng tên là Ba. Ông Mai nhớ rằng vì ông đã giúp anh việc nhỏ ấy, anh rất thân với ông. Câu trả lời “bất cứ việc gì” trên con tàu hôm ấy chính là điều anh đã nói với người bạn tên Lê ở Sài Gòn, nay đã thành hành động (xem chuyên đề Lời rủ ra đi và người bạn tên Lê). Từ giây phút đó, người học trò Quốc học năm nào bước vào đời một người làm thuê trên biển.","doc":1},{"loai":"doan","tieu_de":"Văn Ba trong tư liệu về con tàu","text":"Lời kể của ông Mai có một chỗ không chắc chắn. Chính ông nói việc ấy xảy ra “vào khoảng cuối năm 1911 hay 1912”, và thừa nhận không nhớ đúng nữa. Các nhà nghiên cứu vì thế đối chiếu với những tư liệu khác. Theo Tạp chí Hồ Chí Minh học của Học viện Chính trị quốc gia Hồ Chí Minh, ngày 3/6/1911, Nguyễn Tất Thành chính thức xuống tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis. Anh làm phụ bếp với cái tên mới là Văn Ba, lương 45 franc mỗi tháng. Theo nhà nghiên cứu Nguyễn Đình Đầu, anh đến xin việc tại văn phòng hãng tàu trên lầu một quán cà phê La Rotonde, số 2 đường Catinat.\n\nMột bằng chứng quan trọng khác do chính tay Người viết. Trong lá đơn đề ngày 15/9/1911 gửi Tổng thống Pháp từ Marseille, anh cho biết mình đang làm công cho hãng Chargeurs Réunis, trên tàu Amiral Latouche-Tréville, để kiếm sống (xem chuyên đề Mốc thời gian). Như vậy, con tàu và công việc của người phụ bếp đã được xác nhận bằng giấy tờ. Còn lời ông Mai, dù mơ hồ về năm tháng, vẫn là nguồn hiếm hoi kể lại đời sống hằng ngày của người phụ bếp ấy.","doc":2},{"loai":"anh","src":"textures/bang_w/G04_2_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Người phụ bếp Văn Ba”, nhìn từ xa."},{"loai":"doan","tieu_de":"Từ bốn giờ sáng","text":"Công việc của người phụ bếp bắt đầu từ bốn giờ sáng. Theo lời ông Mai, anh Ba phải quét dọn sạch sẽ nhà bếp, đốt lửa, khuân than, rồi xuống hầm tàu lấy rau, thịt cá, nước đá. Dưới bếp rất nóng, trong hầm rất rét. Nặng nhọc nhất là lúc phải vác một bao nặng leo lên những bậc thang trong khi tàu tròng trành giữa sóng. Xong những việc ấy lại dọn cơm cho những người đầu bếp, rồi nhặt rau, rửa nồi chảo.\n\nNhững cái nồi trong bếp tàu cao quá, anh phải leo lên ghế mới chùi được. Suốt ngày, trong bếp luôn vang lên những tiếng gọi: “Ba, đem nước đây! Ba, dọn chảo đi!”. Người thanh niên từng là học trò Trường Quốc học Huế, từng là thầy giáo ở Phan Thiết, giờ làm những việc vặt vất vả nhất trong bếp của một con tàu viễn dương. Anh không có bằng cấp nào để dựa vào, chỉ có sức bền và ý chí. Theo ông Mai, người phụ bếp ấy không bao giờ nói tục, và vì vậy được tất cả anh em yêu mến.","doc":3},{"loai":"trich","text":"Mỗi ngày, chín giờ tối, công việc mới xong. Anh Ba mệt lử. Nhưng trong khi chúng tôi nghỉ hoặc đánh bài, anh Ba đọc hay viết đến mười một giờ hoặc nửa đêm.","nguoi":"Ông Mai, người từng làm việc cùng tàu với anh Ba (lời kể trong sách của Trần Dân Tiên)","nguon_ten":"Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”","doc":4},{"loai":"doan","tieu_de":"Những đêm đọc và viết","text":"Mười bảy tiếng làm việc mỗi ngày, từ bốn giờ sáng đến chín giờ tối, đủ vắt kiệt sức một người trai trẻ. Vậy mà theo ông Mai, khi anh em trong bếp nghỉ ngơi hay đánh bài, anh Ba vẫn ngồi đọc hoặc viết tới khuya. Anh còn giúp những người bạn mù chữ của ông Mai viết thư về cho gia đình họ.\n\nChi tiết ấy nói nhiều về con người. Từ nhỏ, anh đã học chữ Hán; ở các trường Pháp – Việt, anh học chữ quốc ngữ và tiếng Pháp. Trên con tàu, vốn chữ ấy không đem lại cho anh một đồng lương cao hơn. Nhưng anh dùng nó để giúp những người lao động không biết chữ gửi lời thăm hỏi về quê nhà. Còn những giờ đọc và viết lúc nửa đêm là cách anh tiếp tục tự học, khi không còn trường lớp nào. Đó cũng là thói quen theo Người suốt đời: học ở mọi nơi, trong mọi hoàn cảnh, tranh thủ mọi thời gian có được. Con tàu buôn vì thế trở thành lớp học đầu tiên của cuộc đời lao động. Ở đó, người học trò cũ học về biển cả, và trên hết là về những người làm thuê.","doc":5},{"loai":"ban_co_biet","text":"Theo ông Mai, khi tàu đến Marseille, mỗi nhân viên Việt Nam lĩnh từ một trăm đến hai trăm quan, thêm tiền thưởng của hành khách; riêng anh Ba là phụ bếp chỉ được mười quan. Con số này khác với mức 45 franc mỗi tháng mà các nhà nghiên cứu nêu khi viết về con tàu.","nguon_ten":"Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”; Tạp chí Hồ Chí Minh học – “Về một số con tàu trong những hải trình của Chủ tịch Hồ Chí Minh”","doc":6},{"loai":"doan","tieu_de":"Những bến cảng dọc đường","text":"Trưa ngày 5/6/1911, tàu rời Sài Gòn. Theo Tạp chí Hồ Chí Minh học, hải trình đưa người phụ bếp qua Singapore, Colombo trên đảo Tích Lan, nay là Sri Lanka, rồi Djibouti gần cửa biển Đỏ, vượt kênh Suez, ghé Port Said của Ai Cập. Ngày 6/7/1911, sau ba mươi mốt ngày, tàu cập cảng Marseille.\n\nKhông có tư liệu cho biết người phụ bếp đã được lên bờ ở những bến nào. Nhưng những bến ấy có một điểm chung đáng chú ý. Singapore và Colombo khi ấy thuộc quyền cai trị của nước Anh. Djibouti là thuộc địa của Pháp. Ai Cập, nơi có Port Said, đang bị quân Anh chiếm đóng. Dọc con đường từ Sài Gòn sang châu Âu, người thanh niên đi qua những miền đất cũng như quê hương anh, đều nằm dưới quyền các cường quốc châu Âu. Một năm sau, trên con tàu của hãng Chargeurs Réunis đi vòng quanh châu Phi, Người tận mắt chứng kiến cảnh lao động khổ cực của người dân thuộc địa ở Dakar và nhiều bến cảng khác. Hành trình năm 1911 là bước đầu của cái nhìn rộng mở ấy: nỗi khổ của người dân mất nước không chỉ riêng ở Việt Nam.","doc":7},{"loai":"anh","src":"textures/bang_w/G04_2_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Người phụ bếp Văn Ba”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Lần đầu được gọi bằng “ông”","text":"Ở Marseille, các nhân viên trên tàu lĩnh lương. Ông Mai kể rằng ông cho anh Ba mượn một bộ quần áo, rồi hai người cùng đến một tiệm cà phê trên đường La Canebière, đại lộ nổi tiếng của thành phố cảng này. Đó là lần đầu tiên anh Ba vào tiệm cà phê, và cũng là lần đầu tiên có người Pháp gọi anh bằng “ông”.\n\nChữ “ông” ấy, với người Pháp ở Marseille, có lẽ chỉ là phép lịch sự thông thường khi tiếp khách. Nhưng với một người Việt từ thuộc địa sang, đó là một trải nghiệm lạ lùng. Ở Sài Gòn, giữa người Pháp và người bản xứ là khoảng cách của kẻ cai trị và người bị trị. Anh Ba nhận xét với ông Mai rằng người Pháp ở Pháp tốt, lễ phép hơn người Pháp ở Đông Dương. Một câu nói giản dị, nhưng chứa đựng một phát hiện quan trọng. Thái độ khinh miệt mà người dân thuộc địa phải chịu hằng ngày không phải bản chất của cả một dân tộc. Nó gắn với chính chế độ thực dân, và với những con người mà chế độ ấy đưa sang cai trị xứ người.","doc":8},{"loai":"doan","tieu_de":"Tại sao người Pháp không “khai hóa” đồng bào của họ?","text":"Marseille còn cho người phụ bếp thấy những điều mà sách vở ở thuộc địa không nói tới. Trông thấy những cô gái điếm lên tàu làm tiền, anh hỏi ông Mai: tại sao người Pháp không “khai hóa” đồng bào của họ trước khi đi “khai hóa” chúng ta? Câu hỏi ấy nhắm thẳng vào lá cờ mà chế độ thuộc địa vẫn giương lên: sứ mệnh “khai hóa văn minh” cho các dân tộc bị trị.\n\nTheo sách của Trần Dân Tiên, anh còn ngạc nhiên nhận ra rằng ở Pháp cũng có người nghèo như bên ta, và nói với ông Mai rằng cũng có những người Pháp tốt. Hai phát hiện đi cùng nhau: người lao động Pháp cũng nghèo khổ, và nhân dân Pháp khác với bọn thực dân. Đó là nền móng của một nhận thức theo Người suốt cuộc đời hoạt động: phân biệt nhân dân lao động các nước với những kẻ áp bức. Chín năm sau, tháng 12/1920, tại Đại hội Tours, Nguyễn Ái Quốc bỏ phiếu tán thành gia nhập Quốc tế Cộng sản. Người trở thành một trong những người tham gia sáng lập Đảng Cộng sản Pháp. Con đường ấy có dấu ấn của những quan sát đầu tiên trên bến cảng Marseille.","doc":9},{"loai":"anh","src":"textures/bai/G04_v5.jpg","chu_thich":"Không gian 3D tái hiện Sài Gòn – Bến Nhà Rồng năm 1911.","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},{"loai":"doan","tieu_de":"Sau Marseille","text":"Từ Marseille, tàu Amiral Latouche-Tréville đi tiếp lên cảng Le Havre, tới nơi ngày 15/7/1911, rồi kết thúc hải trình ở Dunkerque ngày 26/7. Tính từ Sài Gòn đến Le Havre, chuyến đi kéo dài bốn mươi ngày. Những tháng tiếp theo, người thanh niên vẫn gắn với biển và với đời làm thuê. Ngày 15/9/1911, từ Marseille, anh viết đơn xin vào học Trường Thuộc địa, nhưng không được chấp nhận.\n\nSách của Trần Dân Tiên còn kể một quãng thời gian anh sống ở Sainte-Adresse, vùng ngoại ô của Le Havre, trong một biệt thự có vườn hoa. Lúc rảnh, anh chăm bón hoa cùng người làm vườn, hoặc giở xem những tờ báo có ảnh trong tủ sách. Rồi một buổi chiều, người chủ nhà đi làm về báo tin có một chuyến tàu đi vòng quanh châu Phi. Năm 1912, anh làm việc trên tàu của hãng Chargeurs Réunis trong chuyến đi ấy. Người phụ bếp Văn Ba năm nào đã thật sự bước vào đời một người lao động trên biển, nhiều năm trước khi Người sống và hoạt động ở London rồi Paris (xem chuyên đề Hai bàn tay).","doc":10},{"loai":"ban_co_biet","text":"Theo nhà nghiên cứu Nguyễn Đình Đầu, năm 1911 tàu Amiral Latouche-Tréville do thuyền trưởng Maisen chỉ huy, với đoàn thủy thủ 69 người. Tàu từ Hải Phòng vào, cập Sài Gòn ngày 2/6 và rời đi trưa 5/6.","nguon_ten":"Báo Thanh Niên – “Nơi Bác ra đi tìm đường cứu nước” (trích “Tạp ghi Việt Sử Địa” của Nguyễn Đình Đầu)","doc":11},{"loai":"anh","src":"textures/bang_w/G04_2_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Người phụ bếp Văn Ba”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Bài học đầu tiên của người lao động","text":"Nhìn lại, ba mươi mốt ngày trên tàu Amiral Latouche-Tréville là ba mươi mốt ngày Nguyễn Tất Thành học những điều không có trong sách vở. Anh học cái mệt của người làm thuê, học sự tương trợ giữa những người lao động, học cách nhìn một thế giới rộng lớn hơn nhiều so với xứ thuộc địa. Anh cũng thấy rằng học vấn không quyết định chỗ đứng của một người dân mất nước. Trên tàu, người học trò Quốc học chỉ là một phụ bếp với đồng lương ít ỏi.\n\nCái tên Văn Ba là một trong những tên gọi đầu tiên trong rất nhiều bí danh, bút danh của Người trong những năm hoạt động ở nước ngoài (xem chuyên đề Tượng Nguyễn Tất Thành tại Bến Nhà Rồng). Hôm nay, câu chuyện người phụ bếp được kể lại tại Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh ở Bến Nhà Rồng. Tại đây, hành trình ra đi tìm đường cứu nước năm 1911 là nội dung trưng bày trọng tâm. Trong gian trưng bày này, bạn có thể dừng lại bên con tàu và bến cảng được dựng lại, và hình dung người phụ bếp trẻ nhìn Sài Gòn lùi dần phía sau.","doc":12}],"nguon":["Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”","Tạp chí Hồ Chí Minh học – “Về một số con tàu trong những hải trình của Chủ tịch Hồ Chí Minh”: https://tapchihochiminh.hcma.vn/Content/ve-mot-so-con-tau-trong-nhung-hai-trinh-cua-chu-tich-ho-chi-minh-01318","Báo Thanh Niên – “Nơi Bác ra đi tìm đường cứu nước” (Nguyễn Đình Đầu): https://thanhnien.vn/noi-bac-ra-di-tim-duong-cuu-nuoc-185241009213949499.htm","Hồ Chí Minh – Tiểu sử, Bảo tàng Hồ Chí Minh, NXB Chính trị quốc gia, 2008: https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/book/ho-chi-minh/tieu-su-cuoc-doi-va-su-nghiep/ho-chi-minh-tieu-su-bao-tang-ho-chi-minh-nxb-chinh-tri-quoc-gia-ha-noi-nam-2008-20","William J. Duiker, “Ho Chi Minh: A Life” (2000) – về lá đơn ngày 15/9/1911, bản dịch đăng tại: https://thehehochiminh.wordpress.com/2010/01/03/1911_lathu_truong_thuocdia/","Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh: Giới thiệu bảo tàng: https://bennharong.vn/gioi-thieu-bao-tang"],"doc":[{"t":"Người phụ bếp tên Ba: từ bốn giờ sáng dưới bếp tàu đến quán cà phê ở Marseille. Người cùng tàu nhớ anh chỉ lĩnh mười quan; các nhà nghiên cứu ghi bốn mươi lăm franc mỗi tháng. Dù con số nào đúng, đó vẫn là một đồng lương ít ỏi. Người phụ bếp trẻ làm từ bốn giờ sáng đến chín giờ tối, rồi thức tới khuya để đọc và viết. Ba mươi mốt ngày sau, ở Marseille, lần đầu tiên anh được một người Pháp gọi bằng “ông”."},{"t":"Một buổi trưa, một người trai trẻ lên tàu. Trong sách của Trần Dân Tiên, những ngày đầu của người phụ bếp được kể qua lời ông Mai ở Hải Phòng, nhân viên cũ trên một chiếc tàu Pháp. Ông làm việc ở phòng ăn của các sĩ quan trên tàu. Theo lời ông, một buổi trưa, một người trai trẻ lên tàu. Sau một phút ngập ngừng, anh ta hỏi xin việc. Những người trên tàu trả lời là không có việc, và dù có đi nữa, họ cũng không có quyền nhận anh. Ông Mai kể rằng không hiểu vì sao ông thấy thương người thanh niên, và bảo: “Đi theo tôi”. Chủ tàu hỏi: “Anh có thể làm việc gì?”. Chàng trai trả lời: “Tôi có thể làm bất cứ việc gì!”. Anh được nhận làm phụ bếp, và xưng tên là Ba. Ông Mai nhớ rằng vì ông đã giúp anh việc nhỏ ấy, anh rất thân với ông. Câu trả lời “bất cứ việc gì” trên con tàu hôm ấy chính là điều anh đã nói với người bạn tên Lê ở Sài Gòn, nay đã thành hành động (xem chuyên đề Lời rủ ra đi và người bạn tên Lê). Từ giây phút đó, người học trò Quốc học năm nào bước vào đời một người làm thuê trên biển."},{"t":"Văn Ba trong tư liệu về con tàu. Lời kể của ông Mai có một chỗ không chắc chắn. Chính ông nói việc ấy xảy ra “vào khoảng cuối năm 1911 hay 1912”, và thừa nhận không nhớ đúng nữa. Các nhà nghiên cứu vì thế đối chiếu với những tư liệu khác. Theo Tạp chí Hồ Chí Minh học của Học viện Chính trị quốc gia Hồ Chí Minh, ngày 3/6/1911, Nguyễn Tất Thành chính thức xuống tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis. Anh làm phụ bếp với cái tên mới là Văn Ba, lương 45 franc mỗi tháng. Theo nhà nghiên cứu Nguyễn Đình Đầu, anh đến xin việc tại văn phòng hãng tàu trên lầu một quán cà phê La Rotonde, số 2 đường Catinat. Một bằng chứng quan trọng khác do chính tay Người viết. Trong lá đơn đề ngày 15/9/1911 gửi Tổng thống Pháp từ Marseille, anh cho biết mình đang làm công cho hãng Chargeurs Réunis, trên tàu Amiral Latouche-Tréville, để kiếm sống (xem chuyên đề Mốc thời gian). Như vậy, con tàu và công việc của người phụ bếp đã được xác nhận bằng giấy tờ. Còn lời ông Mai, dù mơ hồ về năm tháng, vẫn là nguồn hiếm hoi kể lại đời sống hằng ngày của người phụ bếp ấy."},{"t":"Từ bốn giờ sáng. Công việc của người phụ bếp bắt đầu từ bốn giờ sáng. Theo lời ông Mai, anh Ba phải quét dọn sạch sẽ nhà bếp, đốt lửa, khuân than, rồi xuống hầm tàu lấy rau, thịt cá, nước đá. Dưới bếp rất nóng, trong hầm rất rét. Nặng nhọc nhất là lúc phải vác một bao nặng leo lên những bậc thang trong khi tàu tròng trành giữa sóng. Xong những việc ấy lại dọn cơm cho những người đầu bếp, rồi nhặt rau, rửa nồi chảo. Những cái nồi trong bếp tàu cao quá, anh phải leo lên ghế mới chùi được. Suốt ngày, trong bếp luôn vang lên những tiếng gọi: “Ba, đem nước đây! Ba, dọn chảo đi!”. Người thanh niên từng là học trò Trường Quốc học Huế, từng là thầy giáo ở Phan Thiết, giờ làm những việc vặt vất vả nhất trong bếp của một con tàu viễn dương. Anh không có bằng cấp nào để dựa vào, chỉ có sức bền và ý chí. Theo ông Mai, người phụ bếp ấy không bao giờ nói tục, và vì vậy được tất cả anh em yêu mến."},{"t":"Mỗi ngày, chín giờ tối, công việc mới xong. Anh Ba mệt lử. Nhưng trong khi chúng tôi nghỉ hoặc đánh bài, anh Ba đọc hay viết đến mười một giờ hoặc nửa đêm. — Ông Mai, người từng làm việc cùng tàu với anh Ba (lời kể trong sách của Trần Dân Tiên)"},{"t":"Những đêm đọc và viết. Mười bảy tiếng làm việc mỗi ngày, từ bốn giờ sáng đến chín giờ tối, đủ vắt kiệt sức một người trai trẻ. Vậy mà theo ông Mai, khi anh em trong bếp nghỉ ngơi hay đánh bài, anh Ba vẫn ngồi đọc hoặc viết tới khuya. Anh còn giúp những người bạn mù chữ của ông Mai viết thư về cho gia đình họ. Chi tiết ấy nói nhiều về con người. Từ nhỏ, anh đã học chữ Hán; ở các trường Pháp – Việt, anh học chữ quốc ngữ và tiếng Pháp. Trên con tàu, vốn chữ ấy không đem lại cho anh một đồng lương cao hơn. Nhưng anh dùng nó để giúp những người lao động không biết chữ gửi lời thăm hỏi về quê nhà. Còn những giờ đọc và viết lúc nửa đêm là cách anh tiếp tục tự học, khi không còn trường lớp nào. Đó cũng là thói quen theo Người suốt đời: học ở mọi nơi, trong mọi hoàn cảnh, tranh thủ mọi thời gian có được. Con tàu buôn vì thế trở thành lớp học đầu tiên của cuộc đời lao động. Ở đó, người học trò cũ học về biển cả, và trên hết là về những người làm thuê."},{"t":"Bạn có biết? Theo ông Mai, khi tàu đến Marseille, mỗi nhân viên Việt Nam lĩnh từ một trăm đến hai trăm quan, thêm tiền thưởng của hành khách; riêng anh Ba là phụ bếp chỉ được mười quan. Con số này khác với mức 45 franc mỗi tháng mà các nhà nghiên cứu nêu khi viết về con tàu."},{"t":"Những bến cảng dọc đường. Trưa ngày 5/6/1911, tàu rời Sài Gòn. Theo Tạp chí Hồ Chí Minh học, hải trình đưa người phụ bếp qua Singapore, Colombo trên đảo Tích Lan, nay là Sri Lanka, rồi Djibouti gần cửa biển Đỏ, vượt kênh Suez, ghé Port Said của Ai Cập. Ngày 6/7/1911, sau ba mươi mốt ngày, tàu cập cảng Marseille. Không có tư liệu cho biết người phụ bếp đã được lên bờ ở những bến nào. Nhưng những bến ấy có một điểm chung đáng chú ý. Singapore và Colombo khi ấy thuộc quyền cai trị của nước Anh. Djibouti là thuộc địa của Pháp. Ai Cập, nơi có Port Said, đang bị quân Anh chiếm đóng. Dọc con đường từ Sài Gòn sang châu Âu, người thanh niên đi qua những miền đất cũng như quê hương anh, đều nằm dưới quyền các cường quốc châu Âu. Một năm sau, trên con tàu của hãng Chargeurs Réunis đi vòng quanh châu Phi, Người tận mắt chứng kiến cảnh lao động khổ cực của người dân thuộc địa ở Dakar và nhiều bến cảng khác. Hành trình năm 1911 là bước đầu của cái nhìn rộng mở ấy: nỗi khổ của người dân mất nước không chỉ riêng ở Việt Nam."},{"t":"Lần đầu được gọi bằng “ông”. Ở Marseille, các nhân viên trên tàu lĩnh lương. Ông Mai kể rằng ông cho anh Ba mượn một bộ quần áo, rồi hai người cùng đến một tiệm cà phê trên đường La Canebière, đại lộ nổi tiếng của thành phố cảng này. Đó là lần đầu tiên anh Ba vào tiệm cà phê, và cũng là lần đầu tiên có người Pháp gọi anh bằng “ông”. Chữ “ông” ấy, với người Pháp ở Marseille, có lẽ chỉ là phép lịch sự thông thường khi tiếp khách. Nhưng với một người Việt từ thuộc địa sang, đó là một trải nghiệm lạ lùng. Ở Sài Gòn, giữa người Pháp và người bản xứ là khoảng cách của kẻ cai trị và người bị trị. Anh Ba nhận xét với ông Mai rằng người Pháp ở Pháp tốt, lễ phép hơn người Pháp ở Đông Dương. Một câu nói giản dị, nhưng chứa đựng một phát hiện quan trọng. Thái độ khinh miệt mà người dân thuộc địa phải chịu hằng ngày không phải bản chất của cả một dân tộc. Nó gắn với chính chế độ thực dân, và với những con người mà chế độ ấy đưa sang cai trị xứ người."},{"t":"Tại sao người Pháp không “khai hóa” đồng bào của họ?. Marseille còn cho người phụ bếp thấy những điều mà sách vở ở thuộc địa không nói tới. Trông thấy những cô gái điếm lên tàu làm tiền, anh hỏi ông Mai: tại sao người Pháp không “khai hóa” đồng bào của họ trước khi đi “khai hóa” chúng ta? Câu hỏi ấy nhắm thẳng vào lá cờ mà chế độ thuộc địa vẫn giương lên: sứ mệnh “khai hóa văn minh” cho các dân tộc bị trị. Theo sách của Trần Dân Tiên, anh còn ngạc nhiên nhận ra rằng ở Pháp cũng có người nghèo như bên ta, và nói với ông Mai rằng cũng có những người Pháp tốt. Hai phát hiện đi cùng nhau: người lao động Pháp cũng nghèo khổ, và nhân dân Pháp khác với bọn thực dân. Đó là nền móng của một nhận thức theo Người suốt cuộc đời hoạt động: phân biệt nhân dân lao động các nước với những kẻ áp bức. Chín năm sau, tháng 12/1920, tại Đại hội Tours, Nguyễn Ái Quốc bỏ phiếu tán thành gia nhập Quốc tế Cộng sản. Người trở thành một trong những người tham gia sáng lập Đảng Cộng sản Pháp. Con đường ấy có dấu ấn của những quan sát đầu tiên trên bến cảng Marseille."},{"t":"Sau Marseille. Từ Marseille, tàu Amiral Latouche-Tréville đi tiếp lên cảng Le Havre, tới nơi ngày 15/7/1911, rồi kết thúc hải trình ở Dunkerque ngày 26/7. Tính từ Sài Gòn đến Le Havre, chuyến đi kéo dài bốn mươi ngày. Những tháng tiếp theo, người thanh niên vẫn gắn với biển và với đời làm thuê. Ngày 15/9/1911, từ Marseille, anh viết đơn xin vào học Trường Thuộc địa, nhưng không được chấp nhận. Sách của Trần Dân Tiên còn kể một quãng thời gian anh sống ở Sainte-Adresse, vùng ngoại ô của Le Havre, trong một biệt thự có vườn hoa. Lúc rảnh, anh chăm bón hoa cùng người làm vườn, hoặc giở xem những tờ báo có ảnh trong tủ sách. Rồi một buổi chiều, người chủ nhà đi làm về báo tin có một chuyến tàu đi vòng quanh châu Phi. Năm 1912, anh làm việc trên tàu của hãng Chargeurs Réunis trong chuyến đi ấy. Người phụ bếp Văn Ba năm nào đã thật sự bước vào đời một người lao động trên biển, nhiều năm trước khi Người sống và hoạt động ở London rồi Paris (xem chuyên đề Hai bàn tay)."},{"t":"Bạn có biết? Theo nhà nghiên cứu Nguyễn Đình Đầu, năm 1911 tàu Amiral Latouche-Tréville do thuyền trưởng Maisen chỉ huy, với đoàn thủy thủ 69 người. Tàu từ Hải Phòng vào, cập Sài Gòn ngày 2/6 và rời đi trưa 5/6."},{"t":"Bài học đầu tiên của người lao động. Nhìn lại, ba mươi mốt ngày trên tàu Amiral Latouche-Tréville là ba mươi mốt ngày Nguyễn Tất Thành học những điều không có trong sách vở. Anh học cái mệt của người làm thuê, học sự tương trợ giữa những người lao động, học cách nhìn một thế giới rộng lớn hơn nhiều so với xứ thuộc địa. Anh cũng thấy rằng học vấn không quyết định chỗ đứng của một người dân mất nước. Trên tàu, người học trò Quốc học chỉ là một phụ bếp với đồng lương ít ỏi. Cái tên Văn Ba là một trong những tên gọi đầu tiên trong rất nhiều bí danh, bút danh của Người trong những năm hoạt động ở nước ngoài (xem chuyên đề Tượng Nguyễn Tất Thành tại Bến Nhà Rồng). Hôm nay, câu chuyện người phụ bếp được kể lại tại Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh ở Bến Nhà Rồng. Tại đây, hành trình ra đi tìm đường cứu nước năm 1911 là nội dung trưng bày trọng tâm. Trong gian trưng bày này, bạn có thể dừng lại bên con tàu và bến cảng được dựng lại, và hình dung người phụ bếp trẻ nhìn Sài Gòn lùi dần phía sau."}],"so_chu":2070},{"i":3,"tieu_de_bang":"Mốc thời gian","tieu_de":"Từ Nhà Rồng đến Marseille: những mốc thời gian của chuyến đi năm 1911","sapo":"Hai ngày giữa lúc nhận việc và lúc nhổ neo. Ba mươi mốt ngày từ Sài Gòn đến Marseille. Bốn mươi chín năm giữa hai ngày mồng 5 tháng 6. Đặt các mốc thời gian cạnh nhau, ta thấy những con số cũng biết kể chuyện.","bia":{"src":"textures/bai/G04_v6.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Hai dòng thời gian gặp nhau","text":"Khi người phụ bếp Văn Ba rời Sài Gòn trưa ngày 5/6/1911, tòa Nhà Rồng bên sông đã đứng đó gần năm mươi năm. Bảng mốc thời gian này đặt cạnh nhau hai câu chuyện. Câu chuyện thứ nhất là của một nơi chốn: bến cảng Sài Gòn và tòa Nhà Rồng, gắn với sự có mặt của người Pháp từ giữa thế kỷ XIX. Câu chuyện thứ hai là của một con người: Nguyễn Tất Thành, từ Huế xuôi dần về phương Nam, qua Bình Định, Phan Thiết, rồi vào Sài Gòn.\n\nHai dòng thời gian gặp nhau vào tháng 6/1911, trên bến cảng. Rồi chúng lại gặp nhau lần nữa, gần bảy mươi năm sau, khi tòa nhà của hãng tàu thuộc địa trở thành nơi lưu niệm người thanh niên đã ra đi hôm ấy. Các mốc dưới đây được chọn từ những nguồn đã công bố. Ở những chỗ tư liệu còn khác nhau, phần dẫn giải sẽ nói rõ.","doc":1},{"loai":"moc","items":[["17/2/1859","Quân Pháp đánh chiếm thành Gia Định"],["22/2/1860","Chính quyền Pháp tuyên bố mở cảng Sài Gòn cho tàu buôn các nước, mốc ra đời của cảng Sài Gòn"],["5/6/1862","Hòa ước Nhâm Tuất ký tại Sài Gòn: triều Nguyễn nhượng cho Pháp ba tỉnh miền Đông Nam Kỳ và đảo Côn Lôn"],["Giữa 1862 – 1863","Xây tòa trụ sở hãng Messageries Impériales bên sông Sài Gòn, về sau người dân gọi là Nhà Rồng"],["17/11/1869","Kênh Suez khánh thành, rút ngắn đường biển từ châu Âu sang châu Á"],["1870","Hãng đổi tên thành Messageries Maritimes; biểu tượng vương miện, mỏ neo, đầu ngựa thay mặt nguyệt giữa đôi rồng trên nóc"],["19/5/1890","Nguyễn Sinh Cung, sau đổi tên là Nguyễn Tất Thành, chào đời tại làng Hoàng Trù, quê ngoại, huyện Nam Đàn, tỉnh Nghệ An"],["2/1904","Tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis hạ thủy tại Nantes, Pháp"],["20/2/1906","Thành lập Trường Cơ khí Á châu ở Sài Gòn, người dân quen gọi là trường Bá Nghệ"],["1906","Các sĩ phu Duy Tân lập Liên Thành thương quán ở Phan Thiết, cơ sở kinh tài và liên lạc của các nhà yêu nước"],["9/1906","Nguyễn Tất Thành vào học Trường tiểu học Pháp – Việt ở Huế"],["4/1908","Tham gia cuộc biểu tình chống thuế của nông dân tỉnh Thừa Thiên"],["9/1908","Học lớp trung đẳng tại Trường Quốc học Huế"],["6/1909","Rời Quốc học, theo cha vào Bình Định; cuối năm học tiếp ở Trường tiểu học Pháp – Việt Quy Nhơn"],["6/1910","Hoàn thành chương trình tiểu học; nghe tin cha bị cách chức tri huyện Bình Khê, quyết định đi tiếp về phía Nam"],["1910 – 2/1911","Làm trợ giáo ở Trường Dục Thanh, Phan Thiết; đọc sách trong tủ sách của cụ Nguyễn Thông"],["2/1911","Rời Phan Thiết vào Sài Gòn, ở tạm tại các chi nhánh của Liên Thành ở Chợ Lớn và Khánh Hội"],["Đầu năm 1911","Học khoảng ba tháng ở trường Bá Nghệ; lui tới các xóm thợ và bến cảng tìm việc trên tàu"],["2/6/1911","Tàu Amiral Latouche-Tréville từ Hải Phòng vào, cập bến Sài Gòn"],["3/6/1911","Được nhận làm phụ bếp trên tàu với tên Văn Ba, lương 45 franc mỗi tháng"],["Trưa 5/6/1911","Tàu nhổ neo rời Sài Gòn; ngày này được kỷ niệm là Ngày Bác Hồ ra đi tìm đường cứu nước"],["6/1911","Hải trình qua Singapore, Colombo, Djibouti, kênh Suez và Port Said"],["6/7/1911","Tàu cập cảng Marseille; người phụ bếp lần đầu đặt chân lên đất Pháp"],["15/7/1911","Tàu tới cảng Le Havre, bốn mươi ngày sau khi rời Sài Gòn"],["26/7/1911","Tàu tới Dunkerque, bến cuối của hải trình"],["15/9/1911","Từ Marseille, Nguyễn Tất Thành viết đơn gửi Tổng thống Pháp xin vào học Trường Thuộc địa; đơn không được chấp nhận"],["1912","Làm việc trên tàu của hãng Chargeurs Réunis đi vòng quanh châu Phi"],["11/3/1929","Tàu Amiral Latouche-Tréville dừng hoạt động, được tháo dỡ tại Dunkerque"],["28/1/1941","Sau ba mươi năm, Người trở về Tổ quốc qua cột mốc 108 ở Cao Bằng"],["7/9/1979","Ủy ban nhân dân Thành phố Hồ Chí Minh quyết định giữ Nhà Rồng làm di tích lưu niệm Chủ tịch Hồ Chí Minh"],["16/11/1988","Nhà số 5 Châu Văn Liêm, chi nhánh Liên Thành xưa, được công nhận di tích lịch sử quốc gia"],["30/10/1995","Nhà Rồng chính thức trở thành Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh"]],"doc":2},{"loai":"doan","tieu_de":"Dòng thứ nhất: bến cảng ra đời cùng cuộc xâm lược","text":"Các mốc đầu tiên cho thấy bến cảng Sài Gòn ra đời cùng với cuộc xâm lược. Chỉ một năm sau khi quân Pháp chiếm thành Gia Định, ngày 22/2/1860, cảng Sài Gòn được tuyên bố mở cửa cho tàu buôn các nước. Hòa ước Nhâm Tuất được ký ngày 5/6/1862, và cũng từ giữa năm ấy, trụ sở hãng Messageries Impériales được khởi công bên sông. Tòa nhà hoàn thành năm 1863.\n\nNăm 1869, kênh Suez khánh thành, rút ngắn hải trình giữa châu Âu và Viễn Đông. Năm 1870, hãng đổi tên thành Messageries Maritimes. Khoảng cách giữa các mốc rất ngắn: chỉ trong hơn một thập niên, Sài Gòn đã có cảng biển, có trụ sở hãng tàu và có con đường biển thẳng về chính quốc. Đến năm 1911, bến cảng đã hoạt động hơn nửa thế kỷ, và những con tàu nối thuộc địa với nước Pháp đã thành quen thuộc với người dân hai bờ sông (xem chuyên đề Trụ sở hãng Messageries Maritimes — Nhà Rồng — đầu thế kỷ XX).","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_sa_gon_direction_de_la_cie_des_messageries_marit.jpg","chu_thich":"Trụ sở hãng Messageries Maritimes — Nhà Rồng — đầu thế kỷ XX.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Dòng thứ hai: năm năm, bốn thành phố","text":"Dòng thời gian của người thanh niên dày đặc hơn nhiều. Từ tháng 9/1906 ở Huế đến tháng 2/1911 ở Sài Gòn, chưa đầy năm năm, Nguyễn Tất Thành đã sống ở bốn thành phố: Huế, Quy Nhơn, Phan Thiết, Sài Gòn. Anh lần lượt là học trò Trường Quốc học, người tham gia biểu tình chống thuế, thầy giáo trường Dục Thanh, rồi người học nghề ở trường Bá Nghệ.\n\nMỗi chặng dừng chân lại ngắn hơn chặng trước: gần ba năm ở Huế, khoảng một năm ở Bình Định, vài tháng ở Phan Thiết, bốn tháng ở Sài Gòn. Nhịp gấp dần ấy cho thấy một hướng đi ngày càng rõ. Mỗi nơi anh dừng lại không phải để lập nghiệp, mà để học thêm, hiểu thêm, và tiến gần hơn đến cửa biển. Sài Gòn là điểm cuối của con đường bộ ấy. Từ đây, chỉ còn đường biển.","doc":4},{"loai":"anh","src":"textures/bang_w/G04_3_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Bốn tháng, ba ngày, ba mươi mốt ngày","text":"Ở tháng 6/1911, nhịp thời gian càng dồn dập. Tàu Amiral Latouche-Tréville từ Hải Phòng vào, cập Sài Gòn ngày 2/6. Ngày 3/6, người thanh niên được nhận làm phụ bếp. Trưa ngày 5/6, tàu nhổ neo. Con tàu chỉ ở Sài Gòn chừng ba ngày; nếu không sẵn sàng, cơ hội đã trôi qua. Bốn tháng chuẩn bị trước đó, với việc học nghề, dò hỏi các hãng tàu, tìm bạn đồng hành, chính là để nắm được mấy ngày ấy.\n\nRồi đến những con số của biển. Từ Sài Gòn đến Marseille mất ba mươi mốt ngày. Từ Sài Gòn đến Le Havre mất bốn mươi ngày, và hải trình kết thúc ở Dunkerque ngày 26/7. Hơn bốn mươi năm trước đó, khi chưa có kênh Suez, tàu từ châu Á sang châu Âu phải vòng qua mũi Hảo Vọng ở cực nam châu Phi, và chuyến đi dài hơn nhiều. Chưa đầy năm tuần sau khi rời Sài Gòn, anh đã đặt chân lên đất Pháp. Phải ba mươi năm sau, Người mới trở về.","doc":5},{"loai":"ban_co_biet","text":"Ngày 5/6/1911 trùng đúng ngày tháng với Hòa ước Nhâm Tuất, ký tại Sài Gòn ngày 5/6/1862, bản hòa ước đầu tiên buộc triều Nguyễn cắt đất Nam Kỳ cho Pháp. Không có tư liệu nào cho thấy đây là sự sắp đặt; đó là một sự trùng hợp, cách nhau đúng bốn mươi chín năm.","nguon_ten":"Hòa ước Nhâm Tuất (Sài Gòn, 5/6/1862); Tạp chí Hồ Chí Minh học – “Về một số con tàu trong những hải trình của Chủ tịch Hồ Chí Minh”","doc":6},{"loai":"doan","tieu_de":"Lá đơn ngày 15/9/1911","text":"Mốc 15/9/1911 gắn với một tư liệu gốc quý. Hơn hai tháng sau khi đặt chân lên đất Pháp, từ Marseille, Nguyễn Tất Thành viết đơn gửi Tổng thống Pháp, xin được vào học nội trú tại Trường Thuộc địa. Trong đơn, anh cho biết mình đang làm công cho hãng Chargeurs Réunis, trên tàu Amiral Latouche-Tréville, để kiếm sống. Anh viết rằng mình hoàn toàn không có nguồn lực nào và rất thiết tha muốn có học vấn. Anh ký tên Nguyễn Tất Thành, tự giới thiệu là con trai ông Nguyễn Sinh Huy, tức cụ Phó bảng Nguyễn Sinh Sắc.\n\nLá đơn không được chấp nhận. Nhưng nó có giá trị đặc biệt với người nghiên cứu, vì đây là lời xác nhận bằng chính tay Người về con tàu và công việc trong chuyến đi năm 1911. Lá đơn cũng cho thấy ngay từ những ngày đầu ở Pháp, người thanh niên đã tìm mọi cách để được học, để hiểu nước Pháp từ bên trong. Khi cánh cửa trường học đóng lại, anh tiếp tục con đường tự học giữa đời lao động.","doc":7},{"loai":"anh","src":"textures/bang_w/G04_3_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Ba mươi năm giữa hai mốc","text":"Trên bảng mốc thời gian, khoảng cách giữa ngày 5/6/1911 và ngày 28/1/1941 chỉ là vài dòng chữ. Trên thực tế, đó là ba mươi năm. Trong ba mươi năm ấy, người phụ bếp Văn Ba trở thành Nguyễn Ái Quốc, người ký bản “Yêu sách của nhân dân An Nam” gửi Hội nghị Versailles tháng 6/1919. Từ ngày 6/1 đến ngày 7/2/1930, tại Cửu Long, Hương Cảng, Người chủ trì hội nghị hợp nhất các tổ chức cộng sản, thành lập Đảng Cộng sản Việt Nam. Ngày 28/1/1941, Người trở về Tổ quốc qua cột mốc 108 ở biên giới Cao Bằng.\n\nĐặt hai mốc 1911 và 1941 cạnh nhau, ta thấy một hành trình khép lại thành vòng tròn. Đầu bên này là một bến cảng ở phương Nam, nơi người thanh niên ra đi bằng đường biển. Đầu bên kia là một cột mốc biên giới ở phương Bắc, nơi Người trở về bằng đường bộ. Giữa hai đầu ấy là nhiều đại dương, nhiều châu lục và rất nhiều bí danh khác nhau.","doc":8},{"loai":"ban_co_biet","text":"Tàu Amiral Latouche-Tréville dừng hoạt động ngày 11/3/1929 và được tháo dỡ tại Dunkerque, chính bến cảng nơi hải trình năm 1911 kết thúc.","nguon_ten":"Tạp chí Hồ Chí Minh học – “Về một số con tàu trong những hải trình của Chủ tịch Hồ Chí Minh”","doc":9},{"loai":"doan","tieu_de":"Từ trụ sở hãng tàu đến nơi lưu niệm","text":"Dòng thời gian của nơi chốn cũng đi tiếp sau năm 1911. Năm 1955, thương cảng Sài Gòn, trong đó có Nhà Rồng, được chuyển giao cho chính quyền miền Nam Việt Nam quản lý. Năm 1965, tòa nhà được quân đội Mỹ dùng làm trụ sở Cơ quan Tiếp nhận viện trợ quân sự Mỹ. Sau ngày đất nước thống nhất năm 1975, Nhà Rồng thuộc Cục Đường biển Việt Nam quản lý.\n\nNgày 7/9/1979, theo Quyết định số 1315/QĐ-UB của Ủy ban nhân dân Thành phố Hồ Chí Minh, tòa nhà được giữ lại làm di tích lưu niệm Chủ tịch Hồ Chí Minh. Ngày 30/10/1995, Quyết định số 7492/QĐ-UB-NCVX chuyển khu lưu niệm thành Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh (xem chuyên đề Bến Nhà Rồng ngày nay – Bảo tàng Hồ Chí Minh). Như vậy, phải mất gần bảy mươi năm, hai dòng thời gian của gian trưng bày này mới hòa làm một. Bến cảng nơi người thanh niên ra đi trở thành nơi kể lại câu chuyện của chính Người.","doc":10},{"loai":"anh","src":"textures/bang_w/G04_3_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Mốc thời gian”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Những điều các mốc chưa nói hết","text":"Một bảng mốc thời gian dễ tạo cảm giác mọi điều đều đã rõ. Thực ra, quanh chuyến đi năm 1911 vẫn còn những chỗ tư liệu chưa thống nhất. Về tiền lương, các nhà nghiên cứu nêu mức 45 franc mỗi tháng, còn nhân chứng trong sách của Trần Dân Tiên lại nhớ một con số khác (xem chuyên đề Người phụ bếp Văn Ba). Về nơi con tàu neo đậu, nhà nghiên cứu Nguyễn Đình Đầu cho rằng tàu của hãng Chargeurs Réunis cập cầu tàu lớn ở đầu đường Charner, không phải bến Nhà Rồng (xem chuyên đề Bến cảng Sài Gòn).\n\nNhững khác biệt ấy không làm thay đổi các mốc cốt lõi: ngày 3/6/1911 nhận việc với tên Văn Ba, trưa ngày 5/6/1911 rời Sài Gòn, ngày 6/7/1911 đến Marseille. Ngày 5/6 hằng năm vẫn được kỷ niệm là Ngày Bác Hồ ra đi tìm đường cứu nước, và Bến Nhà Rồng vẫn là biểu tượng của cuộc ra đi ấy.","doc":11}],"nguon":["Hồ Chí Minh – Tiểu sử, Bảo tàng Hồ Chí Minh, NXB Chính trị quốc gia, 2008: https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/book/ho-chi-minh/tieu-su-cuoc-doi-va-su-nghiep/ho-chi-minh-tieu-su-bao-tang-ho-chi-minh-nxb-chinh-tri-quoc-gia-ha-noi-nam-2008-20","Tư liệu – Văn kiện Đảng: “Thời niên thiếu của Chủ tịch Hồ Chí Minh (1890 – 1911)”: https://tulieuvankien.dangcongsan.vn/c-mac-angghen-lenin-ho-chi-minh/ho-chi-minh/tieu-su-cuoc-doi-va-su-nghiep/thoi-nien-thieu-cua-chu-tich-ho-chi-minh-1890-1911-3487","Tạp chí Hồ Chí Minh học – “Về một số con tàu trong những hải trình của Chủ tịch Hồ Chí Minh”: https://tapchihochiminh.hcma.vn/Content/ve-mot-so-con-tau-trong-nhung-hai-trinh-cua-chu-tich-ho-chi-minh-01318","Sở Văn hóa và Thể thao TP. Hồ Chí Minh – Bảo tàng Hồ Chí Minh, Chi nhánh TP. Hồ Chí Minh: https://svhtt.hochiminhcity.gov.vn/tin-chi-tiet/-/chi-tiet/bao-tang-ho-chi-minh-chi-nhanh-thanh-pho-ho-chi-minh-19084-2015.html","Báo Thanh Niên – “Nơi Bác ra đi tìm đường cứu nước” (Nguyễn Đình Đầu): https://thanhnien.vn/noi-bac-ra-di-tim-duong-cuu-nuoc-185241009213949499.htm","William J. Duiker, “Ho Chi Minh: A Life” (2000) – về lá đơn ngày 15/9/1911: https://thehehochiminh.wordpress.com/2010/01/03/1911_lathu_truong_thuocdia/"],"doc":[{"t":"Từ Nhà Rồng đến Marseille: những mốc thời gian của chuyến đi năm 1911. Hai ngày giữa lúc nhận việc và lúc nhổ neo. Ba mươi mốt ngày từ Sài Gòn đến Marseille. Bốn mươi chín năm giữa hai ngày mồng 5 tháng 6. Đặt các mốc thời gian cạnh nhau, ta thấy những con số cũng biết kể chuyện."},{"t":"Hai dòng thời gian gặp nhau. Khi người phụ bếp Văn Ba rời Sài Gòn trưa ngày 5/6/1911, tòa Nhà Rồng bên sông đã đứng đó gần năm mươi năm. Bảng mốc thời gian này đặt cạnh nhau hai câu chuyện. Câu chuyện thứ nhất là của một nơi chốn: bến cảng Sài Gòn và tòa Nhà Rồng, gắn với sự có mặt của người Pháp từ giữa thế kỷ XIX. Câu chuyện thứ hai là của một con người: Nguyễn Tất Thành, từ Huế xuôi dần về phương Nam, qua Bình Định, Phan Thiết, rồi vào Sài Gòn. Hai dòng thời gian gặp nhau vào tháng 6/1911, trên bến cảng. Rồi chúng lại gặp nhau lần nữa, gần bảy mươi năm sau, khi tòa nhà của hãng tàu thuộc địa trở thành nơi lưu niệm người thanh niên đã ra đi hôm ấy. Các mốc dưới đây được chọn từ những nguồn đã công bố. Ở những chỗ tư liệu còn khác nhau, phần dẫn giải sẽ nói rõ."},{"t":"Các mốc thời gian. 17/2/1859: Quân Pháp đánh chiếm thành Gia Định. 22/2/1860: Chính quyền Pháp tuyên bố mở cảng Sài Gòn cho tàu buôn các nước, mốc ra đời của cảng Sài Gòn. 5/6/1862: Hòa ước Nhâm Tuất ký tại Sài Gòn: triều Nguyễn nhượng cho Pháp ba tỉnh miền Đông Nam Kỳ và đảo Côn Lôn. Giữa 1862 – 1863: Xây tòa trụ sở hãng Messageries Impériales bên sông Sài Gòn, về sau người dân gọi là Nhà Rồng. 17/11/1869: Kênh Suez khánh thành, rút ngắn đường biển từ châu Âu sang châu Á. 1870: Hãng đổi tên thành Messageries Maritimes; biểu tượng vương miện, mỏ neo, đầu ngựa thay mặt nguyệt giữa đôi rồng trên nóc. 19/5/1890: Nguyễn Sinh Cung, sau đổi tên là Nguyễn Tất Thành, chào đời tại làng Hoàng Trù, quê ngoại, huyện Nam Đàn, tỉnh Nghệ An. 2/1904: Tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis hạ thủy tại Nantes, Pháp. 20/2/1906: Thành lập Trường Cơ khí Á châu ở Sài Gòn, người dân quen gọi là trường Bá Nghệ. 1906: Các sĩ phu Duy Tân lập Liên Thành thương quán ở Phan Thiết, cơ sở kinh tài và liên lạc của các nhà yêu nước. 9/1906: Nguyễn Tất Thành vào học Trường tiểu học Pháp – Việt ở Huế. 4/1908: Tham gia cuộc biểu tình chống thuế của nông dân tỉnh Thừa Thiên. 9/1908: Học lớp trung đẳng tại Trường Quốc học Huế. 6/1909: Rời Quốc học, theo cha vào Bình Định; cuối năm học tiếp ở Trường tiểu học Pháp – Việt Quy Nhơn. 6/1910: Hoàn thành chương trình tiểu học; nghe tin cha bị cách chức tri huyện Bình Khê, quyết định đi tiếp về phía Nam. 1910 – 2/1911: Làm trợ giáo ở Trường Dục Thanh, Phan Thiết; đọc sách trong tủ sách của cụ Nguyễn Thông. 2/1911: Rời Phan Thiết vào Sài Gòn, ở tạm tại các chi nhánh của Liên Thành ở Chợ Lớn và Khánh Hội. Đầu năm 1911: Học khoảng ba tháng ở trường Bá Nghệ; lui tới các xóm thợ và bến cảng tìm việc trên tàu. 2/6/1911: Tàu Amiral Latouche-Tréville từ Hải Phòng vào, cập bến Sài Gòn. 3/6/1911: Được nhận làm phụ bếp trên tàu với tên Văn Ba, lương 45 franc mỗi tháng. Trưa 5/6/1911: Tàu nhổ neo rời Sài Gòn; ngày này được kỷ niệm là Ngày Bác Hồ ra đi tìm đường cứu nước. 6/1911: Hải trình qua Singapore, Colombo, Djibouti, kênh Suez và Port Said. 6/7/1911: Tàu cập cảng Marseille; người phụ bếp lần đầu đặt chân lên đất Pháp. 15/7/1911: Tàu tới cảng Le Havre, bốn mươi ngày sau khi rời Sài Gòn. 26/7/1911: Tàu tới Dunkerque, bến cuối của hải trình. 15/9/1911: Từ Marseille, Nguyễn Tất Thành viết đơn gửi Tổng thống Pháp xin vào học Trường Thuộc địa; đơn không được chấp nhận. 1912: Làm việc trên tàu của hãng Chargeurs Réunis đi vòng quanh châu Phi. 11/3/1929: Tàu Amiral Latouche-Tréville dừng hoạt động, được tháo dỡ tại Dunkerque. 28/1/1941: Sau ba mươi năm, Người trở về Tổ quốc qua cột mốc 108 ở Cao Bằng. 7/9/1979: Ủy ban nhân dân Thành phố Hồ Chí Minh quyết định giữ Nhà Rồng làm di tích lưu niệm Chủ tịch Hồ Chí Minh. 16/11/1988: Nhà số 5 Châu Văn Liêm, chi nhánh Liên Thành xưa, được công nhận di tích lịch sử quốc gia. 30/10/1995: Nhà Rồng chính thức trở thành Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh."},{"t":"Dòng thứ nhất: bến cảng ra đời cùng cuộc xâm lược. Các mốc đầu tiên cho thấy bến cảng Sài Gòn ra đời cùng với cuộc xâm lược. Chỉ một năm sau khi quân Pháp chiếm thành Gia Định, ngày 22/2/1860, cảng Sài Gòn được tuyên bố mở cửa cho tàu buôn các nước. Hòa ước Nhâm Tuất được ký ngày 5/6/1862, và cũng từ giữa năm ấy, trụ sở hãng Messageries Impériales được khởi công bên sông. Tòa nhà hoàn thành năm 1863. Năm 1869, kênh Suez khánh thành, rút ngắn hải trình giữa châu Âu và Viễn Đông. Năm 1870, hãng đổi tên thành Messageries Maritimes. Khoảng cách giữa các mốc rất ngắn: chỉ trong hơn một thập niên, Sài Gòn đã có cảng biển, có trụ sở hãng tàu và có con đường biển thẳng về chính quốc. Đến năm 1911, bến cảng đã hoạt động hơn nửa thế kỷ, và những con tàu nối thuộc địa với nước Pháp đã thành quen thuộc với người dân hai bờ sông (xem chuyên đề Trụ sở hãng Messageries Maritimes — Nhà Rồng — đầu thế kỷ XX)."},{"t":"Dòng thứ hai: năm năm, bốn thành phố. Dòng thời gian của người thanh niên dày đặc hơn nhiều. Từ tháng 9/1906 ở Huế đến tháng 2/1911 ở Sài Gòn, chưa đầy năm năm, Nguyễn Tất Thành đã sống ở bốn thành phố: Huế, Quy Nhơn, Phan Thiết, Sài Gòn. Anh lần lượt là học trò Trường Quốc học, người tham gia biểu tình chống thuế, thầy giáo trường Dục Thanh, rồi người học nghề ở trường Bá Nghệ. Mỗi chặng dừng chân lại ngắn hơn chặng trước: gần ba năm ở Huế, khoảng một năm ở Bình Định, vài tháng ở Phan Thiết, bốn tháng ở Sài Gòn. Nhịp gấp dần ấy cho thấy một hướng đi ngày càng rõ. Mỗi nơi anh dừng lại không phải để lập nghiệp, mà để học thêm, hiểu thêm, và tiến gần hơn đến cửa biển. Sài Gòn là điểm cuối của con đường bộ ấy. Từ đây, chỉ còn đường biển."},{"t":"Bốn tháng, ba ngày, ba mươi mốt ngày. Ở tháng 6/1911, nhịp thời gian càng dồn dập. Tàu Amiral Latouche-Tréville từ Hải Phòng vào, cập Sài Gòn ngày 2/6. Ngày 3/6, người thanh niên được nhận làm phụ bếp. Trưa ngày 5/6, tàu nhổ neo. Con tàu chỉ ở Sài Gòn chừng ba ngày; nếu không sẵn sàng, cơ hội đã trôi qua. Bốn tháng chuẩn bị trước đó, với việc học nghề, dò hỏi các hãng tàu, tìm bạn đồng hành, chính là để nắm được mấy ngày ấy. Rồi đến những con số của biển. Từ Sài Gòn đến Marseille mất ba mươi mốt ngày. Từ Sài Gòn đến Le Havre mất bốn mươi ngày, và hải trình kết thúc ở Dunkerque ngày 26/7. Hơn bốn mươi năm trước đó, khi chưa có kênh Suez, tàu từ châu Á sang châu Âu phải vòng qua mũi Hảo Vọng ở cực nam châu Phi, và chuyến đi dài hơn nhiều. Chưa đầy năm tuần sau khi rời Sài Gòn, anh đã đặt chân lên đất Pháp. Phải ba mươi năm sau, Người mới trở về."},{"t":"Bạn có biết? Ngày 5/6/1911 trùng đúng ngày tháng với Hòa ước Nhâm Tuất, ký tại Sài Gòn ngày 5/6/1862, bản hòa ước đầu tiên buộc triều Nguyễn cắt đất Nam Kỳ cho Pháp. Không có tư liệu nào cho thấy đây là sự sắp đặt; đó là một sự trùng hợp, cách nhau đúng bốn mươi chín năm."},{"t":"Lá đơn ngày 15/9/1911. Mốc 15/9/1911 gắn với một tư liệu gốc quý. Hơn hai tháng sau khi đặt chân lên đất Pháp, từ Marseille, Nguyễn Tất Thành viết đơn gửi Tổng thống Pháp, xin được vào học nội trú tại Trường Thuộc địa. Trong đơn, anh cho biết mình đang làm công cho hãng Chargeurs Réunis, trên tàu Amiral Latouche-Tréville, để kiếm sống. Anh viết rằng mình hoàn toàn không có nguồn lực nào và rất thiết tha muốn có học vấn. Anh ký tên Nguyễn Tất Thành, tự giới thiệu là con trai ông Nguyễn Sinh Huy, tức cụ Phó bảng Nguyễn Sinh Sắc. Lá đơn không được chấp nhận. Nhưng nó có giá trị đặc biệt với người nghiên cứu, vì đây là lời xác nhận bằng chính tay Người về con tàu và công việc trong chuyến đi năm 1911. Lá đơn cũng cho thấy ngay từ những ngày đầu ở Pháp, người thanh niên đã tìm mọi cách để được học, để hiểu nước Pháp từ bên trong. Khi cánh cửa trường học đóng lại, anh tiếp tục con đường tự học giữa đời lao động."},{"t":"Ba mươi năm giữa hai mốc. Trên bảng mốc thời gian, khoảng cách giữa ngày 5/6/1911 và ngày 28/1/1941 chỉ là vài dòng chữ. Trên thực tế, đó là ba mươi năm. Trong ba mươi năm ấy, người phụ bếp Văn Ba trở thành Nguyễn Ái Quốc, người ký bản “Yêu sách của nhân dân An Nam” gửi Hội nghị Versailles tháng 6/1919. Từ ngày 6/1 đến ngày 7/2/1930, tại Cửu Long, Hương Cảng, Người chủ trì hội nghị hợp nhất các tổ chức cộng sản, thành lập Đảng Cộng sản Việt Nam. Ngày 28/1/1941, Người trở về Tổ quốc qua cột mốc 108 ở biên giới Cao Bằng. Đặt hai mốc 1911 và 1941 cạnh nhau, ta thấy một hành trình khép lại thành vòng tròn. Đầu bên này là một bến cảng ở phương Nam, nơi người thanh niên ra đi bằng đường biển. Đầu bên kia là một cột mốc biên giới ở phương Bắc, nơi Người trở về bằng đường bộ. Giữa hai đầu ấy là nhiều đại dương, nhiều châu lục và rất nhiều bí danh khác nhau."},{"t":"Bạn có biết? Tàu Amiral Latouche-Tréville dừng hoạt động ngày 11/3/1929 và được tháo dỡ tại Dunkerque, chính bến cảng nơi hải trình năm 1911 kết thúc."},{"t":"Từ trụ sở hãng tàu đến nơi lưu niệm. Dòng thời gian của nơi chốn cũng đi tiếp sau năm 1911. Năm 1955, thương cảng Sài Gòn, trong đó có Nhà Rồng, được chuyển giao cho chính quyền miền Nam Việt Nam quản lý. Năm 1965, tòa nhà được quân đội Mỹ dùng làm trụ sở Cơ quan Tiếp nhận viện trợ quân sự Mỹ. Sau ngày đất nước thống nhất năm 1975, Nhà Rồng thuộc Cục Đường biển Việt Nam quản lý. Ngày 7/9/1979, theo Quyết định số 1315/QĐ-UB của Ủy ban nhân dân Thành phố Hồ Chí Minh, tòa nhà được giữ lại làm di tích lưu niệm Chủ tịch Hồ Chí Minh. Ngày 30/10/1995, Quyết định số 7492/QĐ-UB-NCVX chuyển khu lưu niệm thành Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh (xem chuyên đề Bến Nhà Rồng ngày nay – Bảo tàng Hồ Chí Minh). Như vậy, phải mất gần bảy mươi năm, hai dòng thời gian của gian trưng bày này mới hòa làm một. Bến cảng nơi người thanh niên ra đi trở thành nơi kể lại câu chuyện của chính Người."},{"t":"Những điều các mốc chưa nói hết. Một bảng mốc thời gian dễ tạo cảm giác mọi điều đều đã rõ. Thực ra, quanh chuyến đi năm 1911 vẫn còn những chỗ tư liệu chưa thống nhất. Về tiền lương, các nhà nghiên cứu nêu mức 45 franc mỗi tháng, còn nhân chứng trong sách của Trần Dân Tiên lại nhớ một con số khác (xem chuyên đề Người phụ bếp Văn Ba). Về nơi con tàu neo đậu, nhà nghiên cứu Nguyễn Đình Đầu cho rằng tàu của hãng Chargeurs Réunis cập cầu tàu lớn ở đầu đường Charner, không phải bến Nhà Rồng (xem chuyên đề Bến cảng Sài Gòn). Những khác biệt ấy không làm thay đổi các mốc cốt lõi: ngày 3/6/1911 nhận việc với tên Văn Ba, trưa ngày 5/6/1911 rời Sài Gòn, ngày 6/7/1911 đến Marseille. Ngày 5/6 hằng năm vẫn được kỷ niệm là Ngày Bác Hồ ra đi tìm đường cứu nước, và Bến Nhà Rồng vẫn là biểu tượng của cuộc ra đi ấy."}],"so_chu":1511},{"i":4,"tieu_de_bang":"Trụ sở hãng Messageries Maritimes — Nhà Rồng — đầu thế kỷ XX","tieu_de":"Tòa nhà của hãng tàu “Hoàng đế”: câu chuyện đằng sau tấm ảnh trụ sở Messageries Maritimes","sapo":"Dưới tấm ảnh cũ chỉ có một dòng chữ Pháp khô khan: “Saïgon – Direction de la Cie des Messageries Maritimes”. Người Sài Gòn chưa bao giờ gọi tòa nhà bằng cái tên dài ấy; họ gọi nó là Nhà Rồng. Đằng sau cái tên dân gian là câu chuyện về một hãng tàu mang danh “Hoàng đế”, đặt chân lên Sài Gòn cùng lúc với tiếng súng xâm lược. Hơn một thế kỷ sau, chính tòa nhà ấy lại trở thành nơi tưởng niệm người đã dành cả đời đấu tranh xóa bỏ ách thuộc địa.","bia":{"src":"textures/ht/ht_anh_sa_gon_direction_de_la_cie_des_messageries_marit.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Một dòng chữ, hai cái tên","text":"Tấm ảnh tư liệu này không rõ người chụp. Hồ sơ lưu trữ ghi niên đại khoảng cuối thế kỷ XIX, đầu thế kỷ XX, kèm dòng chú thích tiếng Pháp “Saïgon – Direction de la Cie des Messageries Maritimes”. Dịch sát nghĩa, đó là “Sài Gòn – Ban Giám đốc Công ty Messageries Maritimes”. Chữ “Direction” cho biết đây không phải một nhà kho hay một quầy vé ven sông, mà là nơi đặt bộ máy điều hành của hãng tàu tại Sài Gòn.\n\nTòa nhà đứng ở ngã ba, nơi rạch Bến Nghé đổ ra sông Sài Gòn, bên phía Khánh Hội. Người Pháp gọi nó bằng tên công ty. Người Sài Gòn thì gọi theo điều họ nhìn thấy từ xa: đôi rồng trên nóc. Cái tên Nhà Rồng về sau đặt tên cho cả bến sông, và sống lâu hơn mọi tên gọi chính thức. Chuyện đôi rồng được kể riêng trong chuyên đề Nhà Rồng. Bài này đi theo một hướng khác: tìm hiểu hãng tàu đã dựng nên tòa nhà, và chỗ đứng của nó trong guồng máy thuộc địa.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_sa_gon_direction_de_la_cie_des_messageries_marit.jpg","chu_thich":"Trụ sở hãng Messageries Maritimes — Nhà Rồng — đầu thế kỷ XX (ảnh tư liệu, không rõ tác giả).","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Hãng tàu mang danh “Hoàng đế”","text":"Messageries Maritimes có gốc gác từ một doanh nghiệp chở khách bằng xe ngựa ở Pháp. Ngày 28/2/1851, công ty khi ấy mang tên Messageries Nationales ký bản hợp đồng chuyên chở thư tín đường biển đầu tiên với Nhà nước Pháp. Khi nước Pháp bước sang thời Đế chế thứ hai dưới quyền Napoléon III, hãng đổi tên thành Messageries Impériales. Tư liệu tiếng Việt thường dịch là Tổng công ty Vận tải Hoàng đế. Chữ “messageries” vốn chỉ việc chuyên chở thư từ, bưu kiện và hành khách theo những tuyến cố định.\n\nNgày 22/4/1861, Nhà nước Pháp ký với hãng bản hợp đồng đầu tiên để mở các tuyến bưu chính và thương mại sang châu Á. Tháng 10/1862, tuyến tàu Viễn Đông khai trương, chạy tới tận Thượng Hải. Khi ấy kênh Suez chưa hoàn thành, nên hành khách và hàng hóa phải chuyển tải qua đất Ai Cập, từ Alexandria sang Suez, rồi mới xuống tàu đi tiếp. Tòa trụ sở ở Sài Gòn được khởi công giữa năm 1862 và hoàn thành năm 1863, đúng lúc tuyến tàu mới ra đời.","doc":2},{"loai":"doan","tieu_de":"Sài Gòn giữa năm 1862","text":"Thời điểm khởi công nói lên nhiều điều. Tháng 2/1859, quân Pháp đánh chiếm thành Gia Định. Ngày 22/2/1860, họ tuyên bố mở cảng Sài Gòn cho tàu buôn các nước ra vào. Đầu năm 1861, quân Pháp phá vỡ Đại đồn Chí Hòa, rồi lần lượt đánh chiếm các tỉnh miền Đông Nam Kỳ. Ngày 5/6/1862, triều đình Tự Đức phải ký Hiệp ước Nhâm Tuất, nhượng cho Pháp ba tỉnh Biên Hòa, Gia Định, Định Tường cùng đảo Côn Lôn.\n\nCũng vào giữa năm ấy, hãng tàu khởi công trụ sở bên bến sông. Một hãng tàu thư tín dựng cơ ngơi sớm như vậy cho thấy vai trò của đường biển trong cuộc xâm lược và khai thác thuộc địa. Những con tàu mang tới quan chức, binh lính, công văn và thư từ từ chính quốc. Chiều ngược lại, chúng chở về châu Âu hàng hóa, sản vật và tin tức từ vùng đất mới chiếm. Tòa nhà bên sông vì thế là một mắt xích của sợi dây nối Sài Gòn với Marseille, và qua Marseille với Paris.","doc":3},{"loai":"ban_co_biet","text":"Hiệp ước Nhâm Tuất, văn bản đầu tiên cắt đất Nam Kỳ cho Pháp, được ký ngày 5/6/1862, cũng vào khoảng thời gian tòa trụ sở hãng tàu khởi công bên sông Sài Gòn. Đúng bốn mươi chín năm sau, cũng vào ngày 5/6, người thanh niên Nguyễn Tất Thành rời Sài Gòn ra đi tìm đường cứu nước.","nguon_ten":"Sách giáo khoa Lịch sử 11 (NXB Giáo dục Việt Nam) – Hiệp ước Nhâm Tuất 5/6/1862; Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh (bennharong.vn)","doc":4},{"loai":"doan","tieu_de":"Nơi bán vé bên ngã ba sông","text":"Theo báo Công an Nhân dân, tòa nhà do hãng tàu xây dựng được dùng làm nơi bán vé tàu và làm nơi ở cho người quản lý. Tư liệu giới thiệu của Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh mô tả công trình mang phong cách kiến trúc phương Tây. Nhưng trên nóc lại gắn đôi rồng theo mô típ “lưỡng long chầu nguyệt” quen thuộc của đình chùa Việt. Sự pha trộn ấy khiến tòa nhà trở thành một dấu mốc dễ nhận ra với bất kỳ ai đi thuyền trên sông.\n\nVị trí được chọn cũng rất đắc địa. Ngã ba rạch Bến Nghé và sông Sài Gòn là nơi tàu biển từ ngoài khơi vào và ghe thuyền từ Chợ Lớn ra gặp nhau. Trước tòa nhà là bến dành cho tàu của hãng. Theo nhà nghiên cứu Nguyễn Đình Đầu, đầu thế kỷ XX, bến Nhà Rồng chủ yếu phục vụ tàu Messageries Maritimes, còn tàu các hãng khác cập những cầu tàu khác của thương cảng (xem chuyên đề Bến cảng Sài Gòn). Nói cách khác, Nhà Rồng không phải cửa ngõ chung của mọi con tàu, mà là cơ ngơi riêng của một hãng lớn.","doc":5},{"loai":"anh","src":"textures/bang_w/G04_4_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trụ sở hãng Messageries Maritimes — Nhà Rồng — đầu thế kỷ XX”, nhìn từ xa."},{"loai":"doan","tieu_de":"Kênh Suez rút ngắn đường về chính quốc","text":"Ngày 17/11/1869, kênh Suez khánh thành. Từ đây, tàu của hãng đi thẳng từ Marseille sang Viễn Đông mà không phải chuyển tải qua đất Ai Cập, rồi kéo dài tuyến tới Yokohama ở Nhật Bản. Sài Gòn trở thành một bến ghé quan trọng trên con đường ấy. Hải trình giữa chính quốc và thuộc địa rút ngắn đáng kể, các chuyến tàu đi về đều đặn hơn.\n\nVới chính quyền thuộc địa, những chuyến tàu thư tín ấy là mạch máu. Chỉ thị và công văn từ Paris, báo chí, sách vở, hàng hóa tiêu dùng cho người Pháp ở Sài Gòn đều theo tàu mà tới. Với người dân bản xứ, con tàu mang một ý nghĩa khác. Nó là biểu tượng quyền lực của chính quốc, nhưng cũng là cánh cửa hiếm hoi mở ra thế giới bên ngoài. Bốn mươi hai năm sau ngày kênh Suez khánh thành, một người thanh niên Việt Nam sẽ đi qua con kênh ấy trên một chuyến tàu buôn, với tư cách người phụ bếp.","doc":6},{"loai":"doan","tieu_de":"Từ “Hoàng đế” đến “Hàng hải”","text":"Tháng 9/1870, Đế chế thứ hai sụp đổ sau thất bại của Pháp trong cuộc chiến với Phổ. Cái tên gắn với hoàng đế không còn hợp thời, và hãng đổi tên thành Messageries Maritimes, tức Công ty Vận tải Hàng hải. Tư liệu của bảo tàng ghi mốc năm 1870; tài liệu lịch sử của hãng ở Pháp cho biết tên mới được dùng chính thức từ năm 1871. Cùng với tên mới, mặt nguyệt giữa đôi rồng trên nóc được thay bằng biểu tượng của hãng gồm vương miện, mỏ neo và đầu ngựa. Người Sài Gòn vì thế gọi đây là “hãng Đầu Ngựa”.\n\nNgười Việt thời ấy phân biệt các hãng tàu Pháp bằng những biệt danh dễ nhớ như vậy. Hãng Chargeurs Réunis, chủ con tàu Amiral Latouche-Tréville, được gọi là “hãng Năm Sao”. Sự phân biệt này rất quan trọng khi đọc lại câu chuyện năm 1911. Người phụ bếp Văn Ba không làm việc cho hãng chủ tòa Nhà Rồng, mà cho hãng Năm Sao (xem chuyên đề Tàu Amiral Latouche-Tréville).","doc":7},{"loai":"ban_co_biet","text":"Chuyến tàu khách định kỳ cuối cùng của Messageries Maritimes trên tuyến Viễn Đông là chuyến tàu Laos rời Yokohama về Marseille ngày 17/11/1969. Ngày ấy tròn một trăm năm sau ngày kênh Suez khánh thành, 17/11/1869, sự kiện từng mở ra thời hoàng kim của hãng ở phương Đông.","nguon_ten":"French Lines & Cies – “L’épopée des Messageries Maritimes: l’Orient pour horizon”","doc":8},{"loai":"doan","tieu_de":"Năm 1911: tòa nhà và người phụ bếp","text":"Đầu năm 1911, khi Nguyễn Tất Thành vào Sài Gòn, tòa nhà của hãng Đầu Ngựa đã đứng bên bến sông gần nửa thế kỷ. Với người thanh niên đang tìm đường ra nước ngoài, những con tàu viễn dương đi về trên sông là hình ảnh cụ thể nhất của thế giới bên kia đại dương. Anh không có tiền mua vé, nên con đường duy nhất là xin làm việc trên tàu. Theo nhà nghiên cứu Nguyễn Đình Đầu, nơi anh xin việc là văn phòng hãng tàu trên lầu quán cà phê La Rotonde ở đường Catinat, chứ không phải tòa Nhà Rồng.\n\nNhư vậy, xét về giấy tờ, tòa Nhà Rồng không trực tiếp gắn với việc nhận người phụ bếp Văn Ba. Nhưng trong ký ức của người dân, bến sông có đôi rồng đã trở thành biểu tượng của cả thương cảng Sài Gòn, nơi con tàu năm 1911 nhổ neo. Lịch sử có những sự trùng hợp giàu ý nghĩa. Tòa nhà dựng lên để phục vụ những chuyến tàu của chế độ thuộc địa, về sau lại được chọn để lưu giữ ký ức về người đã dành trọn đời đấu tranh xóa bỏ chế độ ấy.","doc":9},{"loai":"anh","src":"textures/bang_w/G04_4_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trụ sở hãng Messageries Maritimes — Nhà Rồng — đầu thế kỷ XX”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Số phận của hãng tàu","text":"Hãng Messageries Maritimes còn tồn tại thêm hơn sáu mươi năm sau chuyến đi năm 1911. Trong Chiến tranh thế giới thứ nhất, nhiều tàu của hãng bị trưng dụng chở quân, và hãng mất gần một phần ba đội tàu. Sau đó là thời của những tàu khách lớn trên tuyến Viễn Đông, rồi Chiến tranh thế giới thứ hai và làn sóng giải phóng dân tộc ở các thuộc địa. Năm 1955, sau thất bại của Pháp ở Đông Dương, tòa Nhà Rồng được chuyển giao cho chính quyền Sài Gòn cũ. Mối gắn bó gần một thế kỷ giữa hãng tàu và tòa nhà chấm dứt.\n\nKhi máy bay dần thay thế tàu biển trên những chặng đường dài, các tuyến tàu khách của hãng cũng thưa dần. Ngày 23/2/1977, Messageries Maritimes chính thức chấm dứt hoạt động. Nhà nước Pháp sáp nhập hãng với Compagnie Générale Transatlantique thành Công ty Hàng hải Tổng hợp, viết tắt là CGM. Năm 1999, CGM hợp nhất với hãng CMA, tạo nên tập đoàn vận tải biển CMA CGM ngày nay.","doc":10},{"loai":"ban_co_biet","text":"Theo tài liệu lịch sử của hãng, trong Chiến tranh thế giới thứ nhất, gần một phần ba đội tàu Messageries Maritimes, tức 25 chiếc, đã bị phá hủy.","nguon_ten":"L’encyclopédie des Messageries Maritimes – Histoire de la compagnie (messageries-maritimes.org)","doc":11},{"loai":"anh","src":"textures/bang_w/G04_4_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Trụ sở hãng Messageries Maritimes — Nhà Rồng — đầu thế kỷ XX”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Đọc tấm ảnh hôm nay","text":"Hơn một trăm sáu mươi năm sau ngày hoàn thành, tòa nhà trong tấm ảnh vẫn đứng ở vị trí cũ bên ngã ba sông, nay mang địa chỉ số 1 đường Nguyễn Tất Thành. Nó đã qua tay nhiều chủ: hãng tàu Pháp, chính quyền Sài Gòn cũ, quân đội Mỹ, rồi ngành đường biển Việt Nam sau năm 1975. Năm 1979, nơi đây trở thành nơi lưu niệm Chủ tịch Hồ Chí Minh. Từ ngày 30/10/1995, tòa nhà là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh (xem chuyên đề Bến Nhà Rồng ngày nay).\n\nĐặt tấm ảnh cũ cạnh tòa nhà hôm nay, người xem có thể tự mình so sánh. Dòng chữ “Direction de la Cie des Messageries Maritimes” đã thuộc về quá khứ, cùng với hãng tàu từng điều hành những chuyến tàu nối thuộc địa với chính quốc. Còn tòa nhà thì mang một sứ mệnh hoàn toàn mới. Nó kể lại câu chuyện của người thanh niên từng ra đi từ bến cảng này, để rồi trở về lãnh đạo dân tộc giành độc lập.","doc":12}],"nguon":["Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh: Giới thiệu bảo tàng – https://bennharong.vn/gioi-thieu-bao-tang","French Lines & Cies – L’épopée des Messageries Maritimes: l’Orient pour horizon – https://www.frenchlines.com/expositions/expositions-virtuelles/lepopee-des-messageries-maritimes-lorient-pour-horizon/","L’encyclopédie des Messageries Maritimes – Histoire de la compagnie – https://www.messageries-maritimes.org/hist.htm","Báo Công an Nhân dân – “Đầu xuân thăm Bến Nhà Rồng” (Thái Bình, 20/2/2018) – https://cand.vn/Chuyen-dong-van-hoa/Dau-xuan-tham-Ben-Nha-Rong-i465747","Tạp chí Hồ Chí Minh học – “Về một số con tàu trong những hải trình của Chủ tịch Hồ Chí Minh” – https://tapchihochiminh.hcma.vn/Content/ve-mot-so-con-tau-trong-nhung-hai-trinh-cua-chu-tich-ho-chi-minh-01318","Báo Thanh Niên – “Nơi Bác ra đi tìm đường cứu nước” (nhà nghiên cứu Nguyễn Đình Đầu) – https://thanhnien.vn/noi-bac-ra-di-tim-duong-cuu-nuoc-185241009213949499.htm"],"doc":[{"t":"Tòa nhà của hãng tàu “Hoàng đế”: câu chuyện đằng sau tấm ảnh trụ sở Messageries Maritimes. Dưới tấm ảnh cũ chỉ có một dòng chữ Pháp khô khan: “Saïgon – Direction de la Cie des Messageries Maritimes”. Người Sài Gòn chưa bao giờ gọi tòa nhà bằng cái tên dài ấy; họ gọi nó là Nhà Rồng. Đằng sau cái tên dân gian là câu chuyện về một hãng tàu mang danh “Hoàng đế”, đặt chân lên Sài Gòn cùng lúc với tiếng súng xâm lược. Hơn một thế kỷ sau, chính tòa nhà ấy lại trở thành nơi tưởng niệm người đã dành cả đời đấu tranh xóa bỏ ách thuộc địa."},{"t":"Một dòng chữ, hai cái tên. Tấm ảnh tư liệu này không rõ người chụp. Hồ sơ lưu trữ ghi niên đại khoảng cuối thế kỷ XIX, đầu thế kỷ XX, kèm dòng chú thích tiếng Pháp “Saïgon – Direction de la Cie des Messageries Maritimes”. Dịch sát nghĩa, đó là “Sài Gòn – Ban Giám đốc Công ty Messageries Maritimes”. Chữ “Direction” cho biết đây không phải một nhà kho hay một quầy vé ven sông, mà là nơi đặt bộ máy điều hành của hãng tàu tại Sài Gòn. Tòa nhà đứng ở ngã ba, nơi rạch Bến Nghé đổ ra sông Sài Gòn, bên phía Khánh Hội. Người Pháp gọi nó bằng tên công ty. Người Sài Gòn thì gọi theo điều họ nhìn thấy từ xa: đôi rồng trên nóc. Cái tên Nhà Rồng về sau đặt tên cho cả bến sông, và sống lâu hơn mọi tên gọi chính thức. Chuyện đôi rồng được kể riêng trong chuyên đề Nhà Rồng. Bài này đi theo một hướng khác: tìm hiểu hãng tàu đã dựng nên tòa nhà, và chỗ đứng của nó trong guồng máy thuộc địa."},{"t":"Hãng tàu mang danh “Hoàng đế”. Messageries Maritimes có gốc gác từ một doanh nghiệp chở khách bằng xe ngựa ở Pháp. Ngày 28/2/1851, công ty khi ấy mang tên Messageries Nationales ký bản hợp đồng chuyên chở thư tín đường biển đầu tiên với Nhà nước Pháp. Khi nước Pháp bước sang thời Đế chế thứ hai dưới quyền Napoléon III, hãng đổi tên thành Messageries Impériales. Tư liệu tiếng Việt thường dịch là Tổng công ty Vận tải Hoàng đế. Chữ “messageries” vốn chỉ việc chuyên chở thư từ, bưu kiện và hành khách theo những tuyến cố định. Ngày 22/4/1861, Nhà nước Pháp ký với hãng bản hợp đồng đầu tiên để mở các tuyến bưu chính và thương mại sang châu Á. Tháng 10/1862, tuyến tàu Viễn Đông khai trương, chạy tới tận Thượng Hải. Khi ấy kênh Suez chưa hoàn thành, nên hành khách và hàng hóa phải chuyển tải qua đất Ai Cập, từ Alexandria sang Suez, rồi mới xuống tàu đi tiếp. Tòa trụ sở ở Sài Gòn được khởi công giữa năm 1862 và hoàn thành năm 1863, đúng lúc tuyến tàu mới ra đời."},{"t":"Sài Gòn giữa năm 1862. Thời điểm khởi công nói lên nhiều điều. Tháng 2/1859, quân Pháp đánh chiếm thành Gia Định. Ngày 22/2/1860, họ tuyên bố mở cảng Sài Gòn cho tàu buôn các nước ra vào. Đầu năm 1861, quân Pháp phá vỡ Đại đồn Chí Hòa, rồi lần lượt đánh chiếm các tỉnh miền Đông Nam Kỳ. Ngày 5/6/1862, triều đình Tự Đức phải ký Hiệp ước Nhâm Tuất, nhượng cho Pháp ba tỉnh Biên Hòa, Gia Định, Định Tường cùng đảo Côn Lôn. Cũng vào giữa năm ấy, hãng tàu khởi công trụ sở bên bến sông. Một hãng tàu thư tín dựng cơ ngơi sớm như vậy cho thấy vai trò của đường biển trong cuộc xâm lược và khai thác thuộc địa. Những con tàu mang tới quan chức, binh lính, công văn và thư từ từ chính quốc. Chiều ngược lại, chúng chở về châu Âu hàng hóa, sản vật và tin tức từ vùng đất mới chiếm. Tòa nhà bên sông vì thế là một mắt xích của sợi dây nối Sài Gòn với Marseille, và qua Marseille với Paris."},{"t":"Bạn có biết? Hiệp ước Nhâm Tuất, văn bản đầu tiên cắt đất Nam Kỳ cho Pháp, được ký ngày 5/6/1862, cũng vào khoảng thời gian tòa trụ sở hãng tàu khởi công bên sông Sài Gòn. Đúng bốn mươi chín năm sau, cũng vào ngày 5/6, người thanh niên Nguyễn Tất Thành rời Sài Gòn ra đi tìm đường cứu nước."},{"t":"Nơi bán vé bên ngã ba sông. Theo báo Công an Nhân dân, tòa nhà do hãng tàu xây dựng được dùng làm nơi bán vé tàu và làm nơi ở cho người quản lý. Tư liệu giới thiệu của Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh mô tả công trình mang phong cách kiến trúc phương Tây. Nhưng trên nóc lại gắn đôi rồng theo mô típ “lưỡng long chầu nguyệt” quen thuộc của đình chùa Việt. Sự pha trộn ấy khiến tòa nhà trở thành một dấu mốc dễ nhận ra với bất kỳ ai đi thuyền trên sông. Vị trí được chọn cũng rất đắc địa. Ngã ba rạch Bến Nghé và sông Sài Gòn là nơi tàu biển từ ngoài khơi vào và ghe thuyền từ Chợ Lớn ra gặp nhau. Trước tòa nhà là bến dành cho tàu của hãng. Theo nhà nghiên cứu Nguyễn Đình Đầu, đầu thế kỷ XX, bến Nhà Rồng chủ yếu phục vụ tàu Messageries Maritimes, còn tàu các hãng khác cập những cầu tàu khác của thương cảng (xem chuyên đề Bến cảng Sài Gòn). Nói cách khác, Nhà Rồng không phải cửa ngõ chung của mọi con tàu, mà là cơ ngơi riêng của một hãng lớn."},{"t":"Kênh Suez rút ngắn đường về chính quốc. Ngày 17/11/1869, kênh Suez khánh thành. Từ đây, tàu của hãng đi thẳng từ Marseille sang Viễn Đông mà không phải chuyển tải qua đất Ai Cập, rồi kéo dài tuyến tới Yokohama ở Nhật Bản. Sài Gòn trở thành một bến ghé quan trọng trên con đường ấy. Hải trình giữa chính quốc và thuộc địa rút ngắn đáng kể, các chuyến tàu đi về đều đặn hơn. Với chính quyền thuộc địa, những chuyến tàu thư tín ấy là mạch máu. Chỉ thị và công văn từ Paris, báo chí, sách vở, hàng hóa tiêu dùng cho người Pháp ở Sài Gòn đều theo tàu mà tới. Với người dân bản xứ, con tàu mang một ý nghĩa khác. Nó là biểu tượng quyền lực của chính quốc, nhưng cũng là cánh cửa hiếm hoi mở ra thế giới bên ngoài. Bốn mươi hai năm sau ngày kênh Suez khánh thành, một người thanh niên Việt Nam sẽ đi qua con kênh ấy trên một chuyến tàu buôn, với tư cách người phụ bếp."},{"t":"Từ “Hoàng đế” đến “Hàng hải”. Tháng 9/1870, Đế chế thứ hai sụp đổ sau thất bại của Pháp trong cuộc chiến với Phổ. Cái tên gắn với hoàng đế không còn hợp thời, và hãng đổi tên thành Messageries Maritimes, tức Công ty Vận tải Hàng hải. Tư liệu của bảo tàng ghi mốc năm 1870; tài liệu lịch sử của hãng ở Pháp cho biết tên mới được dùng chính thức từ năm 1871. Cùng với tên mới, mặt nguyệt giữa đôi rồng trên nóc được thay bằng biểu tượng của hãng gồm vương miện, mỏ neo và đầu ngựa. Người Sài Gòn vì thế gọi đây là “hãng Đầu Ngựa”. Người Việt thời ấy phân biệt các hãng tàu Pháp bằng những biệt danh dễ nhớ như vậy. Hãng Chargeurs Réunis, chủ con tàu Amiral Latouche-Tréville, được gọi là “hãng Năm Sao”. Sự phân biệt này rất quan trọng khi đọc lại câu chuyện năm 1911. Người phụ bếp Văn Ba không làm việc cho hãng chủ tòa Nhà Rồng, mà cho hãng Năm Sao (xem chuyên đề Tàu Amiral Latouche-Tréville)."},{"t":"Bạn có biết? Chuyến tàu khách định kỳ cuối cùng của Messageries Maritimes trên tuyến Viễn Đông là chuyến tàu Laos rời Yokohama về Marseille ngày 17/11/1969. Ngày ấy tròn một trăm năm sau ngày kênh Suez khánh thành, 17/11/1869, sự kiện từng mở ra thời hoàng kim của hãng ở phương Đông."},{"t":"Năm 1911: tòa nhà và người phụ bếp. Đầu năm 1911, khi Nguyễn Tất Thành vào Sài Gòn, tòa nhà của hãng Đầu Ngựa đã đứng bên bến sông gần nửa thế kỷ. Với người thanh niên đang tìm đường ra nước ngoài, những con tàu viễn dương đi về trên sông là hình ảnh cụ thể nhất của thế giới bên kia đại dương. Anh không có tiền mua vé, nên con đường duy nhất là xin làm việc trên tàu. Theo nhà nghiên cứu Nguyễn Đình Đầu, nơi anh xin việc là văn phòng hãng tàu trên lầu quán cà phê La Rotonde ở đường Catinat, chứ không phải tòa Nhà Rồng. Như vậy, xét về giấy tờ, tòa Nhà Rồng không trực tiếp gắn với việc nhận người phụ bếp Văn Ba. Nhưng trong ký ức của người dân, bến sông có đôi rồng đã trở thành biểu tượng của cả thương cảng Sài Gòn, nơi con tàu năm 1911 nhổ neo. Lịch sử có những sự trùng hợp giàu ý nghĩa. Tòa nhà dựng lên để phục vụ những chuyến tàu của chế độ thuộc địa, về sau lại được chọn để lưu giữ ký ức về người đã dành trọn đời đấu tranh xóa bỏ chế độ ấy."},{"t":"Số phận của hãng tàu. Hãng Messageries Maritimes còn tồn tại thêm hơn sáu mươi năm sau chuyến đi năm 1911. Trong Chiến tranh thế giới thứ nhất, nhiều tàu của hãng bị trưng dụng chở quân, và hãng mất gần một phần ba đội tàu. Sau đó là thời của những tàu khách lớn trên tuyến Viễn Đông, rồi Chiến tranh thế giới thứ hai và làn sóng giải phóng dân tộc ở các thuộc địa. Năm 1955, sau thất bại của Pháp ở Đông Dương, tòa Nhà Rồng được chuyển giao cho chính quyền Sài Gòn cũ. Mối gắn bó gần một thế kỷ giữa hãng tàu và tòa nhà chấm dứt. Khi máy bay dần thay thế tàu biển trên những chặng đường dài, các tuyến tàu khách của hãng cũng thưa dần. Ngày 23/2/1977, Messageries Maritimes chính thức chấm dứt hoạt động. Nhà nước Pháp sáp nhập hãng với Compagnie Générale Transatlantique thành Công ty Hàng hải Tổng hợp, viết tắt là CGM. Năm 1999, CGM hợp nhất với hãng CMA, tạo nên tập đoàn vận tải biển CMA CGM ngày nay."},{"t":"Bạn có biết? Theo tài liệu lịch sử của hãng, trong Chiến tranh thế giới thứ nhất, gần một phần ba đội tàu Messageries Maritimes, tức 25 chiếc, đã bị phá hủy."},{"t":"Đọc tấm ảnh hôm nay. Hơn một trăm sáu mươi năm sau ngày hoàn thành, tòa nhà trong tấm ảnh vẫn đứng ở vị trí cũ bên ngã ba sông, nay mang địa chỉ số 1 đường Nguyễn Tất Thành. Nó đã qua tay nhiều chủ: hãng tàu Pháp, chính quyền Sài Gòn cũ, quân đội Mỹ, rồi ngành đường biển Việt Nam sau năm 1975. Năm 1979, nơi đây trở thành nơi lưu niệm Chủ tịch Hồ Chí Minh. Từ ngày 30/10/1995, tòa nhà là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh (xem chuyên đề Bến Nhà Rồng ngày nay). Đặt tấm ảnh cũ cạnh tòa nhà hôm nay, người xem có thể tự mình so sánh. Dòng chữ “Direction de la Cie des Messageries Maritimes” đã thuộc về quá khứ, cùng với hãng tàu từng điều hành những chuyến tàu nối thuộc địa với chính quốc. Còn tòa nhà thì mang một sứ mệnh hoàn toàn mới. Nó kể lại câu chuyện của người thanh niên từng ra đi từ bến cảng này, để rồi trở về lãnh đạo dân tộc giành độc lập."}],"so_chu":1926},{"i":5,"tieu_de_bang":"Bến cảng Sài Gòn đầu thế kỷ XX, tàu viễn dương neo trên sông","tieu_de":"Mũi Tán Dóc và con tàu Paul-Lecat: tấm bưu ảnh kể chuyện thương cảng Sài Gòn","sapo":"Trên tấm bưu ảnh cũ, một con tàu viễn dương buông neo giữa dòng sông Sài Gòn, trước mũi đất mà dân Sài Gòn xưa gọi đùa là “Mũi Tán Dóc”. Con tàu ấy được hạ thủy ở Pháp vào mùa xuân năm 1911, đúng lúc Nguyễn Tất Thành đang học nghề ở Sài Gòn. Nó không phải con tàu đưa anh đi. Nhưng đọc kỹ, tấm ảnh kể được rất nhiều về thương cảng mà người thanh niên ấy từng ngày ngày lui tới.","bia":{"src":"textures/ht/ht_anh_saigon_la_pointe_des_blagueurs_le_paul_lecat_sur.jpg","credit":"Ảnh: Francis Alexandre Decoly · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Dòng chữ trên tấm bưu ảnh","text":"Tấm ảnh là một bưu ảnh mang dòng chữ tiếng Pháp “Saigon. La Pointe des Blagueurs – Le Paul-Lecat sur rade”. Dịch sang tiếng Việt, đó là “Sài Gòn. Mũi Tán Dóc – Tàu Paul-Lecat neo giữa sông”. Chữ “sur rade” cho biết con tàu đang thả neo ở vùng nước neo đậu, chứ không cập sát cầu tàu. Thông tin lưu trữ ghi tấm bưu ảnh gắn với tên Francis Alexandre Decoly, năm 1919. Cùng mẫu bưu ảnh này hiện có trong bộ sưu tập số của Thư viện Công cộng New York.\n\nCần nói rõ ngay từ đầu: Paul-Lecat là tàu khách của hãng Messageries Maritimes. Nó không phải tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis, con tàu đã đưa Nguyễn Tất Thành rời Tổ quốc năm 1911. Giá trị của tấm ảnh nằm ở chỗ khác. Nó cho ta nhìn thấy dòng sông, bến cảng và những con tàu viễn dương trong đúng những năm người thanh niên ấy chuẩn bị lên đường, và cả những năm anh đã ở bên kia đại dương.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_saigon_la_pointe_des_blagueurs_le_paul_lecat_sur.jpg","chu_thich":"Bến cảng Sài Gòn đầu thế kỷ XX, tàu viễn dương neo trên sông – bưu ảnh “La Pointe des Blagueurs – Le Paul-Lecat sur rade”.","credit":"Ảnh: Francis Alexandre Decoly · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Người phát hành bưu ảnh","text":"Theo trang nghiên cứu “Photographes d’Asie (1840–1944)” về những người làm ảnh ở châu Á thời thuộc địa, Decoly không phải thợ ảnh. Ông là một người kinh doanh ở Sài Gòn, làm nghề quản lý tài sản phá sản và đại diện thương mại, đồng thời phát hành bưu ảnh trong khoảng những năm 1905 – 1924. Cơ sở của ông đặt ở số 10 đại lộ Charner, nay là đường Nguyễn Huệ. Bưu ảnh của ông ban đầu in chữ tắt “A.F.D.”, về sau mang nhãn hiệu “La Pagode” với biểu tượng ngọn tháp chùa. Loạt ảnh ông phát hành không chỉ có Sài Gòn mà còn có Campuchia và Lào.\n\nĐầu thế kỷ XX là thời hoàng kim của bưu ảnh. Người châu Âu ở thuộc địa mua bưu ảnh để gửi về chính quốc, vừa làm thư vừa làm quà. Vì bán cho người châu Âu, những tấm thiếp thường chọn góc đẹp nhất: dòng sông rộng, con tàu lớn, bến cảng ngăn nắp. Người phu khuân vác, người thợ, người làm thuê hiếm khi là nhân vật chính. Nhờ những tấm thiếp ấy, nhiều cảnh Sài Gòn xưa còn lưu lại đến nay. Nhưng người xem hôm nay cần đọc chúng với con mắt tỉnh táo.","doc":2},{"loai":"doan","tieu_de":"Mũi đất của những người tán dóc","text":"Pointe des Blagueurs là mũi đất ở ngã ba rạch Bến Nghé và sông Sài Gòn, bên phía trung tâm thành phố. Theo báo Thanh Niên, các bợm rượu thời ấy đặt cho mũi đất cái tên khôi hài “Mũi đất bọn tán dóc”, và người Sài Gòn quen gọi là Mũi Tán Dóc. Ngay trên mũi đất có một công trình quan trọng với tàu bè. Đó là cột tín hiệu mà người Pháp gọi là “Mât des signaux”, dựng năm 1865, về sau người Việt gọi là cột cờ Thủ Ngữ.\n\nCột tín hiệu có nhiệm vụ truyền hiệu lệnh và thông tin cho tàu thuyền qua lại trên sông. Ban ngày, người ta dùng cờ màu hoặc quả cầu đen; ban đêm là đèn trắng hay đỏ. Đầu thế kỷ XX, cột kim loại được nâng cao hơn 30 mét, có thêm sàn đứng. Những con tàu lớn như Paul-Lecat ra vào cảng đều nằm trong tầm những tín hiệu ấy. Nhìn kỹ bối cảnh, tấm bưu ảnh ghi lại đúng một ngã ba đường thủy của Sài Gòn, nơi sông lớn gặp rạch Bến Nghé, nơi tàu biển gặp ghe thuyền từ Chợ Lớn.","doc":3},{"loai":"ban_co_biet","text":"Mũi Tán Dóc nằm ngay đối diện Bến Nhà Rồng, chỉ cách cửa rạch Bến Nghé. Vì thế, con tàu Paul-Lecat của hãng Messageries Maritimes trong ảnh đang neo không xa trụ sở của chính hãng mình, tức tòa Nhà Rồng (xem chuyên đề Trụ sở hãng Messageries Maritimes).","nguon_ten":"Báo Thanh Niên – “Cột cờ Thủ Ngữ – nơi tán dóc của dân Sài Gòn xưa” (Lam Yên, 9/8/2026); Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh","doc":4},{"loai":"doan","tieu_de":"Paul-Lecat, con tàu hạ thủy năm 1911","text":"Theo trang bách khoa về hãng Messageries Maritimes, Paul-Lecat được đóng tại xưởng La Ciotat, gần Marseille. Ban đầu con tàu được dự tính cho tuyến Nam Mỹ với tên Buenos Ayres, rồi được đặt theo tên ông Paul Lecat, Tổng giám đốc của hãng. Tàu hạ thủy ngày 19/3/1911. Cũng vào những tháng ấy, ở Sài Gòn, Nguyễn Tất Thành đang học nghề ở trường Bá Nghệ và tìm cách ra nước ngoài.\n\nPaul-Lecat là một tàu khách lớn của thời ấy: dài hơn 161 mét, rộng gần 19 mét, tổng dung tích 12.988 tấn đăng ký. Tàu có 200 chỗ hạng nhất, 184 chỗ hạng hai, 109 chỗ hạng ba, cùng 826 suất cho người đi tàu theo chế độ khẩu phần. Hai máy hơi nước với mười hai nồi hơi cho công suất khoảng 11.000 mã lực, tốc độ khi chạy thử đạt 18 hải lý mỗi giờ. Ngày 22/9/1912, con tàu bắt đầu phục vụ trên tuyến Viễn Đông, tuyến có bến ghé Sài Gòn. Vì vậy, tấm bưu ảnh chắc chắn ra đời sau thời điểm ấy, phù hợp với niên đại năm 1919 mà thông tin lưu trữ ghi lại.","doc":5},{"loai":"anh","src":"textures/bang_w/G04_5_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bến cảng Sài Gòn đầu thế kỷ XX, tàu viễn dương neo trên sông”, nhìn từ xa."},{"loai":"doan","tieu_de":"Hai con tàu, hai thế giới","text":"Đặt Paul-Lecat cạnh Amiral Latouche-Tréville, ta thấy rõ hai thế giới trên biển. Một bên là tàu khách của hãng thư tín lớn trên tuyến Viễn Đông, với hàng trăm chỗ hạng nhất, hạng hai cho những hành khách có tiền. Bên kia là một tàu chở hàng kiêm chở khách của hãng Chargeurs Réunis, hạ thủy năm 1904, trọng tải 5.572 tấn. Ở đó, người phụ bếp, thủy thủ, thợ máy làm việc quần quật suốt hải trình.\n\nNgười phụ bếp Văn Ba thuộc về thế giới thứ hai. Công việc của anh bắt đầu từ lúc trời chưa sáng, giữa bếp lò, than đá và hầm lạnh của con tàu (xem chuyên đề Người phụ bếp Văn Ba). Hai con tàu cùng chạy trên con đường Marseille – Sài Gòn qua kênh Suez. Nhưng chỗ đứng của con người trên hai con tàu ấy cách nhau cả một trật tự xã hội thuộc địa. Người thanh niên Nguyễn Tất Thành chấp nhận đứng ở bậc thấp nhất của trật tự ấy để được tận mắt nhìn thấy các nước phương Tây.","doc":6},{"loai":"doan","tieu_de":"Một dòng sông dẫn ra biển","text":"Sài Gòn không nằm sát biển mà ở bên một con sông sâu, đủ cho tàu lớn ngược vào tận thành phố. Theo báo Nhân Dân, ngày 22/2/1860, chính quyền thực dân quyết định mở cảng Sài Gòn. Năm 1862, việc xây dựng cảng được triển khai, và cảng bắt đầu đón tàu buôn quốc tế với tên gọi Thương cảng Sài Gòn. Ngày 2/1/1914, cảng được công nhận chính thức là cảng công cộng của Đông Dương thuộc Pháp. Suốt thời Pháp thuộc, đây là cảng lớn nhất toàn cõi Đông Dương.\n\nTàu từ biển vào phải đi một chặng dài trên sông, qua vùng rừng ngập mặn Cần Giờ, rồi mới tới bến. Dọc bờ sông, kho hàng, cầu tàu, xưởng máy nối nhau. Những tín hiệu trên cột cờ Thủ Ngữ giúp tàu biết lúc nào được vào, lúc nào phải chờ. Đến đầu năm 1911, khi Nguyễn Tất Thành vào Sài Gòn, bến cảng này đã hoạt động được hơn nửa thế kỷ. Với một người muốn ra nước ngoài mà không có tiền, dòng sông ấy là lối ra duy nhất.","doc":7},{"loai":"anh","src":"textures/bang_w/G04_5_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bến cảng Sài Gòn đầu thế kỷ XX, tàu viễn dương neo trên sông”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Dòng gạo chảy ra biển","text":"Hàng hóa chủ lực đi qua thương cảng là lúa gạo. Theo số liệu báo Tuổi Trẻ dẫn lại, năm 1860 Nam Kỳ chỉ xuất khẩu được khoảng 53.000 tấn gạo. Năm 1877, kênh Chợ Gạo khánh thành, mở đường đưa lúa từ miền Tây về Sài Gòn – Chợ Lớn. Nhờ vậy, năm 1880 lượng gạo xuất khẩu đã lên tới 294.500 tấn, và mười năm sau là 747.600 tấn. Năm 1910, bốn nhà máy xay lớn cùng lập Hiệp hội lúa gạo Viễn Đông tại Sài Gòn. Bốn nhà máy ấy sản xuất khoảng 2.650 tấn gạo mỗi ngày đêm, chiếm phân nửa sản lượng gạo xuất khẩu của Đông Dương.\n\nĐằng sau những con số ấy là sức lao động của rất nhiều người Việt: người chèo ghe chở lúa, người xay xát, người phu vác những bao tải nặng xuống tàu. Tấm bưu ảnh không cho thấy họ. Nhưng họ chính là những người mà Nguyễn Tất Thành đã sống cùng và quan sát suốt thời gian ở Sài Gòn. Họ làm ra hạt gạo xuất khẩu, còn đời sống của chính họ vẫn cực nhọc. Nghịch lý ấy là một trong những bài học đầu tiên của người thanh niên trước khi ra đi.","doc":8},{"loai":"ban_co_biet","text":"Trong Chiến tranh thế giới thứ nhất, Paul-Lecat bị trưng dụng chở quân. Ngày 21/12/1928, con tàu bốc cháy khi đang nằm trong ụ khô ở Marseille; xác tàu bị phá dỡ tại Genoa, nước Ý, vào tháng 4/1929. Con tàu trong tấm bưu ảnh chỉ tồn tại chưa đầy hai mươi năm.","nguon_ten":"L’encyclopédie des Messageries Maritimes – Le paquebot Paul Lecat (messageries-maritimes.org)","doc":9},{"loai":"doan","tieu_de":"Năm 1919 và một cái tên mới","text":"Niên đại 1919 ghi kèm tấm bưu ảnh gợi một sự trùng hợp đáng suy ngẫm. Trong khi những con tàu như Paul-Lecat vẫn đều đặn đi về giữa Marseille và Sài Gòn, thì ở Paris, người phụ bếp năm nào đã trở thành một nhà hoạt động chính trị. Tháng 6/1919, bản “Yêu sách của nhân dân An Nam” gửi tới Hội nghị Versailles được ký tên Nguyễn Ái Quốc (xem chuyên đề Sài Gòn – Bến Nhà Rồng). Tám năm sau ngày rời bến cảng Sài Gòn, tiếng nói đòi quyền lợi cho dân tộc bị trị đã được gửi tới các đoàn đại biểu dự hội nghị.\n\nTấm bưu ảnh, vì thế, có thể được đọc theo hai chiều thời gian. Nhìn ngược về trước năm 1911, nó cho thấy một thương cảng thuộc địa đã hoạt động hơn nửa thế kỷ, phục vụ bộ máy cai trị và việc khai thác lúa gạo. Nhìn về sau năm 1911, nó nhắc rằng chính những con đường biển mà chế độ thuộc địa dựng lên để cai trị cũng đã mở ra lối đi cho một người con của dân tộc bị trị.","doc":10},{"loai":"anh","src":"textures/bang_w/G04_5_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bến cảng Sài Gòn đầu thế kỷ XX, tàu viễn dương neo trên sông”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Cột cờ Thủ Ngữ vẫn đứng trên mũi đất năm xưa, nay ở số 2 đường Tôn Đức Thắng. Tháng 5/2016, công trình được Thành phố Hồ Chí Minh công nhận là di tích, và được trùng tu trong các năm 2020 – 2021. Bên kia cửa rạch Bến Nghé, tòa Nhà Rồng vẫn nhìn ra dòng sông, nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. Khu vực quanh bảo tàng và những dãy kho cũ bên bờ Khánh Hội đang được chỉnh trang thành không gian văn hóa công cộng (xem chuyên đề Bến Nhà Rồng ngày nay).\n\nĐứng bên bờ sông hôm nay, nhìn sang mũi đất có cột cờ, người xem có thể hình dung lại khung cảnh của tấm bưu ảnh hơn một trăm năm trước. Con tàu Paul-Lecat đã không còn, và hãng tàu chủ của nó cũng đã khép lại lịch sử. Nhưng dòng sông vẫn chảy ra biển theo con đường mà ngày 5/6/1911, một chiếc tàu buôn đã chở người phụ bếp trẻ đi về phía những đại dương xa lạ.","doc":11}],"nguon":["L’encyclopédie des Messageries Maritimes – Le paquebot Paul Lecat – https://www.messageries-maritimes.org/paulecat.htm","Photographes d’Asie (1840–1944) – Decoly, Francis Alexandre – http://photographesenoutremerasie.blogspot.com/2010/03/decoly-francis-alexandre.html","Báo Thanh Niên – “Cột cờ Thủ Ngữ – nơi tán dóc của dân Sài Gòn xưa” (Lam Yên, 9/8/2026) – https://thanhnien.vn/cot-co-thu-ngu-noi-tan-doc-cua-dan-sai-gon-xua-185260808205956251.htm","Báo Tuổi Trẻ – “Cột cờ Thủ Ngữ: Già hơn mọi người là cái chắc, chỉ mới 155 tuổi tây hà!” (30/8/2020) – https://tuoitre.vn/cot-co-thu-ngu-gia-hon-moi-nguoi-la-cai-chac-chi-moi-155-tuoi-tay-ha-20200830053925343.htm","Báo Nhân Dân – “Thương cảng đầu tiên ở Việt Nam” – https://nhandan.vn/thuong-cang-dau-tien-o-viet-nam-post565755.html","Báo Tuổi Trẻ – “Con kênh... xuất khẩu gạo” (Vân Trường, 12/5/2018) – https://tuoitre.vn/con-kenh-xuat-khau-gao-20180512115324927.htm"],"doc":[{"t":"Mũi Tán Dóc và con tàu Paul-Lecat: tấm bưu ảnh kể chuyện thương cảng Sài Gòn. Trên tấm bưu ảnh cũ, một con tàu viễn dương buông neo giữa dòng sông Sài Gòn, trước mũi đất mà dân Sài Gòn xưa gọi đùa là “Mũi Tán Dóc”. Con tàu ấy được hạ thủy ở Pháp vào mùa xuân năm 1911, đúng lúc Nguyễn Tất Thành đang học nghề ở Sài Gòn. Nó không phải con tàu đưa anh đi. Nhưng đọc kỹ, tấm ảnh kể được rất nhiều về thương cảng mà người thanh niên ấy từng ngày ngày lui tới."},{"t":"Dòng chữ trên tấm bưu ảnh. Tấm ảnh là một bưu ảnh mang dòng chữ tiếng Pháp “Saigon. La Pointe des Blagueurs – Le Paul-Lecat sur rade”. Dịch sang tiếng Việt, đó là “Sài Gòn. Mũi Tán Dóc – Tàu Paul-Lecat neo giữa sông”. Chữ “sur rade” cho biết con tàu đang thả neo ở vùng nước neo đậu, chứ không cập sát cầu tàu. Thông tin lưu trữ ghi tấm bưu ảnh gắn với tên Francis Alexandre Decoly, năm 1919. Cùng mẫu bưu ảnh này hiện có trong bộ sưu tập số của Thư viện Công cộng New York. Cần nói rõ ngay từ đầu: Paul-Lecat là tàu khách của hãng Messageries Maritimes. Nó không phải tàu Amiral Latouche-Tréville của hãng Chargeurs Réunis, con tàu đã đưa Nguyễn Tất Thành rời Tổ quốc năm 1911. Giá trị của tấm ảnh nằm ở chỗ khác. Nó cho ta nhìn thấy dòng sông, bến cảng và những con tàu viễn dương trong đúng những năm người thanh niên ấy chuẩn bị lên đường, và cả những năm anh đã ở bên kia đại dương."},{"t":"Người phát hành bưu ảnh. Theo trang nghiên cứu “Photographes d’Asie (1840–1944)” về những người làm ảnh ở châu Á thời thuộc địa, Decoly không phải thợ ảnh. Ông là một người kinh doanh ở Sài Gòn, làm nghề quản lý tài sản phá sản và đại diện thương mại, đồng thời phát hành bưu ảnh trong khoảng những năm 1905 – 1924. Cơ sở của ông đặt ở số 10 đại lộ Charner, nay là đường Nguyễn Huệ. Bưu ảnh của ông ban đầu in chữ tắt “A.F.D.”, về sau mang nhãn hiệu “La Pagode” với biểu tượng ngọn tháp chùa. Loạt ảnh ông phát hành không chỉ có Sài Gòn mà còn có Campuchia và Lào. Đầu thế kỷ XX là thời hoàng kim của bưu ảnh. Người châu Âu ở thuộc địa mua bưu ảnh để gửi về chính quốc, vừa làm thư vừa làm quà. Vì bán cho người châu Âu, những tấm thiếp thường chọn góc đẹp nhất: dòng sông rộng, con tàu lớn, bến cảng ngăn nắp. Người phu khuân vác, người thợ, người làm thuê hiếm khi là nhân vật chính. Nhờ những tấm thiếp ấy, nhiều cảnh Sài Gòn xưa còn lưu lại đến nay. Nhưng người xem hôm nay cần đọc chúng với con mắt tỉnh táo."},{"t":"Mũi đất của những người tán dóc. Pointe des Blagueurs là mũi đất ở ngã ba rạch Bến Nghé và sông Sài Gòn, bên phía trung tâm thành phố. Theo báo Thanh Niên, các bợm rượu thời ấy đặt cho mũi đất cái tên khôi hài “Mũi đất bọn tán dóc”, và người Sài Gòn quen gọi là Mũi Tán Dóc. Ngay trên mũi đất có một công trình quan trọng với tàu bè. Đó là cột tín hiệu mà người Pháp gọi là “Mât des signaux”, dựng năm 1865, về sau người Việt gọi là cột cờ Thủ Ngữ. Cột tín hiệu có nhiệm vụ truyền hiệu lệnh và thông tin cho tàu thuyền qua lại trên sông. Ban ngày, người ta dùng cờ màu hoặc quả cầu đen; ban đêm là đèn trắng hay đỏ. Đầu thế kỷ XX, cột kim loại được nâng cao hơn 30 mét, có thêm sàn đứng. Những con tàu lớn như Paul-Lecat ra vào cảng đều nằm trong tầm những tín hiệu ấy. Nhìn kỹ bối cảnh, tấm bưu ảnh ghi lại đúng một ngã ba đường thủy của Sài Gòn, nơi sông lớn gặp rạch Bến Nghé, nơi tàu biển gặp ghe thuyền từ Chợ Lớn."},{"t":"Bạn có biết? Mũi Tán Dóc nằm ngay đối diện Bến Nhà Rồng, chỉ cách cửa rạch Bến Nghé. Vì thế, con tàu Paul-Lecat của hãng Messageries Maritimes trong ảnh đang neo không xa trụ sở của chính hãng mình, tức tòa Nhà Rồng (xem chuyên đề Trụ sở hãng Messageries Maritimes)."},{"t":"Paul-Lecat, con tàu hạ thủy năm 1911. Theo trang bách khoa về hãng Messageries Maritimes, Paul-Lecat được đóng tại xưởng La Ciotat, gần Marseille. Ban đầu con tàu được dự tính cho tuyến Nam Mỹ với tên Buenos Ayres, rồi được đặt theo tên ông Paul Lecat, Tổng giám đốc của hãng. Tàu hạ thủy ngày 19/3/1911. Cũng vào những tháng ấy, ở Sài Gòn, Nguyễn Tất Thành đang học nghề ở trường Bá Nghệ và tìm cách ra nước ngoài. Paul-Lecat là một tàu khách lớn của thời ấy: dài hơn 161 mét, rộng gần 19 mét, tổng dung tích 12.988 tấn đăng ký. Tàu có 200 chỗ hạng nhất, 184 chỗ hạng hai, 109 chỗ hạng ba, cùng 826 suất cho người đi tàu theo chế độ khẩu phần. Hai máy hơi nước với mười hai nồi hơi cho công suất khoảng 11.000 mã lực, tốc độ khi chạy thử đạt 18 hải lý mỗi giờ. Ngày 22/9/1912, con tàu bắt đầu phục vụ trên tuyến Viễn Đông, tuyến có bến ghé Sài Gòn. Vì vậy, tấm bưu ảnh chắc chắn ra đời sau thời điểm ấy, phù hợp với niên đại năm 1919 mà thông tin lưu trữ ghi lại."},{"t":"Hai con tàu, hai thế giới. Đặt Paul-Lecat cạnh Amiral Latouche-Tréville, ta thấy rõ hai thế giới trên biển. Một bên là tàu khách của hãng thư tín lớn trên tuyến Viễn Đông, với hàng trăm chỗ hạng nhất, hạng hai cho những hành khách có tiền. Bên kia là một tàu chở hàng kiêm chở khách của hãng Chargeurs Réunis, hạ thủy năm 1904, trọng tải 5.572 tấn. Ở đó, người phụ bếp, thủy thủ, thợ máy làm việc quần quật suốt hải trình. Người phụ bếp Văn Ba thuộc về thế giới thứ hai. Công việc của anh bắt đầu từ lúc trời chưa sáng, giữa bếp lò, than đá và hầm lạnh của con tàu (xem chuyên đề Người phụ bếp Văn Ba). Hai con tàu cùng chạy trên con đường Marseille – Sài Gòn qua kênh Suez. Nhưng chỗ đứng của con người trên hai con tàu ấy cách nhau cả một trật tự xã hội thuộc địa. Người thanh niên Nguyễn Tất Thành chấp nhận đứng ở bậc thấp nhất của trật tự ấy để được tận mắt nhìn thấy các nước phương Tây."},{"t":"Một dòng sông dẫn ra biển. Sài Gòn không nằm sát biển mà ở bên một con sông sâu, đủ cho tàu lớn ngược vào tận thành phố. Theo báo Nhân Dân, ngày 22/2/1860, chính quyền thực dân quyết định mở cảng Sài Gòn. Năm 1862, việc xây dựng cảng được triển khai, và cảng bắt đầu đón tàu buôn quốc tế với tên gọi Thương cảng Sài Gòn. Ngày 2/1/1914, cảng được công nhận chính thức là cảng công cộng của Đông Dương thuộc Pháp. Suốt thời Pháp thuộc, đây là cảng lớn nhất toàn cõi Đông Dương. Tàu từ biển vào phải đi một chặng dài trên sông, qua vùng rừng ngập mặn Cần Giờ, rồi mới tới bến. Dọc bờ sông, kho hàng, cầu tàu, xưởng máy nối nhau. Những tín hiệu trên cột cờ Thủ Ngữ giúp tàu biết lúc nào được vào, lúc nào phải chờ. Đến đầu năm 1911, khi Nguyễn Tất Thành vào Sài Gòn, bến cảng này đã hoạt động được hơn nửa thế kỷ. Với một người muốn ra nước ngoài mà không có tiền, dòng sông ấy là lối ra duy nhất."},{"t":"Dòng gạo chảy ra biển. Hàng hóa chủ lực đi qua thương cảng là lúa gạo. Theo số liệu báo Tuổi Trẻ dẫn lại, năm 1860 Nam Kỳ chỉ xuất khẩu được khoảng 53.000 tấn gạo. Năm 1877, kênh Chợ Gạo khánh thành, mở đường đưa lúa từ miền Tây về Sài Gòn – Chợ Lớn. Nhờ vậy, năm 1880 lượng gạo xuất khẩu đã lên tới 294.500 tấn, và mười năm sau là 747.600 tấn. Năm 1910, bốn nhà máy xay lớn cùng lập Hiệp hội lúa gạo Viễn Đông tại Sài Gòn. Bốn nhà máy ấy sản xuất khoảng 2.650 tấn gạo mỗi ngày đêm, chiếm phân nửa sản lượng gạo xuất khẩu của Đông Dương. Đằng sau những con số ấy là sức lao động của rất nhiều người Việt: người chèo ghe chở lúa, người xay xát, người phu vác những bao tải nặng xuống tàu. Tấm bưu ảnh không cho thấy họ. Nhưng họ chính là những người mà Nguyễn Tất Thành đã sống cùng và quan sát suốt thời gian ở Sài Gòn. Họ làm ra hạt gạo xuất khẩu, còn đời sống của chính họ vẫn cực nhọc. Nghịch lý ấy là một trong những bài học đầu tiên của người thanh niên trước khi ra đi."},{"t":"Bạn có biết? Trong Chiến tranh thế giới thứ nhất, Paul-Lecat bị trưng dụng chở quân. Ngày 21/12/1928, con tàu bốc cháy khi đang nằm trong ụ khô ở Marseille; xác tàu bị phá dỡ tại Genoa, nước Ý, vào tháng 4/1929. Con tàu trong tấm bưu ảnh chỉ tồn tại chưa đầy hai mươi năm."},{"t":"Năm 1919 và một cái tên mới. Niên đại 1919 ghi kèm tấm bưu ảnh gợi một sự trùng hợp đáng suy ngẫm. Trong khi những con tàu như Paul-Lecat vẫn đều đặn đi về giữa Marseille và Sài Gòn, thì ở Paris, người phụ bếp năm nào đã trở thành một nhà hoạt động chính trị. Tháng 6/1919, bản “Yêu sách của nhân dân An Nam” gửi tới Hội nghị Versailles được ký tên Nguyễn Ái Quốc (xem chuyên đề Sài Gòn – Bến Nhà Rồng). Tám năm sau ngày rời bến cảng Sài Gòn, tiếng nói đòi quyền lợi cho dân tộc bị trị đã được gửi tới các đoàn đại biểu dự hội nghị. Tấm bưu ảnh, vì thế, có thể được đọc theo hai chiều thời gian. Nhìn ngược về trước năm 1911, nó cho thấy một thương cảng thuộc địa đã hoạt động hơn nửa thế kỷ, phục vụ bộ máy cai trị và việc khai thác lúa gạo. Nhìn về sau năm 1911, nó nhắc rằng chính những con đường biển mà chế độ thuộc địa dựng lên để cai trị cũng đã mở ra lối đi cho một người con của dân tộc bị trị."},{"t":"Dấu tích hôm nay. Cột cờ Thủ Ngữ vẫn đứng trên mũi đất năm xưa, nay ở số 2 đường Tôn Đức Thắng. Tháng 5/2016, công trình được Thành phố Hồ Chí Minh công nhận là di tích, và được trùng tu trong các năm 2020 – 2021. Bên kia cửa rạch Bến Nghé, tòa Nhà Rồng vẫn nhìn ra dòng sông, nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. Khu vực quanh bảo tàng và những dãy kho cũ bên bờ Khánh Hội đang được chỉnh trang thành không gian văn hóa công cộng (xem chuyên đề Bến Nhà Rồng ngày nay). Đứng bên bờ sông hôm nay, nhìn sang mũi đất có cột cờ, người xem có thể hình dung lại khung cảnh của tấm bưu ảnh hơn một trăm năm trước. Con tàu Paul-Lecat đã không còn, và hãng tàu chủ của nó cũng đã khép lại lịch sử. Nhưng dòng sông vẫn chảy ra biển theo con đường mà ngày 5/6/1911, một chiếc tàu buôn đã chở người phụ bếp trẻ đi về phía những đại dương xa lạ."}],"so_chu":1928},{"i":6,"tieu_de_bang":"Bến Nhà Rồng ngày nay – Bảo tàng Hồ Chí Minh","tieu_de":"Nhiều lần đổi chủ, một sứ mệnh mới: tòa Nhà Rồng trở thành Bảo tàng Hồ Chí Minh","sapo":"Tấm ảnh chụp ngày 29/9/2013 ghi lại tòa Nhà Rồng khi đã làm bảo tàng được gần hai mươi năm. Ít ai ngờ trước đó, tòa nhà từng qua tay một hãng tàu Pháp, chính quyền Sài Gòn cũ, quân đội Mỹ và ngành đường biển Việt Nam. Từ năm 1979, nơi đây kể câu chuyện về người thanh niên đã ra đi từ bến cảng này. Năm 2026, bảo tàng lại tạm đóng cửa để chuẩn bị cho một diện mạo mới.","bia":{"src":"textures/ht/ht_anh_ho_chi_minh_museum_saigon.jpg","credit":"Ảnh: Gary Todd · CC0 · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Tấm ảnh năm 2013","text":"Tấm ảnh do Gary Todd chụp ngày 29/9/2013. Tác giả đã để tấm ảnh ở chế độ CC0, tức từ bỏ mọi quyền, nên ai cũng có thể sử dụng tự do. Khi ấy, tòa nhà trong ảnh đã đứng bên sông Sài Gòn tròn một trăm năm mươi năm, và mang danh Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh được mười tám năm.\n\nĐịa chỉ của bảo tàng là số 1 đường Nguyễn Tất Thành. Con đường chạy qua trước bến mang chính tên người thanh niên đã rời Sài Gòn năm 1911. Sau đợt sắp xếp lại đơn vị hành chính năm 2025, địa chỉ ấy thuộc phường Xóm Chiếu, Thành phố Hồ Chí Minh. Bảo tàng trực thuộc Sở Văn hóa và Thể thao Thành phố, và nằm trong hệ thống các bảo tàng, di tích lưu niệm Chủ tịch Hồ Chí Minh trên cả nước. Nhìn tấm ảnh, ít ai đoán được rằng để có vai trò hôm nay, tòa nhà đã trải qua nhiều lần đổi chủ.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_museum_saigon.jpg","chu_thich":"Bến Nhà Rồng ngày nay — Bảo tàng Hồ Chí Minh, chi nhánh TP. Hồ Chí Minh (ảnh chụp ngày 29/9/2013).","credit":"Ảnh: Gary Todd · CC0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những lần đổi chủ","text":"Theo tư liệu của bảo tàng, tòa nhà được xây từ giữa năm 1862 và hoàn thành năm 1863, làm trụ sở của hãng Messageries Impériales, năm 1870 đổi tên là Messageries Maritimes (xem chuyên đề Trụ sở hãng Messageries Maritimes). Gần một thế kỷ, đây là cơ ngơi của hãng tàu Pháp. Năm 1955, sau thất bại của Pháp ở Đông Dương, tòa nhà được chuyển giao cho chính quyền Sài Gòn cũ. Cũng sau năm 1955, đôi rồng trên nóc được thay bằng đôi rồng khác quay đầu ra ngoài.\n\nNăm 1965, quân đội Mỹ sử dụng tòa nhà làm trụ sở. Sau ngày miền Nam hoàn toàn giải phóng, 30/4/1975, Nhà Rồng do Cục Đường biển Việt Nam quản lý. Chỉ trong khoảng hai mươi năm, tòa nhà đã đổi chủ ba lần. Phải đến cuối thập niên 1970, Nhà Rồng mới được giao một sứ mệnh hoàn toàn khác.","doc":2},{"loai":"moc","items":[["giữa 1862 – 1863","Xây tòa trụ sở hãng Messageries Impériales bên sông Sài Gòn"],["1955","Tòa nhà được chuyển giao cho chính quyền Sài Gòn cũ"],["1965","Quân đội Mỹ sử dụng tòa nhà làm trụ sở"],["sau 30/4/1975","Cục Đường biển Việt Nam quản lý tòa nhà"],["9/7/1979","Quyết định số 1315/QĐ-UB công nhận nơi đây là Di tích lưu niệm Chủ tịch Hồ Chí Minh"],["9/1979","Mở cửa đón khách, nhân kỷ niệm mười năm ngày Chủ tịch Hồ Chí Minh đi xa"],["30/10/1995","Thành lập Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh"],["6/2003","Khánh thành tượng đồng “Nguyễn Tất Thành ra đi tìm đường cứu nước” giữa sân bảo tàng"],["7/5/2026","Tạm dừng đón khách để cải tạo, chỉnh trang khuôn viên"],["1/7/2026","Khởi công dự án Công viên văn hóa Bến Nhà Rồng – Khánh Hội"]],"doc":3},{"loai":"doan","tieu_de":"Năm 1979: một sứ mệnh mới","text":"Ngày 9/7/1979, Ủy ban nhân dân Thành phố Hồ Chí Minh ra Quyết định số 1315/QĐ-UB, công nhận nơi đây là Di tích lưu niệm Chủ tịch Hồ Chí Minh. Tháng 9/1979, nhân kỷ niệm mười năm ngày Chủ tịch Hồ Chí Minh đi xa, khu lưu niệm mở cửa đón khách. Phần trưng bày đầu tiên mang tên “Sự nghiệp tìm đường cứu nước của Chủ tịch Hồ Chí Minh (1890 – 1945)”. Một tòa nhà từng phục vụ những chuyến tàu của chế độ thuộc địa từ đây trở thành nơi kể lại hành trình của người đã đấu tranh xóa bỏ chế độ ấy.\n\nCó thể hiểu vì sao Nhà Rồng được chọn. Trong ký ức của người dân cả nước, Bến Nhà Rồng gắn liền với ngày 5/6/1911, khi người thanh niên Nguyễn Tất Thành rời bến cảng Sài Gòn. Các nhà nghiên cứu vẫn bàn luận về vị trí chính xác nơi con tàu năm ấy neo đậu (xem chuyên đề Bến cảng Sài Gòn). Nhưng Nhà Rồng là công trình có từ những năm đầu của thương cảng, dễ nhận ra với đôi rồng trên nóc. Đặt khu lưu niệm ở đây là đặt câu chuyện về cuộc ra đi vào đúng không gian của nó.","doc":4},{"loai":"anh","src":"textures/bang_w/G04_6_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bến Nhà Rồng ngày nay – Bảo tàng Hồ Chí Minh”, nhìn từ xa."},{"loai":"doan","tieu_de":"Năm 1995: một bảo tàng chính thức","text":"Ngày 30/10/1995, theo Quyết định số 7492/QĐ-UB, khu lưu niệm chính thức trở thành Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. Nhiệm vụ của bảo tàng được xác định rõ: nghiên cứu, sưu tầm, kiểm kê, bảo quản và trưng bày tư liệu, hiện vật về cuộc đời và sự nghiệp cách mạng của Chủ tịch Hồ Chí Minh. Bảo tàng còn đón tiếp, hướng dẫn khách trong nước và quốc tế, tổ chức các hoạt động văn hóa, giáo dục.\n\nTheo Sở Văn hóa và Thể thao Thành phố, sau ba mươi lăm năm hoạt động kể từ ngày mở cửa, nơi đây đã đón trên 30 triệu lượt khách từ khắp nơi trong nước và quốc tế. Riêng năm 2025, bảo tàng đón hơn 550.000 lượt khách. Từ đầu năm 2026 đến trước khi tạm đóng cửa, con số đã là 135.141 lượt. Theo tư liệu giới thiệu, bảo tàng mở cửa hằng ngày, kể cả ngày lễ, ngày Tết.","doc":5},{"loai":"ban_co_biet","text":"Khi khu lưu niệm mở cửa tháng 9/1979, phần trưng bày đầu tiên chỉ giới thiệu chặng đường 1890 – 1945, tức hành trình tìm đường cứu nước của Chủ tịch Hồ Chí Minh. Ngày nay, các phòng trưng bày giới thiệu toàn bộ cuộc đời và sự nghiệp của Người.","nguon_ten":"Báo Công an Nhân dân – “Đầu xuân thăm Bến Nhà Rồng” (20/2/2018); Cổng thông tin về Chủ tịch Hồ Chí Minh – tham quan ảo Bến Nhà Rồng","doc":6},{"loai":"doan","tieu_de":"Những gì được lưu giữ","text":"Theo số liệu công bố năm 2026, bảo tàng lưu giữ khoảng 24.000 hiện vật, tư liệu và hình ảnh, với 15 bộ sưu tập quý hiếm. Không gian trưng bày gồm 10 phòng, trong đó có 5 phòng chuyên đề. Phần tham quan ảo trên Cổng thông tin về Chủ tịch Hồ Chí Minh giới thiệu tầng một với Phòng tưởng niệm Chủ tịch Hồ Chí Minh. Tầng này có các chủ đề “Hồ Chí Minh – Cuộc hành trình của thời đại”, “Bác Hồ với miền Nam, miền Nam với Bác Hồ”, “Sài Gòn những năm 1910” và “Việt Nam những Tuyên ngôn độc lập”. Tầng hai có chuyên đề về các đền thờ Bác Hồ ở Nam Bộ và chủ đề “Hồ Chí Minh và học tập suốt đời”.\n\nChủ đề “Sài Gòn những năm 1910” gắn trực tiếp với câu chuyện của gian trưng bày này: thành phố cảng nơi người thanh niên Nguyễn Tất Thành đã sống, học nghề và ra đi. Bản thân tòa nhà cũng là một hiện vật lớn. Hàng hiên vòm, cửa chớp, mái ngói và đôi rồng trên nóc giúp người xem hình dung một thương cảng thời thuộc địa, nơi những con tàu nối Sài Gòn với châu Âu từng neo đậu.","doc":7},{"loai":"doan","tieu_de":"Khuôn viên bên sông và ba địa chỉ","text":"Khuôn viên bảo tàng rộng khoảng 1,4 hécta, nằm ở mũi đất nơi rạch Bến Nghé gặp sông Sài Gòn. Báo Công an Nhân dân từng mô tả, ngoài phần diện tích xây dựng, khuôn viên phủ màu xanh của nhiều loại cây cỏ quý hiếm, hội tụ từ nhiều nơi trong và ngoài nước. Giữa sân, từ tháng 6/2003, là pho tượng đồng “Nguyễn Tất Thành ra đi tìm đường cứu nước”, nhìn về phía sông Sài Gòn (xem chuyên đề Tượng Nguyễn Tất Thành tại Bến Nhà Rồng).\n\nBến Nhà Rồng cũng là điểm khởi đầu tự nhiên cho những ai muốn lần theo dấu chân người thanh niên năm 1911 ở Thành phố Hồ Chí Minh hôm nay. Ở Chợ Lớn có Nhà số 5 Châu Văn Liêm, nơi anh tạm trú, được công nhận di tích lịch sử quốc gia ngày 16/11/1988. Trường Cao đẳng Kỹ thuật Cao Thắng, tức trường Bá Nghệ xưa, nơi anh học nghề, vẫn đang đào tạo người thợ kỹ thuật. Ba địa chỉ ấy ghép lại thành ba bước chuẩn bị: có chỗ dựa, có một nghề, rồi lên đường.","doc":8},{"loai":"anh","src":"textures/bang_w/G04_6_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bến Nhà Rồng ngày nay – Bảo tàng Hồ Chí Minh”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Năm 2026: tạm đóng cửa để chỉnh trang","text":"Ngày 7/5/2026, bảo tàng tạm dừng đón khách để thực hiện dự án chỉnh trang, cải tạo. Theo báo Tuổi Trẻ, kinh phí khoảng 68,7 tỉ đồng, dành cho các hạng mục cải tạo nền sân, hệ thống chiếu sáng, thoát nước, cảnh quan cây xanh, tưới tự động, bồn hoa và hồ sen. Việc cải tạo thuộc giai đoạn một của không gian văn hóa Bến Nhà Rồng – Khánh Hội. Theo kế hoạch ban đầu, công trình hoàn thành trong khoảng 120 ngày để kịp dịp Quốc khánh 2/9/2026.\n\nTheo báo Văn hóa, đến dịp 2/9, bảo tàng vẫn đang hoàn thiện các hạng mục nên chưa thể đón khách. Thời điểm mở cửa trở lại chờ cấp có thẩm quyền quyết định và sẽ được thông báo trên các kênh chính thức của bảo tàng. Trong thời gian đóng cửa, người yêu lịch sử vẫn có thể tham quan bảo tàng ảo trên trang bennharong.vn.","doc":9},{"loai":"doan","tieu_de":"Công viên văn hóa Bến Nhà Rồng – Khánh Hội","text":"Ngày 1/7/2026, Thành phố Hồ Chí Minh khởi công dự án Công viên văn hóa Bến Nhà Rồng – Khánh Hội và Cây xanh công cộng Bến Bạch Đằng. Dự án do Tập đoàn Sun Group đầu tư theo hình thức hợp đồng xây dựng – chuyển giao. Theo báo Dân trí, dự án rộng 73,3 hécta, tổng vốn khoảng 29.317 tỉ đồng. Trong đó, công viên văn hóa Nhà Rồng rộng 9,6 hécta, cộng với 1,4 hécta của bảo tàng, tạo thành không gian văn hóa – lịch sử khoảng 11 hécta.\n\nCông viên được thiết kế theo ý tưởng “9 chương – 9 dòng nước”, gợi những dấu mốc quan trọng trong cuộc đời Chủ tịch Hồ Chí Minh. Các dãy kho cũ ở Khánh Hội được chuyển thành không gian công cộng theo cách “vỏ cũ, lõi mới”, giữ lại khung thép nguyên bản. Theo báo Tuổi Trẻ, một điểm nhấn là cây cầu đi bộ mang hình tượng mũi thuyền, gợi nhắc cuộc ra đi năm 1911. Đường Nguyễn Tất Thành trước bảo tàng cũng được mở rộng.","doc":10},{"loai":"ban_co_biet","text":"Theo báo Tuổi Trẻ, trong dự án công viên văn hóa Bến Nhà Rồng – Khánh Hội, nhà đầu tư dự kiến phục dựng nguyên mẫu con tàu Amiral Latouche-Tréville, con tàu đã đưa người phụ bếp Văn Ba rời Sài Gòn năm 1911.","nguon_ten":"Báo Tuổi Trẻ – “Dự án Bến Nhà Rồng - Khánh Hội là nơi lịch sử được kể lại bằng kiến trúc” (1/7/2026)","doc":11},{"loai":"anh","src":"textures/bang_w/G04_6_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bến Nhà Rồng ngày nay – Bảo tàng Hồ Chí Minh”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Một khoảnh khắc giữa hai thời kỳ","text":"Hơn một trăm sáu mươi năm sau ngày hoàn thành, tòa Nhà Rồng vẫn đứng ở vị trí cũ, nhìn ra dòng sông mà những con tàu viễn dương từng đi về. Mỗi dịp 19/5, ngày sinh của Chủ tịch Hồ Chí Minh, và 5/6, Ngày Bác Hồ ra đi tìm đường cứu nước, nơi đây là một trong những địa chỉ tưởng niệm quen thuộc của người dân Thành phố. Khi bảo tàng mở cửa trở lại, khách tham quan có thể bắt đầu từ pho tượng đồng giữa sân. Sau đó, họ đi qua phòng tưởng niệm, rồi theo các phòng trưng bày lần lại cuộc đời Người.\n\nTấm ảnh năm 2013 vì thế ghi lại một khoảnh khắc giữa hai thời kỳ của tòa nhà: sau gần hai thập niên làm bảo tàng, trước cuộc chỉnh trang của năm 2026. Điều không thay đổi là ý nghĩa của nơi chốn. Từ một trụ sở hãng tàu thuộc địa, Nhà Rồng đã trở thành nơi người Việt Nam tìm về để nhớ lại cuộc ra đi của người thanh niên hai mươi mốt tuổi, và con đường ba mươi năm dẫn tới độc lập dân tộc.","doc":12}],"nguon":["Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh: Giới thiệu bảo tàng – https://bennharong.vn/gioi-thieu-bao-tang","Báo Tuổi Trẻ – Thông tin địa điểm: Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh (Quyết định 1315/QĐ-UB ngày 9/7/1979) – https://sso.tuoitre.vn/su-kien/binh-chon-diem-den/thong-tin-dia-diem/bao-tang-ho-chi-minh-chi-nhanh-tp-ho-chi-minh.pdf","Sở Văn hóa và Thể thao TP. Hồ Chí Minh – Bảo tàng Hồ Chí Minh, Chi nhánh TP. Hồ Chí Minh – https://svhtt.hochiminhcity.gov.vn/tin-chi-tiet/-/chi-tiet/bao-tang-ho-chi-minh-chi-nhanh-thanh-pho-ho-chi-minh-19084-2015.html","Báo Tuổi Trẻ – “Bảo tàng Hồ Chí Minh chi nhánh TP.HCM tạm ngừng mở cửa từ hôm nay 7-5 để sửa chữa” (7/5/2026) – https://tuoitre.vn/bao-tang-ho-chi-minh-chi-nhanh-tp-hcm-tam-ngung-mo-cua-tu-hom-nay-7-5-de-sua-chua-20260507114255791.htm","Báo Văn hóa – “Bảo tàng Hồ Chí Minh - chi nhánh TP.HCM chưa mở cửa phục vụ khách dịp 2.9” – https://baovanhoa.vn/van-hoa/bao-tang-ho-chi-minh-chi-nhanh-tphcm-chua-mo-cua-phuc-vu-khach-dip-29-261444.html","Báo Dân trí – “Công viên Nhà Rồng - Khánh Hội bên sông Sài Gòn đẹp như tranh qua phối cảnh” (1/7/2026) – https://dantri.com.vn/thoi-su/cong-vien-nha-rong-khanh-hoi-ben-song-sai-gon-dep-nhu-tranh-qua-phoi-canh-20260701164224442.htm"],"doc":[{"t":"Nhiều lần đổi chủ, một sứ mệnh mới: tòa Nhà Rồng trở thành Bảo tàng Hồ Chí Minh. Tấm ảnh chụp ngày 29/9/2013 ghi lại tòa Nhà Rồng khi đã làm bảo tàng được gần hai mươi năm. Ít ai ngờ trước đó, tòa nhà từng qua tay một hãng tàu Pháp, chính quyền Sài Gòn cũ, quân đội Mỹ và ngành đường biển Việt Nam. Từ năm 1979, nơi đây kể câu chuyện về người thanh niên đã ra đi từ bến cảng này. Năm 2026, bảo tàng lại tạm đóng cửa để chuẩn bị cho một diện mạo mới."},{"t":"Tấm ảnh năm 2013. Tấm ảnh do Gary Todd chụp ngày 29/9/2013. Tác giả đã để tấm ảnh ở chế độ CC0, tức từ bỏ mọi quyền, nên ai cũng có thể sử dụng tự do. Khi ấy, tòa nhà trong ảnh đã đứng bên sông Sài Gòn tròn một trăm năm mươi năm, và mang danh Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh được mười tám năm. Địa chỉ của bảo tàng là số 1 đường Nguyễn Tất Thành. Con đường chạy qua trước bến mang chính tên người thanh niên đã rời Sài Gòn năm 1911. Sau đợt sắp xếp lại đơn vị hành chính năm 2025, địa chỉ ấy thuộc phường Xóm Chiếu, Thành phố Hồ Chí Minh. Bảo tàng trực thuộc Sở Văn hóa và Thể thao Thành phố, và nằm trong hệ thống các bảo tàng, di tích lưu niệm Chủ tịch Hồ Chí Minh trên cả nước. Nhìn tấm ảnh, ít ai đoán được rằng để có vai trò hôm nay, tòa nhà đã trải qua nhiều lần đổi chủ."},{"t":"Những lần đổi chủ. Theo tư liệu của bảo tàng, tòa nhà được xây từ giữa năm 1862 và hoàn thành năm 1863, làm trụ sở của hãng Messageries Impériales, năm 1870 đổi tên là Messageries Maritimes (xem chuyên đề Trụ sở hãng Messageries Maritimes). Gần một thế kỷ, đây là cơ ngơi của hãng tàu Pháp. Năm 1955, sau thất bại của Pháp ở Đông Dương, tòa nhà được chuyển giao cho chính quyền Sài Gòn cũ. Cũng sau năm 1955, đôi rồng trên nóc được thay bằng đôi rồng khác quay đầu ra ngoài. Năm 1965, quân đội Mỹ sử dụng tòa nhà làm trụ sở. Sau ngày miền Nam hoàn toàn giải phóng, 30/4/1975, Nhà Rồng do Cục Đường biển Việt Nam quản lý. Chỉ trong khoảng hai mươi năm, tòa nhà đã đổi chủ ba lần. Phải đến cuối thập niên 1970, Nhà Rồng mới được giao một sứ mệnh hoàn toàn khác."},{"t":"Các mốc thời gian. giữa 1862 – 1863: Xây tòa trụ sở hãng Messageries Impériales bên sông Sài Gòn. 1955: Tòa nhà được chuyển giao cho chính quyền Sài Gòn cũ. 1965: Quân đội Mỹ sử dụng tòa nhà làm trụ sở. sau 30/4/1975: Cục Đường biển Việt Nam quản lý tòa nhà. 9/7/1979: Quyết định số 1315/QĐ-UB công nhận nơi đây là Di tích lưu niệm Chủ tịch Hồ Chí Minh. 9/1979: Mở cửa đón khách, nhân kỷ niệm mười năm ngày Chủ tịch Hồ Chí Minh đi xa. 30/10/1995: Thành lập Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. 6/2003: Khánh thành tượng đồng “Nguyễn Tất Thành ra đi tìm đường cứu nước” giữa sân bảo tàng. 7/5/2026: Tạm dừng đón khách để cải tạo, chỉnh trang khuôn viên. 1/7/2026: Khởi công dự án Công viên văn hóa Bến Nhà Rồng – Khánh Hội."},{"t":"Năm 1979: một sứ mệnh mới. Ngày 9/7/1979, Ủy ban nhân dân Thành phố Hồ Chí Minh ra Quyết định số 1315/QĐ-UB, công nhận nơi đây là Di tích lưu niệm Chủ tịch Hồ Chí Minh. Tháng 9/1979, nhân kỷ niệm mười năm ngày Chủ tịch Hồ Chí Minh đi xa, khu lưu niệm mở cửa đón khách. Phần trưng bày đầu tiên mang tên “Sự nghiệp tìm đường cứu nước của Chủ tịch Hồ Chí Minh (1890 – 1945)”. Một tòa nhà từng phục vụ những chuyến tàu của chế độ thuộc địa từ đây trở thành nơi kể lại hành trình của người đã đấu tranh xóa bỏ chế độ ấy. Có thể hiểu vì sao Nhà Rồng được chọn. Trong ký ức của người dân cả nước, Bến Nhà Rồng gắn liền với ngày 5/6/1911, khi người thanh niên Nguyễn Tất Thành rời bến cảng Sài Gòn. Các nhà nghiên cứu vẫn bàn luận về vị trí chính xác nơi con tàu năm ấy neo đậu (xem chuyên đề Bến cảng Sài Gòn). Nhưng Nhà Rồng là công trình có từ những năm đầu của thương cảng, dễ nhận ra với đôi rồng trên nóc. Đặt khu lưu niệm ở đây là đặt câu chuyện về cuộc ra đi vào đúng không gian của nó."},{"t":"Năm 1995: một bảo tàng chính thức. Ngày 30/10/1995, theo Quyết định số 7492/QĐ-UB, khu lưu niệm chính thức trở thành Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. Nhiệm vụ của bảo tàng được xác định rõ: nghiên cứu, sưu tầm, kiểm kê, bảo quản và trưng bày tư liệu, hiện vật về cuộc đời và sự nghiệp cách mạng của Chủ tịch Hồ Chí Minh. Bảo tàng còn đón tiếp, hướng dẫn khách trong nước và quốc tế, tổ chức các hoạt động văn hóa, giáo dục. Theo Sở Văn hóa và Thể thao Thành phố, sau ba mươi lăm năm hoạt động kể từ ngày mở cửa, nơi đây đã đón trên 30 triệu lượt khách từ khắp nơi trong nước và quốc tế. Riêng năm 2025, bảo tàng đón hơn 550.000 lượt khách. Từ đầu năm 2026 đến trước khi tạm đóng cửa, con số đã là 135.141 lượt. Theo tư liệu giới thiệu, bảo tàng mở cửa hằng ngày, kể cả ngày lễ, ngày Tết."},{"t":"Bạn có biết? Khi khu lưu niệm mở cửa tháng 9/1979, phần trưng bày đầu tiên chỉ giới thiệu chặng đường 1890 – 1945, tức hành trình tìm đường cứu nước của Chủ tịch Hồ Chí Minh. Ngày nay, các phòng trưng bày giới thiệu toàn bộ cuộc đời và sự nghiệp của Người."},{"t":"Những gì được lưu giữ. Theo số liệu công bố năm 2026, bảo tàng lưu giữ khoảng 24.000 hiện vật, tư liệu và hình ảnh, với 15 bộ sưu tập quý hiếm. Không gian trưng bày gồm 10 phòng, trong đó có 5 phòng chuyên đề. Phần tham quan ảo trên Cổng thông tin về Chủ tịch Hồ Chí Minh giới thiệu tầng một với Phòng tưởng niệm Chủ tịch Hồ Chí Minh. Tầng này có các chủ đề “Hồ Chí Minh – Cuộc hành trình của thời đại”, “Bác Hồ với miền Nam, miền Nam với Bác Hồ”, “Sài Gòn những năm 1910” và “Việt Nam những Tuyên ngôn độc lập”. Tầng hai có chuyên đề về các đền thờ Bác Hồ ở Nam Bộ và chủ đề “Hồ Chí Minh và học tập suốt đời”. Chủ đề “Sài Gòn những năm 1910” gắn trực tiếp với câu chuyện của gian trưng bày này: thành phố cảng nơi người thanh niên Nguyễn Tất Thành đã sống, học nghề và ra đi. Bản thân tòa nhà cũng là một hiện vật lớn. Hàng hiên vòm, cửa chớp, mái ngói và đôi rồng trên nóc giúp người xem hình dung một thương cảng thời thuộc địa, nơi những con tàu nối Sài Gòn với châu Âu từng neo đậu."},{"t":"Khuôn viên bên sông và ba địa chỉ. Khuôn viên bảo tàng rộng khoảng 1,4 hécta, nằm ở mũi đất nơi rạch Bến Nghé gặp sông Sài Gòn. Báo Công an Nhân dân từng mô tả, ngoài phần diện tích xây dựng, khuôn viên phủ màu xanh của nhiều loại cây cỏ quý hiếm, hội tụ từ nhiều nơi trong và ngoài nước. Giữa sân, từ tháng 6/2003, là pho tượng đồng “Nguyễn Tất Thành ra đi tìm đường cứu nước”, nhìn về phía sông Sài Gòn (xem chuyên đề Tượng Nguyễn Tất Thành tại Bến Nhà Rồng). Bến Nhà Rồng cũng là điểm khởi đầu tự nhiên cho những ai muốn lần theo dấu chân người thanh niên năm 1911 ở Thành phố Hồ Chí Minh hôm nay. Ở Chợ Lớn có Nhà số 5 Châu Văn Liêm, nơi anh tạm trú, được công nhận di tích lịch sử quốc gia ngày 16/11/1988. Trường Cao đẳng Kỹ thuật Cao Thắng, tức trường Bá Nghệ xưa, nơi anh học nghề, vẫn đang đào tạo người thợ kỹ thuật. Ba địa chỉ ấy ghép lại thành ba bước chuẩn bị: có chỗ dựa, có một nghề, rồi lên đường."},{"t":"Năm 2026: tạm đóng cửa để chỉnh trang. Ngày 7/5/2026, bảo tàng tạm dừng đón khách để thực hiện dự án chỉnh trang, cải tạo. Theo báo Tuổi Trẻ, kinh phí khoảng 68,7 tỉ đồng, dành cho các hạng mục cải tạo nền sân, hệ thống chiếu sáng, thoát nước, cảnh quan cây xanh, tưới tự động, bồn hoa và hồ sen. Việc cải tạo thuộc giai đoạn một của không gian văn hóa Bến Nhà Rồng – Khánh Hội. Theo kế hoạch ban đầu, công trình hoàn thành trong khoảng 120 ngày để kịp dịp Quốc khánh 2/9/2026. Theo báo Văn hóa, đến dịp 2/9, bảo tàng vẫn đang hoàn thiện các hạng mục nên chưa thể đón khách. Thời điểm mở cửa trở lại chờ cấp có thẩm quyền quyết định và sẽ được thông báo trên các kênh chính thức của bảo tàng. Trong thời gian đóng cửa, người yêu lịch sử vẫn có thể tham quan bảo tàng ảo trên trang bennharong.vn."},{"t":"Công viên văn hóa Bến Nhà Rồng – Khánh Hội. Ngày 1/7/2026, Thành phố Hồ Chí Minh khởi công dự án Công viên văn hóa Bến Nhà Rồng – Khánh Hội và Cây xanh công cộng Bến Bạch Đằng. Dự án do Tập đoàn Sun Group đầu tư theo hình thức hợp đồng xây dựng – chuyển giao. Theo báo Dân trí, dự án rộng 73,3 hécta, tổng vốn khoảng 29.317 tỉ đồng. Trong đó, công viên văn hóa Nhà Rồng rộng 9,6 hécta, cộng với 1,4 hécta của bảo tàng, tạo thành không gian văn hóa – lịch sử khoảng 11 hécta. Công viên được thiết kế theo ý tưởng “9 chương – 9 dòng nước”, gợi những dấu mốc quan trọng trong cuộc đời Chủ tịch Hồ Chí Minh. Các dãy kho cũ ở Khánh Hội được chuyển thành không gian công cộng theo cách “vỏ cũ, lõi mới”, giữ lại khung thép nguyên bản. Theo báo Tuổi Trẻ, một điểm nhấn là cây cầu đi bộ mang hình tượng mũi thuyền, gợi nhắc cuộc ra đi năm 1911. Đường Nguyễn Tất Thành trước bảo tàng cũng được mở rộng."},{"t":"Bạn có biết? Theo báo Tuổi Trẻ, trong dự án công viên văn hóa Bến Nhà Rồng – Khánh Hội, nhà đầu tư dự kiến phục dựng nguyên mẫu con tàu Amiral Latouche-Tréville, con tàu đã đưa người phụ bếp Văn Ba rời Sài Gòn năm 1911."},{"t":"Một khoảnh khắc giữa hai thời kỳ. Hơn một trăm sáu mươi năm sau ngày hoàn thành, tòa Nhà Rồng vẫn đứng ở vị trí cũ, nhìn ra dòng sông mà những con tàu viễn dương từng đi về. Mỗi dịp 19/5, ngày sinh của Chủ tịch Hồ Chí Minh, và 5/6, Ngày Bác Hồ ra đi tìm đường cứu nước, nơi đây là một trong những địa chỉ tưởng niệm quen thuộc của người dân Thành phố. Khi bảo tàng mở cửa trở lại, khách tham quan có thể bắt đầu từ pho tượng đồng giữa sân. Sau đó, họ đi qua phòng tưởng niệm, rồi theo các phòng trưng bày lần lại cuộc đời Người. Tấm ảnh năm 2013 vì thế ghi lại một khoảnh khắc giữa hai thời kỳ của tòa nhà: sau gần hai thập niên làm bảo tàng, trước cuộc chỉnh trang của năm 2026. Điều không thay đổi là ý nghĩa của nơi chốn. Từ một trụ sở hãng tàu thuộc địa, Nhà Rồng đã trở thành nơi người Việt Nam tìm về để nhớ lại cuộc ra đi của người thanh niên hai mươi mốt tuổi, và con đường ba mươi năm dẫn tới độc lập dân tộc."}],"so_chu":1830},{"i":7,"tieu_de_bang":"Tượng Nguyễn Tất Thành tại Bến Nhà Rồng","tieu_de":"Pho tượng người thanh niên hai mươi mốt tuổi bên bến sông Sài Gòn","sapo":"Hình ảnh quen thuộc nhất về Bác Hồ là một ông cụ râu tóc bạc, hiền từ. Ở Bến Nhà Rồng thì khác: giữa sân bảo tàng là một người thanh niên, hướng mặt về phía dòng sông. Pho tượng đồng cao 3,3 mét ấy gợi lại khoảnh khắc trước lúc lên đường của Nguyễn Tất Thành, khi chưa ai biết đến tên anh.","bia":{"src":"textures/ht/ht_anh_tuong_nguyen_ai_quoc_nguyen_tat_thanh_nha_tuong_.jpg","credit":"Ảnh: vi:User:TDA · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Tấm ảnh chụp tháng 5/2010","text":"Tấm ảnh tư liệu được chụp ngày 13/5/2010, chỉ ít ngày trước lễ kỷ niệm 120 năm ngày sinh Chủ tịch Hồ Chí Minh. Người chụp là một thành viên của cộng đồng Wikipedia tiếng Việt, và tấm ảnh được chia sẻ ở dạng tự do sử dụng. Tên tệp ảnh gọi pho tượng bằng cả hai cái tên của Người: Nguyễn Ái Quốc và Nguyễn Tất Thành.\n\nỞ Bến Nhà Rồng, hình tượng người thanh niên năm 1911 hiện diện rõ nhất qua pho tượng đồng đặt giữa sân bảo tàng, mang tên “Nguyễn Tất Thành ra đi tìm đường cứu nước”. Đây không phải chân dung vị Chủ tịch nước mà nhiều thế hệ người Việt quen thuộc. Đó là một người thanh niên chưa có danh tiếng, chưa có tổ chức, chưa viết một bài báo nào. Anh chỉ có một quyết định đã chín muồi và đôi bàn tay lao động. Chọn khắc họa khoảnh khắc ấy, pho tượng mời người xem nhìn lại điểm khởi đầu của một cuộc đời, trước khi cuộc đời ấy gắn liền với vận mệnh cả dân tộc.","doc":1},{"loai":"anh","src":"textures/ht/ht_anh_tuong_nguyen_ai_quoc_nguyen_tat_thanh_nha_tuong_.jpg","chu_thich":"Tượng Nguyễn Tất Thành tại Bến Nhà Rồng (ảnh chụp ngày 13/5/2010).","credit":"Ảnh: vi:User:TDA · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Ngày khánh thành tháng Sáu năm 2003","text":"Theo báo VnExpress, pho tượng được Thành phố Hồ Chí Minh khánh thành vào đầu tháng 6/2003, dịp kỷ niệm 92 năm ngày Người ra đi tìm đường cứu nước. Tác giả là nhà điêu khắc Phạm Mười. Tượng đúc bằng đồng, cao 3,3 mét, nặng hơn 1 tấn. Bệ tượng hình vuông, mỗi cạnh 2 mét, cao 1,4 mét, ốp đá granite. Cổng thông tin về Chủ tịch Hồ Chí Minh cũng ghi các thông số tương tự: tượng cao 330 xăng-ti-mét, nặng 1.000 ki-lô-gam, khánh thành năm 2003.\n\nTượng đứng giữa sân Nhà Rồng, nhìn theo hướng bắc về phía sông Sài Gòn và Bến Bạch Đằng. Tính cả bệ, pho tượng cao khoảng 4,7 mét, đủ để nổi bật giữa khoảng sân rộng bên bờ sông. Người xem đứng dưới chân tượng phải ngước lên, rồi nhìn theo hướng nhìn của tượng ra phía dòng sông. Chính hướng nhìn ấy làm nên ý nghĩa của tác phẩm. Người thanh niên không nhìn về phía thành phố sau lưng, mà nhìn ra con đường thủy dẫn tới biển lớn và thế giới bên ngoài.","doc":2},{"loai":"ban_co_biet","text":"Cùng dịp khánh thành tượng đồng ngoài sân năm 2003, bảo tàng đón nhận thêm pho tượng “Bác Hồ đọc báo Nhân Dân” bằng đồng đỏ, cao 95 xăng-ti-mét, nặng 120 ki-lô-gam. Pho tượng do Ban Quản lý Lăng Chủ tịch Hồ Chí Minh ở Hà Nội tặng, đặt trong phòng tưởng niệm.","nguon_ten":"Báo VnExpress – “TP HCM khánh thành tượng Nguyễn Tất Thành” (5/6/2003)","doc":3},{"loai":"doan","tieu_de":"Người thanh niên trong tượng là ai?","text":"Pho tượng khắc họa Nguyễn Tất Thành ở tuổi hai mươi mốt. Anh sinh ngày 19/5/1890 tại quê ngoại làng Hoàng Trù, gần làng Kim Liên, huyện Nam Đàn, tỉnh Nghệ An. Tên lúc nhỏ là Nguyễn Sinh Cung; cha là cụ Phó bảng Nguyễn Sinh Sắc, mẹ là bà Hoàng Thị Loan. Về sau, anh được đổi tên là Nguyễn Tất Thành. Anh học chữ Hán từ nhỏ, rồi học tiếng Pháp, từng là học trò trường Quốc học Huế. Năm 1908, anh tham gia phong trào chống thuế của nông dân ở Huế.\n\nNhững năm 1909 – 1910, anh ở Bình Định, nơi thân phụ làm tri huyện Bình Khê. Sau đó anh vào Phan Thiết dạy học ở trường Dục Thanh, rồi đầu năm 1911 đến Sài Gòn. Như vậy, người phụ bếp trên tàu năm ấy là một thanh niên có học vấn, am hiểu cả Nho học lẫn Tây học. Anh đã đi qua gần suốt dải đất miền Trung trước khi tới thành phố cảng phương Nam, và tự nguyện chọn con đường lao động để đi ra thế giới.","doc":4},{"loai":"anh","src":"textures/bang_w/G04_7_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tượng Nguyễn Tất Thành tại Bến Nhà Rồng”, nhìn từ xa."},{"loai":"doan","tieu_de":"Từ Văn Ba đến Hồ Chí Minh","text":"Những cái tên của Người đánh dấu từng chặng đường. Ở Sài Gòn năm 1911, khi xin làm phụ bếp trên tàu Amiral Latouche-Tréville, anh dùng tên Văn Ba. Ngày 15/9/1911, từ Marseille, anh viết đơn xin vào học Trường Thuộc địa và ký tên Nguyễn Tất Thành. Tháng 6/1919, bản “Yêu sách của nhân dân An Nam” gửi tới Hội nghị Versailles được ký tên Nguyễn Ái Quốc. Cái tên ấy về sau trở thành biểu tượng của phong trào giải phóng các dân tộc thuộc địa. Từ tháng 8/1942, Người dùng tên Hồ Chí Minh.\n\nGiữa những cái tên ấy là rất nhiều bí danh, bút danh khác, dùng trong những năm hoạt động bí mật ở nhiều nước. Tên tệp của tấm ảnh tư liệu ghép hai cái tên Nguyễn Ái Quốc và Nguyễn Tất Thành, như một cách nhắc rằng người thanh niên trên bến sông và nhà cách mạng nổi tiếng về sau là một. Pho tượng ở Bến Nhà Rồng mang cái tên gắn với cuộc ra đi: Nguyễn Tất Thành, người thanh niên chưa ai biết đến nhưng đã mang trong mình câu hỏi lớn về vận mệnh dân tộc.","doc":5},{"loai":"doan","tieu_de":"Người đi tìm hình của nước","text":"Năm 1960, nhà thơ Chế Lan Viên viết bài thơ “Người đi tìm hình của nước”, một bài thơ quen thuộc với nhiều thế hệ bạn đọc về cuộc ra đi năm 1911. Nhà thơ tưởng tượng mình hóa thành con sóng dưới con tàu, lặng lẽ tiễn người thanh niên rời bến. Hình ảnh ấy gần với cảm xúc của người đứng trước pho tượng ở Bến Nhà Rồng hôm nay. Họ muốn được tiễn đưa, được dõi theo một cuộc lên đường đã diễn ra lặng lẽ, không có nghi lễ nào.\n\nNhan đề bài thơ cũng là một cách hiểu sâu sắc về chuyến đi. Người thanh niên không đi để tìm một chỗ đứng cho riêng mình, mà đi tìm “hình của nước”, tức con đường và diện mạo cho một nước Việt Nam độc lập. Năm 1960 cũng là năm Chủ tịch Hồ Chí Minh bước sang tuổi bảy mươi. Nhìn lại từ mốc ấy, chuyến đi của người phụ bếp năm 1911 đã hiện ra với tầm vóc của một bước ngoặt lịch sử.","doc":6},{"loai":"trich","text":"Đất nước đẹp vô cùng. Nhưng Bác phải ra đi / Cho tôi làm sóng dưới con tàu đưa tiễn Bác","nguoi":"Chế Lan Viên","nguon_ten":"Bài thơ “Người đi tìm hình của nước”, 1960","doc":7},{"loai":"doan","tieu_de":"Những pho tượng của tuổi trẻ","text":"Hình tượng Nguyễn Tất Thành thời trẻ còn xuất hiện ở những nơi khác gắn với dấu chân anh trước năm 1911. Ở thành phố Quy Nhơn, ngày 18/5/2017, tỉnh Bình Định khánh thành tượng đài Nguyễn Sinh Sắc – Nguyễn Tất Thành, đúc bằng đồng, cao 15,5 mét kể cả bệ. Theo báo Tuổi Trẻ, đây là tượng đài đầu tiên trong cả nước tôn vinh cả Bác Hồ và thân phụ của Người. Công trình gắn với thời gian Nguyễn Tất Thành ở Bình Định những năm 1909 – 1910. Phía sau tượng là bức phù điêu dài 76 mét, tái hiện Việt Nam đầu thế kỷ XX dưới ách thuộc địa và hành trình của Người trước khi ra đi tìm đường cứu nước.\n\nĐặt cạnh nhau, những pho tượng ấy kể một câu chuyện liền mạch. Đó là người con của một gia đình nhà Nho yêu nước, đi dọc miền Trung, rồi tới bến cảng Sài Gòn. Pho tượng ở Bến Nhà Rồng đứng ở điểm cuối của chặng đường trong nước ấy, cũng là điểm đầu của ba mươi năm bôn ba nơi đất khách.","doc":8},{"loai":"anh","src":"textures/bang_w/G04_7_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tượng Nguyễn Tất Thành tại Bến Nhà Rồng”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Hướng nhìn về phía bến sông","text":"Từ sân Nhà Rồng, hướng bắc là cửa rạch Bến Nghé và bờ bên kia, nơi có mũi đất với cột cờ Thủ Ngữ và Bến Bạch Đằng (xem chuyên đề Bến cảng Sài Gòn đầu thế kỷ XX). Xa hơn là khu thương cảng ở đầu đường Charner xưa, nay là đường Nguyễn Huệ. Theo nhà nghiên cứu Nguyễn Đình Đầu, tàu hãng Chargeurs Réunis thời ấy cập cầu tàu lớn ở khu vực này. Vị trí chính xác nơi con tàu neo đậu năm 1911 vẫn còn được bàn luận.\n\nDù con tàu rời đi từ cầu tàu nào, điều không thay đổi là dòng sông. Pho tượng nhìn ra chính dòng Sài Gòn mà ngày 5/6/1911 đã đưa người phụ bếp trẻ ra biển. Từ đó, anh đi qua Singapore, Colombo, Port Said, tới Marseille, rồi đi khắp các châu lục. Ba mươi năm sau, ngày 28/1/1941, Người trở về Tổ quốc qua cột mốc 108 ở Cao Bằng. Ngày 2/9/1945, tại Quảng trường Ba Đình, Người đọc bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa.","doc":9},{"loai":"ban_co_biet","text":"Ngày tàu rời Sài Gòn, 5/6/1911, Nguyễn Tất Thành vừa bước sang tuổi hai mươi mốt được hơn hai tuần.","nguon_ten":"Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":10},{"loai":"anh","src":"textures/bang_w/G04_7_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tượng Nguyễn Tất Thành tại Bến Nhà Rồng”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Đứng trước pho tượng hôm nay","text":"Từ năm 2003, pho tượng trở thành điểm dừng chân đầu tiên của nhiều đoàn khách đến Bến Nhà Rồng. Với học sinh, sinh viên, pho tượng là một bài học lịch sử trực quan. Người thanh niên ra đi tìm đường cứu nước năm ấy cũng chỉ trạc tuổi các bạn trẻ đang đứng dưới chân tượng hôm nay. Với khách quốc tế, đây là dịp để biết rằng vị lãnh tụ của Việt Nam đã bắt đầu hành trình của mình như một người lao động bình thường trên một con tàu buôn.\n\nNăm 2026, khuôn viên bảo tàng, nơi đặt pho tượng, nằm trong đợt chỉnh trang với các hạng mục cải tạo nền sân, chiếu sáng, cây xanh, bồn hoa và hồ sen. Bảo tàng tạm dừng đón khách từ ngày 7/5/2026 (xem chuyên đề Bến Nhà Rồng ngày nay). Khi khuôn viên mới hoàn thành, pho tượng sẽ tiếp tục đón những người tìm về bến sông này. Câu hỏi mà pho tượng gửi tới người xem vẫn vậy: điều gì khiến một người hai mươi mốt tuổi dám rời xa quê hương để đi tìm con đường cho dân tộc mình?","doc":11}],"nguon":["Báo VnExpress – “TP HCM khánh thành tượng Nguyễn Tất Thành” (5/6/2003) – https://vnexpress.net/tp-hcm-khanh-thanh-tuong-nguyen-tat-thanh-1976382.html","Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh – Giới thiệu khái quát về Bảo tàng Hồ Chí Minh (Bến Nhà Rồng) – https://bennharong.hochiminh.vn/BenNhaRongdata/pano/info.html","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Chế Lan Viên, “Người đi tìm hình của nước” (1960)","Báo Tuổi Trẻ – “Khánh thành tượng đài Nguyễn Sinh Sắc - Nguyễn Tất Thành” (2017) – https://tuoitre.vn/khanh-thanh-tuong-dai-nguyen-sinh-sac-nguyen-tat-thanh-1316892.htm","Báo Thanh Niên – “Nơi Bác ra đi tìm đường cứu nước” (nhà nghiên cứu Nguyễn Đình Đầu) – https://thanhnien.vn/noi-bac-ra-di-tim-duong-cuu-nuoc-185241009213949499.htm"],"doc":[{"t":"Pho tượng người thanh niên hai mươi mốt tuổi bên bến sông Sài Gòn. Hình ảnh quen thuộc nhất về Bác Hồ là một ông cụ râu tóc bạc, hiền từ. Ở Bến Nhà Rồng thì khác: giữa sân bảo tàng là một người thanh niên, hướng mặt về phía dòng sông. Pho tượng đồng cao 3,3 mét ấy gợi lại khoảnh khắc trước lúc lên đường của Nguyễn Tất Thành, khi chưa ai biết đến tên anh."},{"t":"Tấm ảnh chụp tháng 5/2010. Tấm ảnh tư liệu được chụp ngày 13/5/2010, chỉ ít ngày trước lễ kỷ niệm 120 năm ngày sinh Chủ tịch Hồ Chí Minh. Người chụp là một thành viên của cộng đồng Wikipedia tiếng Việt, và tấm ảnh được chia sẻ ở dạng tự do sử dụng. Tên tệp ảnh gọi pho tượng bằng cả hai cái tên của Người: Nguyễn Ái Quốc và Nguyễn Tất Thành. Ở Bến Nhà Rồng, hình tượng người thanh niên năm 1911 hiện diện rõ nhất qua pho tượng đồng đặt giữa sân bảo tàng, mang tên “Nguyễn Tất Thành ra đi tìm đường cứu nước”. Đây không phải chân dung vị Chủ tịch nước mà nhiều thế hệ người Việt quen thuộc. Đó là một người thanh niên chưa có danh tiếng, chưa có tổ chức, chưa viết một bài báo nào. Anh chỉ có một quyết định đã chín muồi và đôi bàn tay lao động. Chọn khắc họa khoảnh khắc ấy, pho tượng mời người xem nhìn lại điểm khởi đầu của một cuộc đời, trước khi cuộc đời ấy gắn liền với vận mệnh cả dân tộc."},{"t":"Ngày khánh thành tháng Sáu năm 2003. Theo báo VnExpress, pho tượng được Thành phố Hồ Chí Minh khánh thành vào đầu tháng 6/2003, dịp kỷ niệm 92 năm ngày Người ra đi tìm đường cứu nước. Tác giả là nhà điêu khắc Phạm Mười. Tượng đúc bằng đồng, cao 3,3 mét, nặng hơn 1 tấn. Bệ tượng hình vuông, mỗi cạnh 2 mét, cao 1,4 mét, ốp đá granite. Cổng thông tin về Chủ tịch Hồ Chí Minh cũng ghi các thông số tương tự: tượng cao 330 xăng-ti-mét, nặng 1.000 ki-lô-gam, khánh thành năm 2003. Tượng đứng giữa sân Nhà Rồng, nhìn theo hướng bắc về phía sông Sài Gòn và Bến Bạch Đằng. Tính cả bệ, pho tượng cao khoảng 4,7 mét, đủ để nổi bật giữa khoảng sân rộng bên bờ sông. Người xem đứng dưới chân tượng phải ngước lên, rồi nhìn theo hướng nhìn của tượng ra phía dòng sông. Chính hướng nhìn ấy làm nên ý nghĩa của tác phẩm. Người thanh niên không nhìn về phía thành phố sau lưng, mà nhìn ra con đường thủy dẫn tới biển lớn và thế giới bên ngoài."},{"t":"Bạn có biết? Cùng dịp khánh thành tượng đồng ngoài sân năm 2003, bảo tàng đón nhận thêm pho tượng “Bác Hồ đọc báo Nhân Dân” bằng đồng đỏ, cao 95 xăng-ti-mét, nặng 120 ki-lô-gam. Pho tượng do Ban Quản lý Lăng Chủ tịch Hồ Chí Minh ở Hà Nội tặng, đặt trong phòng tưởng niệm."},{"t":"Người thanh niên trong tượng là ai?. Pho tượng khắc họa Nguyễn Tất Thành ở tuổi hai mươi mốt. Anh sinh ngày 19/5/1890 tại quê ngoại làng Hoàng Trù, gần làng Kim Liên, huyện Nam Đàn, tỉnh Nghệ An. Tên lúc nhỏ là Nguyễn Sinh Cung; cha là cụ Phó bảng Nguyễn Sinh Sắc, mẹ là bà Hoàng Thị Loan. Về sau, anh được đổi tên là Nguyễn Tất Thành. Anh học chữ Hán từ nhỏ, rồi học tiếng Pháp, từng là học trò trường Quốc học Huế. Năm 1908, anh tham gia phong trào chống thuế của nông dân ở Huế. Những năm 1909 – 1910, anh ở Bình Định, nơi thân phụ làm tri huyện Bình Khê. Sau đó anh vào Phan Thiết dạy học ở trường Dục Thanh, rồi đầu năm 1911 đến Sài Gòn. Như vậy, người phụ bếp trên tàu năm ấy là một thanh niên có học vấn, am hiểu cả Nho học lẫn Tây học. Anh đã đi qua gần suốt dải đất miền Trung trước khi tới thành phố cảng phương Nam, và tự nguyện chọn con đường lao động để đi ra thế giới."},{"t":"Từ Văn Ba đến Hồ Chí Minh. Những cái tên của Người đánh dấu từng chặng đường. Ở Sài Gòn năm 1911, khi xin làm phụ bếp trên tàu Amiral Latouche-Tréville, anh dùng tên Văn Ba. Ngày 15/9/1911, từ Marseille, anh viết đơn xin vào học Trường Thuộc địa và ký tên Nguyễn Tất Thành. Tháng 6/1919, bản “Yêu sách của nhân dân An Nam” gửi tới Hội nghị Versailles được ký tên Nguyễn Ái Quốc. Cái tên ấy về sau trở thành biểu tượng của phong trào giải phóng các dân tộc thuộc địa. Từ tháng 8/1942, Người dùng tên Hồ Chí Minh. Giữa những cái tên ấy là rất nhiều bí danh, bút danh khác, dùng trong những năm hoạt động bí mật ở nhiều nước. Tên tệp của tấm ảnh tư liệu ghép hai cái tên Nguyễn Ái Quốc và Nguyễn Tất Thành, như một cách nhắc rằng người thanh niên trên bến sông và nhà cách mạng nổi tiếng về sau là một. Pho tượng ở Bến Nhà Rồng mang cái tên gắn với cuộc ra đi: Nguyễn Tất Thành, người thanh niên chưa ai biết đến nhưng đã mang trong mình câu hỏi lớn về vận mệnh dân tộc."},{"t":"Người đi tìm hình của nước. Năm 1960, nhà thơ Chế Lan Viên viết bài thơ “Người đi tìm hình của nước”, một bài thơ quen thuộc với nhiều thế hệ bạn đọc về cuộc ra đi năm 1911. Nhà thơ tưởng tượng mình hóa thành con sóng dưới con tàu, lặng lẽ tiễn người thanh niên rời bến. Hình ảnh ấy gần với cảm xúc của người đứng trước pho tượng ở Bến Nhà Rồng hôm nay. Họ muốn được tiễn đưa, được dõi theo một cuộc lên đường đã diễn ra lặng lẽ, không có nghi lễ nào. Nhan đề bài thơ cũng là một cách hiểu sâu sắc về chuyến đi. Người thanh niên không đi để tìm một chỗ đứng cho riêng mình, mà đi tìm “hình của nước”, tức con đường và diện mạo cho một nước Việt Nam độc lập. Năm 1960 cũng là năm Chủ tịch Hồ Chí Minh bước sang tuổi bảy mươi. Nhìn lại từ mốc ấy, chuyến đi của người phụ bếp năm 1911 đã hiện ra với tầm vóc của một bước ngoặt lịch sử."},{"t":"Đất nước đẹp vô cùng. Nhưng Bác phải ra đi / Cho tôi làm sóng dưới con tàu đưa tiễn Bác — Chế Lan Viên"},{"t":"Những pho tượng của tuổi trẻ. Hình tượng Nguyễn Tất Thành thời trẻ còn xuất hiện ở những nơi khác gắn với dấu chân anh trước năm 1911. Ở thành phố Quy Nhơn, ngày 18/5/2017, tỉnh Bình Định khánh thành tượng đài Nguyễn Sinh Sắc – Nguyễn Tất Thành, đúc bằng đồng, cao 15,5 mét kể cả bệ. Theo báo Tuổi Trẻ, đây là tượng đài đầu tiên trong cả nước tôn vinh cả Bác Hồ và thân phụ của Người. Công trình gắn với thời gian Nguyễn Tất Thành ở Bình Định những năm 1909 – 1910. Phía sau tượng là bức phù điêu dài 76 mét, tái hiện Việt Nam đầu thế kỷ XX dưới ách thuộc địa và hành trình của Người trước khi ra đi tìm đường cứu nước. Đặt cạnh nhau, những pho tượng ấy kể một câu chuyện liền mạch. Đó là người con của một gia đình nhà Nho yêu nước, đi dọc miền Trung, rồi tới bến cảng Sài Gòn. Pho tượng ở Bến Nhà Rồng đứng ở điểm cuối của chặng đường trong nước ấy, cũng là điểm đầu của ba mươi năm bôn ba nơi đất khách."},{"t":"Hướng nhìn về phía bến sông. Từ sân Nhà Rồng, hướng bắc là cửa rạch Bến Nghé và bờ bên kia, nơi có mũi đất với cột cờ Thủ Ngữ và Bến Bạch Đằng (xem chuyên đề Bến cảng Sài Gòn đầu thế kỷ XX). Xa hơn là khu thương cảng ở đầu đường Charner xưa, nay là đường Nguyễn Huệ. Theo nhà nghiên cứu Nguyễn Đình Đầu, tàu hãng Chargeurs Réunis thời ấy cập cầu tàu lớn ở khu vực này. Vị trí chính xác nơi con tàu neo đậu năm 1911 vẫn còn được bàn luận. Dù con tàu rời đi từ cầu tàu nào, điều không thay đổi là dòng sông. Pho tượng nhìn ra chính dòng Sài Gòn mà ngày 5/6/1911 đã đưa người phụ bếp trẻ ra biển. Từ đó, anh đi qua Singapore, Colombo, Port Said, tới Marseille, rồi đi khắp các châu lục. Ba mươi năm sau, ngày 28/1/1941, Người trở về Tổ quốc qua cột mốc 108 ở Cao Bằng. Ngày 2/9/1945, tại Quảng trường Ba Đình, Người đọc bản Tuyên ngôn Độc lập khai sinh nước Việt Nam Dân chủ Cộng hòa."},{"t":"Bạn có biết? Ngày tàu rời Sài Gòn, 5/6/1911, Nguyễn Tất Thành vừa bước sang tuổi hai mươi mốt được hơn hai tuần."},{"t":"Đứng trước pho tượng hôm nay. Từ năm 2003, pho tượng trở thành điểm dừng chân đầu tiên của nhiều đoàn khách đến Bến Nhà Rồng. Với học sinh, sinh viên, pho tượng là một bài học lịch sử trực quan. Người thanh niên ra đi tìm đường cứu nước năm ấy cũng chỉ trạc tuổi các bạn trẻ đang đứng dưới chân tượng hôm nay. Với khách quốc tế, đây là dịp để biết rằng vị lãnh tụ của Việt Nam đã bắt đầu hành trình của mình như một người lao động bình thường trên một con tàu buôn. Năm 2026, khuôn viên bảo tàng, nơi đặt pho tượng, nằm trong đợt chỉnh trang với các hạng mục cải tạo nền sân, chiếu sáng, cây xanh, bồn hoa và hồ sen. Bảo tàng tạm dừng đón khách từ ngày 7/5/2026 (xem chuyên đề Bến Nhà Rồng ngày nay). Khi khuôn viên mới hoàn thành, pho tượng sẽ tiếp tục đón những người tìm về bến sông này. Câu hỏi mà pho tượng gửi tới người xem vẫn vậy: điều gì khiến một người hai mươi mốt tuổi dám rời xa quê hương để đi tìm con đường cho dân tộc mình?"}],"so_chu":1668},{"i":8,"tieu_de_bang":"Nhà Rồng","tieu_de":"Nhà Rồng: đôi rồng Việt trên nóc một tòa nhà Pháp và hơn một thế kỷ rưỡi đổi chủ","sapo":"Giữa năm 1862, khi Sài Gòn vừa bị cắt về tay người Pháp, một hãng tàu mang danh “Vận tải Hoàng đế” dựng trụ sở bên rạch Bến Nghé, rồi đắp lên nóc hai con rồng theo lối trang trí đình chùa Việt. Người dân không gọi tên hãng, họ gọi theo đôi rồng. Hơn một trăm sáu mươi năm, tòa nhà đổi chủ nhiều lần, đôi rồng cũng đổi dáng, chỉ cái tên Nhà Rồng là ở lại.","bia":{"src":"textures/ht/ht_anh_sa_gon_direction_de_la_cie_des_messageries_marit.jpg","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Hai con rồng trên một mái nhà Tây","text":"Người đi thuyền trên sông Sài Gòn những năm 1860 hẳn phải chú ý tới một công trình lạ mắt ở chỗ rạch Bến Nghé đổ ra sông. Tòa nhà mang dáng dấp kiến trúc phương Tây, nhưng trên nóc lại có hai con rồng chầu vào mặt nguyệt ở giữa. Đó là mô típ “lưỡng long chầu nguyệt”, vốn quen thuộc trên mái đình, mái chùa Việt Nam. Tòa nhà được xây từ giữa năm 1862 và hoàn thành năm 1863, làm trụ sở của Tổng công ty Vận tải Hoàng đế, tiếng Pháp là Messageries Impériales. Tư liệu của Bảo tàng Hồ Chí Minh ghi tên tòa nhà bằng tiếng Pháp là Hôtel des Messageries Impériales, nghĩa là tòa trụ sở của hãng.\n\nNgười Sài Gòn không gọi theo cái tên dài dòng ấy. Họ gọi theo hình ảnh dễ nhớ nhất, nổi bật nhất trên nền trời: Nhà Rồng. Bến sông trước tòa nhà cũng thành Bến Nhà Rồng. Hơn một trăm sáu mươi năm đã qua, hãng tàu đổi tên, chế độ thuộc địa sụp đổ, tòa nhà qua tay nhiều chủ. Chỉ có cái tên do người dân đặt là vẫn ở lại, bền bỉ hơn mọi tấm biển chính thức.","doc":1},{"loai":"doan","tieu_de":"Sài Gòn năm 1862: hãng tàu đến trước","text":"Tòa nhà ra đời trong những năm đầu tiên của chế độ thuộc địa. Quân Pháp đánh chiếm thành Gia Định năm 1859. Ngày 5/6/1862, triều đình Tự Đức phải ký hòa ước Nhâm Tuất, nhượng cho Pháp ba tỉnh miền Đông Nam Kỳ là Biên Hòa, Gia Định, Định Tường cùng đảo Côn Lôn. Cũng từ năm ấy, hãng Messageries Impériales sang hoạt động ở Sài Gòn. Theo Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh, trụ sở của hãng là một trong những công trình đầu tiên người Pháp xây dựng sau khi chiếm được Sài Gòn.\n\nHãng chọn một địa thế đắc dụng: mũi đất ở ngã ba, nơi rạch Bến Nghé gặp sông Sài Gòn. Tư liệu của Bảo tàng Thành phố Hồ Chí Minh cho biết mặt sông ở đây rộng, tàu dài ba trăm mét có thể quay đầu. Nước sâu khoảng tám mét khi mực nước trung bình, lên tới mười mét khi triều cường, đủ cho tàu ba nghìn tấn ra vào. Theo nhà nghiên cứu Nguyễn Đình Đầu, tàu viễn dương của hãng khi đến Sài Gòn đều cập bến Nhà Rồng, nơi dành riêng cho hãng.","doc":2},{"loai":"anh","src":"textures/ht/ht_anh_sa_gon_direction_de_la_cie_des_messageries_marit.jpg","chu_thich":"Trụ sở hãng Messageries Maritimes – Nhà Rồng – đầu thế kỷ XX.","credit":"Ảnh: Không rõ tác giả · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Một công trình Âu – Á","text":"Tòa Nhà Rồng có mặt bằng hình chữ nhật, cao hai tầng, nằm trong khuôn viên rộng khoảng 1,4 ha. Tường gạch dày giữ mát cho bên trong. Mái ngói dốc giúp nước mưa thoát nhanh trong những cơn mưa rào nhiệt đới. Dọc hai tầng là hệ thống cửa vòm và hành lang dài, kiểu hàng hiên giúp che nắng, thông gió, rất phổ biến ở các công trình người Pháp dựng tại xứ nóng. Bên trong, cầu thang được làm theo kiểu gấp khúc, lan can bằng sắt trang trí nhiều hoa văn.\n\nNếu chỉ nhìn phần thân nhà, người ta dễ tưởng đây là một dinh thự ở miền Nam nước Pháp. Chính phần mái mới làm nên sự khác biệt. Đường nóc uốn cong, đôi rồng đất nung tráng men xanh nổi lên trên nền trời, khiến tòa nhà mang một dáng vẻ vừa Âu vừa Á. Sự pha trộn ấy cũng là lý do tòa nhà trở thành một dấu mốc quen thuộc của bến cảng.","doc":3},{"loai":"trich","text":"Hãng Nhà Rồng (Messageries Impériales) là hãng chuyên chở kỳ cựu của Pháp, sang hoạt động ở Sài Gòn từ 1862, xây trụ sở đồ sộ bên rạch Bến Nghé với nóc nhà uốn cong và trang trí bằng hình lưỡng long tranh nguyệt.","nguoi":"Nhà nghiên cứu Nguyễn Đình Đầu","nguon_ten":"Nguyễn Đình Đầu, “Tạp ghi Việt Sử Địa” (NXB Trẻ); trích đăng trên báo Thanh Niên ngày 10/10/2024, bài “Nơi Bác ra đi tìm đường cứu nước”","doc":4},{"loai":"doan","tieu_de":"Vì sao lại là rồng?","text":"Trong kiến trúc truyền thống Việt Nam, “lưỡng long chầu nguyệt” là hình ảnh hai con rồng đối xứng ở hai đầu bờ nóc, cùng hướng vào một mặt nguyệt hay một viên ngọc ở giữa. Mô típ ấy thường thấy trên mái đình làng, chùa chiền, cung điện, gắn với ý niệm về sự tôn nghiêm, cát tường và mưa thuận gió hòa. Với người dân Gia Định thế kỷ XIX, đó là một hình ảnh thân thuộc, nhìn là nhận ra ngay.\n\nTư liệu hiện có không cho biết ai đã chọn chi tiết trang trí ấy cho trụ sở một hãng tàu Pháp, và chọn vì lý do gì. Điều chắc chắn là hiệu quả của nó vượt xa một chi tiết trang trí. Đôi rồng trên nóc đã đặt tên cho tòa nhà, rồi cho bến sông, và qua đó đi vào ngôn ngữ hằng ngày của người Sài Gòn. Với người Sài Gòn, chỉ cần nói hai chữ Nhà Rồng là ai cũng biết nơi nào. Cái tên dân gian ấy về sau còn được dùng để gọi chính hãng tàu, như trong cách viết của nhà nghiên cứu Nguyễn Đình Đầu ở trên.","doc":5},{"loai":"anh","src":"textures/bang_w/G04_8_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà Rồng”, nhìn từ xa."},{"loai":"doan","tieu_de":"Vương miện, mỏ neo và đầu ngựa","text":"Năm 1870, khi Đế chế thứ hai ở Pháp sụp đổ, hãng đổi tên thành Messageries Maritimes, tức Công ty Vận tải Hàng hải, nhưng nhiệm vụ và phạm vi hoạt động không thay đổi. Mặt nguyệt giữa đôi rồng bị thay bằng biểu tượng của hãng gồm vương miện, mỏ neo và đầu ngựa. Người Sài Gòn vì thế gọi đây là “hãng Đầu Ngựa”. Nhà nghiên cứu Nguyễn Đình Đầu còn cho biết hình đầu ngựa được vẽ cả trên ống khói các con tàu của hãng (xem chuyên đề ảnh tư liệu “Trụ sở hãng Messageries Maritimes – Nhà Rồng”).\n\nCùng với tòa nhà, khu bến riêng của hãng cũng lớn dần theo lượng tàu cập bến. Những cầu tàu gỗ ban đầu chạy dọc bờ sông về phía Tân Thuận. Cuối thế kỷ XIX, cầu gỗ được thay bằng cầu tàu có cốt sắt; đến năm 1930, khi những cầu này đã hư nặng, một cầu tàu bê tông cốt sắt dài hơn bốn trăm mét được xây thay thế. Tòa nhà hai tầng với đôi rồng trên nóc vẫn đứng ở đầu khu bến, như người gác cửa của cả một hệ thống cầu tàu, kho hàng mở rộng suốt nhiều thập kỷ.","doc":6},{"loai":"ban_co_biet","text":"Theo tư liệu của Bảo tàng Thành phố Hồ Chí Minh, hãng tàu đã dựng ba cầu tàu gỗ chạy dài khoảng 350 m từ Nhà Rồng về hướng Tân Thuận. Năm 1899, khi cầu gỗ không còn đáp ứng nổi lượng tàu, hãng thay bằng hai cầu tàu cốt sắt, mỗi cầu dài 41,25 m, rộng 8 m, nối với bờ bằng một cầu phao rộng 10 m.","nguon_ten":"Bảo tàng Thành phố Hồ Chí Minh – phòng trưng bày “Thương cảng – thương mại dịch vụ Sài Gòn – Thành phố Hồ Chí Minh”: https://hcmc-museum.edu.vn/luu-tru/4008","doc":7},{"loai":"doan","tieu_de":"Tháng 6/1911: tòa nhà bên kia cầu tàu","text":"Năm 1911, khi Nguyễn Tất Thành ở Sài Gòn, Nhà Rồng vẫn là trụ sở của hãng Messageries Maritimes. Con tàu Amiral Latouche-Tréville mà anh xin làm phụ bếp lại thuộc một hãng khác, hãng Chargeurs Réunis, người Việt quen gọi là hãng Năm Sao. Theo nhà nghiên cứu Nguyễn Đình Đầu, mỗi hãng cho tàu cập bến riêng, và tàu hãng Năm Sao khi ấy cập cầu tàu lớn của thương cảng ở đầu đường Charner, nay là đường Nguyễn Huệ. Ông viết rằng từ vị trí ấy nhìn sang phía sông, có thể thấy ngôi Nhà Rồng đồ sộ với dáng vẻ Âu Á pha trộn (xem chuyên đề “Bến cảng Sài Gòn”).\n\nNhư vậy, dù con tàu có neo đúng ở bến Nhà Rồng hay không, tòa nhà có đôi rồng vẫn là công trình nổi bật nhất trên bờ sông trong những ngày tháng Sáu ấy. Nhiều thập kỷ sau, chính tòa nhà này được chọn làm nơi ghi nhớ cuộc ra đi. Cái tên Bến Nhà Rồng từ đó gắn với ngày 5/6/1911 trong ký ức của cả dân tộc.","doc":8},{"loai":"ban_co_biet","text":"Hòa ước Nhâm Tuất, văn bản mở đầu việc cắt ba tỉnh miền Đông Nam Kỳ cho Pháp, được ký ngày 5/6/1862, cũng là năm tòa Nhà Rồng khởi công. Đúng bốn mươi chín năm sau, cũng vào ngày 5/6, người thanh niên Nguyễn Tất Thành rời Sài Gòn ra đi tìm đường giải phóng dân tộc.","nguon_ten":"Hòa ước Nhâm Tuất (Sài Gòn, 5/6/1862); Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":9},{"loai":"doan","tieu_de":"Những đời chủ sau năm 1955","text":"Nhà Rồng là trụ sở của hãng Messageries Maritimes suốt gần một thế kỷ. Năm 1955, sau thất bại của thực dân Pháp ở Việt Nam, thương cảng Sài Gòn, trong đó có Nhà Rồng, được chuyển giao cho chính quyền miền Nam Việt Nam quản lý. Chính quyền mới cho tu bổ lại phần mái và thay đôi rồng cũ bằng một đôi rồng khác, với tư thế quay đầu ra ngoài. Vì thế, đôi rồng người xem thấy trên nóc hôm nay không còn là đôi rồng chầu nguyệt của thế kỷ XIX.\n\nNăm 1965, quân đội Mỹ sử dụng tòa nhà làm trụ sở của Cơ quan Tiếp nhận viện trợ quân sự Mỹ. Tòa trụ sở hãng tàu thời thuộc địa trở thành một mắt xích của cuộc chiến tranh trên đất Việt Nam. Năm 1975, sau ngày đất nước thống nhất, Nhà Rồng, lúc ấy được coi là biểu tượng của cảng Sài Gòn, thuộc quyền quản lý của Cục Đường biển Việt Nam. Mỗi đời chủ để lại một dấu vết, nhưng không đời chủ nào xóa được cái tên người dân đã đặt.","doc":10},{"loai":"anh","src":"textures/bang_w/G04_8_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Nhà Rồng”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Từ quyết định năm 1979 đến bảo tàng","text":"Sau ngày đất nước thống nhất, Nhà Rồng được giữ lại làm di tích lưu niệm về Chủ tịch Hồ Chí Minh, theo Quyết định số 1315/QĐ-UB ngày 9/7/1979 của Ủy ban nhân dân Thành phố Hồ Chí Minh. Sau hơn mười năm hoạt động, ngày 30/10/1995, Ủy ban nhân dân Thành phố ra Quyết định số 7492/QĐ-UB-NCVX, chuyển Khu lưu niệm Chủ tịch Hồ Chí Minh thành Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh.\n\nTheo giới thiệu của bảo tàng, bên trong tòa nhà có bảy phòng trưng bày. Bốn phòng giới thiệu cuộc đời và sự nghiệp cách mạng của Chủ tịch Hồ Chí Minh. Ba phòng chuyên đề nói về sự kiện Bác Hồ ra đi tìm đường cứu nước, về tình cảm giữa Bác Hồ và nhân dân miền Nam, và về hệ thống đền thờ Bác Hồ ở Nam Bộ. Như vậy, tòa nhà vừa là nơi trưng bày hiện vật, vừa tự nó là một hiện vật lớn nhất của bảo tàng. Tường gạch, cửa vòm, cầu thang sắt và đôi rồng trên nóc đều là chứng tích của một thế kỷ rưỡi lịch sử bến cảng.","doc":11},{"loai":"anh","src":"textures/ht/ht_anh_ho_chi_minh_museum_saigon.jpg","chu_thich":"Bến Nhà Rồng ngày nay – Bảo tàng Hồ Chí Minh, chi nhánh Thành phố Hồ Chí Minh.","credit":"Ảnh: Gary Todd · CC0 · Wikimedia Commons"},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Năm 2026, tòa Nhà Rồng bước vào một đợt cải tạo lớn. Từ ngày 7/5/2026, bảo tàng tạm ngừng đón khách để thực hiện dự án cải tạo, chỉnh trang, hạng mục đầu tiên của khu công viên văn hóa Bến Nhà Rồng – Khánh Hội bên sông Sài Gòn. Theo Cổng thông tin Hội đồng nhân dân Thành phố, không gian bên trong bảo tàng lưu giữ khoảng 24.000 hiện vật, tư liệu và hình ảnh về cuộc đời Chủ tịch Hồ Chí Minh. Dự án đặt mục tiêu hoàn thành vào dịp Quốc khánh 2/9/2026. Tuy nhiên, theo báo Văn Hóa ngày 1/9/2026, công trình chưa kịp hoàn thành như dự kiến và thời điểm mở cửa trở lại còn chờ cấp có thẩm quyền quyết định.\n\nDù vậy, những gì làm nên giá trị của Nhà Rồng vẫn còn nguyên: vị trí ở ngã ba rạch Bến Nghé và sông Sài Gòn, thân nhà hai tầng với hàng cửa vòm, và đôi rồng trên nóc nhìn ra dòng sông. Trong không gian phục dựng của gian trưng bày này, tòa Nhà Rồng được dựng lại như cột mốc định hướng của cả bến cảng năm 1911.","doc":12}],"nguon":["Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh: Giới thiệu bảo tàng – https://bennharong.vn/gioi-thieu-bao-tang ; Giới thiệu khái quát – https://bennharong.hochiminh.vn/BenNhaRongdata/pano/info.html","Sở Văn hóa và Thể thao TP. Hồ Chí Minh – Bảo tàng Hồ Chí Minh, Chi nhánh TP. Hồ Chí Minh – https://svhtt.hochiminhcity.gov.vn/tin-chi-tiet/-/chi-tiet/bao-tang-ho-chi-minh-chi-nhanh-thanh-pho-ho-chi-minh-19084-2015.html","Bảo tàng Thành phố Hồ Chí Minh – Thương cảng, thương mại dịch vụ Sài Gòn – Thành phố Hồ Chí Minh – https://hcmc-museum.edu.vn/luu-tru/4008","Nguyễn Đình Đầu, “Nơi Bác ra đi tìm đường cứu nước”, báo Thanh Niên, 10/10/2024 – https://thanhnien.vn/noi-bac-ra-di-tim-duong-cuu-nuoc-185241009213949499.htm","VnExpress – “Kiến trúc Bến Nhà Rồng 163 năm tuổi trước khi cải tạo” (2026) – https://vnexpress.net/kien-truc-ben-nha-rong-163-nam-tuoi-truoc-khi-cai-tao-5069030.html","HĐND TP. Hồ Chí Minh – “Bảo tàng Hồ Chí Minh ở Bến Nhà Rồng tạm đóng cửa đến tháng 9” (9/5/2026) – https://hdnd.hochiminhcity.gov.vn/tin-tuc/ban-van-hoa-xa-hoi/bao-tang-ho-chi-minh-o-ben-nha-rong-tam-dong-cua-den-thang-9 ; Báo Văn Hóa (1/9/2026) – https://baovanhoa.vn/van-hoa/bao-tang-ho-chi-minh-chi-nhanh-tphcm-chua-mo-cua-phuc-vu-khach-dip-29-261444.html"],"doc":[{"t":"Nhà Rồng: đôi rồng Việt trên nóc một tòa nhà Pháp và hơn một thế kỷ rưỡi đổi chủ. Giữa năm 1862, khi Sài Gòn vừa bị cắt về tay người Pháp, một hãng tàu mang danh “Vận tải Hoàng đế” dựng trụ sở bên rạch Bến Nghé, rồi đắp lên nóc hai con rồng theo lối trang trí đình chùa Việt. Người dân không gọi tên hãng, họ gọi theo đôi rồng. Hơn một trăm sáu mươi năm, tòa nhà đổi chủ nhiều lần, đôi rồng cũng đổi dáng, chỉ cái tên Nhà Rồng là ở lại."},{"t":"Hai con rồng trên một mái nhà Tây. Người đi thuyền trên sông Sài Gòn những năm 1860 hẳn phải chú ý tới một công trình lạ mắt ở chỗ rạch Bến Nghé đổ ra sông. Tòa nhà mang dáng dấp kiến trúc phương Tây, nhưng trên nóc lại có hai con rồng chầu vào mặt nguyệt ở giữa. Đó là mô típ “lưỡng long chầu nguyệt”, vốn quen thuộc trên mái đình, mái chùa Việt Nam. Tòa nhà được xây từ giữa năm 1862 và hoàn thành năm 1863, làm trụ sở của Tổng công ty Vận tải Hoàng đế, tiếng Pháp là Messageries Impériales. Tư liệu của Bảo tàng Hồ Chí Minh ghi tên tòa nhà bằng tiếng Pháp là Hôtel des Messageries Impériales, nghĩa là tòa trụ sở của hãng. Người Sài Gòn không gọi theo cái tên dài dòng ấy. Họ gọi theo hình ảnh dễ nhớ nhất, nổi bật nhất trên nền trời: Nhà Rồng. Bến sông trước tòa nhà cũng thành Bến Nhà Rồng. Hơn một trăm sáu mươi năm đã qua, hãng tàu đổi tên, chế độ thuộc địa sụp đổ, tòa nhà qua tay nhiều chủ. Chỉ có cái tên do người dân đặt là vẫn ở lại, bền bỉ hơn mọi tấm biển chính thức."},{"t":"Sài Gòn năm 1862: hãng tàu đến trước. Tòa nhà ra đời trong những năm đầu tiên của chế độ thuộc địa. Quân Pháp đánh chiếm thành Gia Định năm 1859. Ngày 5/6/1862, triều đình Tự Đức phải ký hòa ước Nhâm Tuất, nhượng cho Pháp ba tỉnh miền Đông Nam Kỳ là Biên Hòa, Gia Định, Định Tường cùng đảo Côn Lôn. Cũng từ năm ấy, hãng Messageries Impériales sang hoạt động ở Sài Gòn. Theo Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh, trụ sở của hãng là một trong những công trình đầu tiên người Pháp xây dựng sau khi chiếm được Sài Gòn. Hãng chọn một địa thế đắc dụng: mũi đất ở ngã ba, nơi rạch Bến Nghé gặp sông Sài Gòn. Tư liệu của Bảo tàng Thành phố Hồ Chí Minh cho biết mặt sông ở đây rộng, tàu dài ba trăm mét có thể quay đầu. Nước sâu khoảng tám mét khi mực nước trung bình, lên tới mười mét khi triều cường, đủ cho tàu ba nghìn tấn ra vào. Theo nhà nghiên cứu Nguyễn Đình Đầu, tàu viễn dương của hãng khi đến Sài Gòn đều cập bến Nhà Rồng, nơi dành riêng cho hãng."},{"t":"Một công trình Âu – Á. Tòa Nhà Rồng có mặt bằng hình chữ nhật, cao hai tầng, nằm trong khuôn viên rộng khoảng 1,4 ha. Tường gạch dày giữ mát cho bên trong. Mái ngói dốc giúp nước mưa thoát nhanh trong những cơn mưa rào nhiệt đới. Dọc hai tầng là hệ thống cửa vòm và hành lang dài, kiểu hàng hiên giúp che nắng, thông gió, rất phổ biến ở các công trình người Pháp dựng tại xứ nóng. Bên trong, cầu thang được làm theo kiểu gấp khúc, lan can bằng sắt trang trí nhiều hoa văn. Nếu chỉ nhìn phần thân nhà, người ta dễ tưởng đây là một dinh thự ở miền Nam nước Pháp. Chính phần mái mới làm nên sự khác biệt. Đường nóc uốn cong, đôi rồng đất nung tráng men xanh nổi lên trên nền trời, khiến tòa nhà mang một dáng vẻ vừa Âu vừa Á. Sự pha trộn ấy cũng là lý do tòa nhà trở thành một dấu mốc quen thuộc của bến cảng."},{"t":"Hãng Nhà Rồng (Messageries Impériales) là hãng chuyên chở kỳ cựu của Pháp, sang hoạt động ở Sài Gòn từ 1862, xây trụ sở đồ sộ bên rạch Bến Nghé với nóc nhà uốn cong và trang trí bằng hình lưỡng long tranh nguyệt. — Nhà nghiên cứu Nguyễn Đình Đầu"},{"t":"Vì sao lại là rồng?. Trong kiến trúc truyền thống Việt Nam, “lưỡng long chầu nguyệt” là hình ảnh hai con rồng đối xứng ở hai đầu bờ nóc, cùng hướng vào một mặt nguyệt hay một viên ngọc ở giữa. Mô típ ấy thường thấy trên mái đình làng, chùa chiền, cung điện, gắn với ý niệm về sự tôn nghiêm, cát tường và mưa thuận gió hòa. Với người dân Gia Định thế kỷ XIX, đó là một hình ảnh thân thuộc, nhìn là nhận ra ngay. Tư liệu hiện có không cho biết ai đã chọn chi tiết trang trí ấy cho trụ sở một hãng tàu Pháp, và chọn vì lý do gì. Điều chắc chắn là hiệu quả của nó vượt xa một chi tiết trang trí. Đôi rồng trên nóc đã đặt tên cho tòa nhà, rồi cho bến sông, và qua đó đi vào ngôn ngữ hằng ngày của người Sài Gòn. Với người Sài Gòn, chỉ cần nói hai chữ Nhà Rồng là ai cũng biết nơi nào. Cái tên dân gian ấy về sau còn được dùng để gọi chính hãng tàu, như trong cách viết của nhà nghiên cứu Nguyễn Đình Đầu ở trên."},{"t":"Vương miện, mỏ neo và đầu ngựa. Năm 1870, khi Đế chế thứ hai ở Pháp sụp đổ, hãng đổi tên thành Messageries Maritimes, tức Công ty Vận tải Hàng hải, nhưng nhiệm vụ và phạm vi hoạt động không thay đổi. Mặt nguyệt giữa đôi rồng bị thay bằng biểu tượng của hãng gồm vương miện, mỏ neo và đầu ngựa. Người Sài Gòn vì thế gọi đây là “hãng Đầu Ngựa”. Nhà nghiên cứu Nguyễn Đình Đầu còn cho biết hình đầu ngựa được vẽ cả trên ống khói các con tàu của hãng (xem chuyên đề ảnh tư liệu “Trụ sở hãng Messageries Maritimes – Nhà Rồng”). Cùng với tòa nhà, khu bến riêng của hãng cũng lớn dần theo lượng tàu cập bến. Những cầu tàu gỗ ban đầu chạy dọc bờ sông về phía Tân Thuận. Cuối thế kỷ XIX, cầu gỗ được thay bằng cầu tàu có cốt sắt; đến năm 1930, khi những cầu này đã hư nặng, một cầu tàu bê tông cốt sắt dài hơn bốn trăm mét được xây thay thế. Tòa nhà hai tầng với đôi rồng trên nóc vẫn đứng ở đầu khu bến, như người gác cửa của cả một hệ thống cầu tàu, kho hàng mở rộng suốt nhiều thập kỷ."},{"t":"Bạn có biết? Theo tư liệu của Bảo tàng Thành phố Hồ Chí Minh, hãng tàu đã dựng ba cầu tàu gỗ chạy dài khoảng 350 m từ Nhà Rồng về hướng Tân Thuận. Năm 1899, khi cầu gỗ không còn đáp ứng nổi lượng tàu, hãng thay bằng hai cầu tàu cốt sắt, mỗi cầu dài 41,25 m, rộng 8 m, nối với bờ bằng một cầu phao rộng 10 m."},{"t":"Tháng 6/1911: tòa nhà bên kia cầu tàu. Năm 1911, khi Nguyễn Tất Thành ở Sài Gòn, Nhà Rồng vẫn là trụ sở của hãng Messageries Maritimes. Con tàu Amiral Latouche-Tréville mà anh xin làm phụ bếp lại thuộc một hãng khác, hãng Chargeurs Réunis, người Việt quen gọi là hãng Năm Sao. Theo nhà nghiên cứu Nguyễn Đình Đầu, mỗi hãng cho tàu cập bến riêng, và tàu hãng Năm Sao khi ấy cập cầu tàu lớn của thương cảng ở đầu đường Charner, nay là đường Nguyễn Huệ. Ông viết rằng từ vị trí ấy nhìn sang phía sông, có thể thấy ngôi Nhà Rồng đồ sộ với dáng vẻ Âu Á pha trộn (xem chuyên đề “Bến cảng Sài Gòn”). Như vậy, dù con tàu có neo đúng ở bến Nhà Rồng hay không, tòa nhà có đôi rồng vẫn là công trình nổi bật nhất trên bờ sông trong những ngày tháng Sáu ấy. Nhiều thập kỷ sau, chính tòa nhà này được chọn làm nơi ghi nhớ cuộc ra đi. Cái tên Bến Nhà Rồng từ đó gắn với ngày 5/6/1911 trong ký ức của cả dân tộc."},{"t":"Bạn có biết? Hòa ước Nhâm Tuất, văn bản mở đầu việc cắt ba tỉnh miền Đông Nam Kỳ cho Pháp, được ký ngày 5/6/1862, cũng là năm tòa Nhà Rồng khởi công. Đúng bốn mươi chín năm sau, cũng vào ngày 5/6, người thanh niên Nguyễn Tất Thành rời Sài Gòn ra đi tìm đường giải phóng dân tộc."},{"t":"Những đời chủ sau năm 1955. Nhà Rồng là trụ sở của hãng Messageries Maritimes suốt gần một thế kỷ. Năm 1955, sau thất bại của thực dân Pháp ở Việt Nam, thương cảng Sài Gòn, trong đó có Nhà Rồng, được chuyển giao cho chính quyền miền Nam Việt Nam quản lý. Chính quyền mới cho tu bổ lại phần mái và thay đôi rồng cũ bằng một đôi rồng khác, với tư thế quay đầu ra ngoài. Vì thế, đôi rồng người xem thấy trên nóc hôm nay không còn là đôi rồng chầu nguyệt của thế kỷ XIX. Năm 1965, quân đội Mỹ sử dụng tòa nhà làm trụ sở của Cơ quan Tiếp nhận viện trợ quân sự Mỹ. Tòa trụ sở hãng tàu thời thuộc địa trở thành một mắt xích của cuộc chiến tranh trên đất Việt Nam. Năm 1975, sau ngày đất nước thống nhất, Nhà Rồng, lúc ấy được coi là biểu tượng của cảng Sài Gòn, thuộc quyền quản lý của Cục Đường biển Việt Nam. Mỗi đời chủ để lại một dấu vết, nhưng không đời chủ nào xóa được cái tên người dân đã đặt."},{"t":"Từ quyết định năm 1979 đến bảo tàng. Sau ngày đất nước thống nhất, Nhà Rồng được giữ lại làm di tích lưu niệm về Chủ tịch Hồ Chí Minh, theo Quyết định số 1315/QĐ-UB ngày 9/7/1979 của Ủy ban nhân dân Thành phố Hồ Chí Minh. Sau hơn mười năm hoạt động, ngày 30/10/1995, Ủy ban nhân dân Thành phố ra Quyết định số 7492/QĐ-UB-NCVX, chuyển Khu lưu niệm Chủ tịch Hồ Chí Minh thành Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh. Theo giới thiệu của bảo tàng, bên trong tòa nhà có bảy phòng trưng bày. Bốn phòng giới thiệu cuộc đời và sự nghiệp cách mạng của Chủ tịch Hồ Chí Minh. Ba phòng chuyên đề nói về sự kiện Bác Hồ ra đi tìm đường cứu nước, về tình cảm giữa Bác Hồ và nhân dân miền Nam, và về hệ thống đền thờ Bác Hồ ở Nam Bộ. Như vậy, tòa nhà vừa là nơi trưng bày hiện vật, vừa tự nó là một hiện vật lớn nhất của bảo tàng. Tường gạch, cửa vòm, cầu thang sắt và đôi rồng trên nóc đều là chứng tích của một thế kỷ rưỡi lịch sử bến cảng."},{"t":"Dấu tích hôm nay. Năm 2026, tòa Nhà Rồng bước vào một đợt cải tạo lớn. Từ ngày 7/5/2026, bảo tàng tạm ngừng đón khách để thực hiện dự án cải tạo, chỉnh trang, hạng mục đầu tiên của khu công viên văn hóa Bến Nhà Rồng – Khánh Hội bên sông Sài Gòn. Theo Cổng thông tin Hội đồng nhân dân Thành phố, không gian bên trong bảo tàng lưu giữ khoảng 24.000 hiện vật, tư liệu và hình ảnh về cuộc đời Chủ tịch Hồ Chí Minh. Dự án đặt mục tiêu hoàn thành vào dịp Quốc khánh 2/9/2026. Tuy nhiên, theo báo Văn Hóa ngày 1/9/2026, công trình chưa kịp hoàn thành như dự kiến và thời điểm mở cửa trở lại còn chờ cấp có thẩm quyền quyết định. Dù vậy, những gì làm nên giá trị của Nhà Rồng vẫn còn nguyên: vị trí ở ngã ba rạch Bến Nghé và sông Sài Gòn, thân nhà hai tầng với hàng cửa vòm, và đôi rồng trên nóc nhìn ra dòng sông. Trong không gian phục dựng của gian trưng bày này, tòa Nhà Rồng được dựng lại như cột mốc định hướng của cả bến cảng năm 1911."}],"so_chu":2007},{"i":9,"tieu_de_bang":"Tàu Amiral Latouche-Tréville","tieu_de":"Amiral Latouche-Tréville: chân dung con tàu buôn của hãng Năm Sao","sapo":"Nó dài gần một trăm hai mươi mét, chạy bằng hơi nước và mang tên một vị đô đốc từng đẩy lui Nelson. Suốt hai mươi lăm năm, nó chỉ là một trong nhiều con tàu buôn nối nước Pháp với Đông Dương. Thế nhưng chuyến rời Sài Gòn trưa 5/6/1911, với một người phụ bếp mới nhận việc tên Văn Ba, đã đưa tên con tàu vào lịch sử Việt Nam.","bia":{"src":"textures/bai/G04_v0.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Tấm ảnh trước giờ nhổ neo","text":"Năm 2026, Tạp chí Nghiên cứu Hồ Chí Minh của Học viện Chính trị quốc gia Hồ Chí Minh giới thiệu một tấm ảnh cũ thuộc sưu tập của nhà sưu tầm Nguyễn Đại Hùng Lộc. Chú thích cho biết đó là tàu Amiral Latouche-Tréville chuẩn bị rời cảng Sài Gòn, kèm ảnh chụp mặt trước cầu tàu năm 1911. Theo bài viết, con tàu rời bến sông Sài Gòn vào trưa ngày 5/6/1911.\n\nCái tên trên mạn tàu là tiếng Pháp, nghĩa là “Đô đốc Latouche-Tréville”. Với hành khách châu Âu thời ấy, đó là một con tàu bình thường trên tuyến Pháp – Đông Dương, vừa chở hàng vừa chở khách. Với người Việt Nam hôm nay, đó là con tàu đã đưa người thanh niên Nguyễn Tất Thành rời Tổ quốc. Những ngày làm phụ bếp của anh được kể trong một chuyên đề khác (xem chuyên đề “Người phụ bếp Văn Ba”). Ở đây, ta đi tìm chân dung của chính con tàu: nó được đóng ở đâu, thuộc về ai, mang tên ai, đã chở những ai và kết thúc cuộc đời ra sao.","doc":1},{"loai":"anh","src":"textures/bang_w/G04_9_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tàu Amiral Latouche-Tréville”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Ra đời ở xưởng đóng tàu Loire","text":"Theo Tạp chí Nghiên cứu Hồ Chí Minh, con tàu do hãng đóng tàu Loire của Pháp khởi đóng ngày 21/9/1903 và hạ thủy tháng 2/1904 tại Nantes, thành phố cảng bên dòng sông Loire. Nhà nghiên cứu Nguyễn Đình Đầu cho biết thêm tàu được đăng ký tại cảng Le Havre năm 1904. Đó là cảng gắn bó với hãng chủ tàu từ những ngày đầu thành lập.\n\nAmiral Latouche-Tréville dài 118,7 m, rộng 15,2 m, trọng tải 5.572 tấn, tải trọng tối đa 7.200 tấn, vận hành bằng máy hơi nước. Sức chứa tối đa có thể lên tới khoảng 1.100 người, kể cả thủy thủ đoàn. Người Pháp xếp loại tàu này vào hạng “paquebot mixte”, tức tàu hỗn hợp: khoang dưới chở hàng hóa, các tầng trên dành cho hành khách với nhiều hạng vé khác nhau. Đầu thế kỷ XX, đó là cỡ tàu lớn trên các tuyến viễn dương. Ở bến Sài Gòn, thân tàu dài gần một trăm hai mươi mét hẳn nổi bật giữa những ghe thuyền nhỏ bé của dân bản xứ.","doc":2},{"loai":"doan","tieu_de":"Hãng Năm Sao","text":"Chủ tàu là Công ty Chargeurs Réunis, thành lập năm 1872. Tháng 10/1872, con tàu đầu tiên của hãng rời cảng Le Havre đi vùng sông La Plata ở Nam Mỹ. Hãng dần mở thêm tuyến sang Tây Phi, rồi từ năm 1901 chạy tuyến thường kỳ giữa Pháp và Đông Dương, nối các cảng Pháp với Sài Gòn và Hải Phòng. Theo một báo cáo năm 1986 của giám đốc nhà máy Ba Son được nhà nghiên cứu Nguyễn Đình Đầu dẫn lại, đội tàu của hãng trên tuyến này gồm bảy chiếc. Sáu tàu lớn chia nhau chạy giữa các cảng Pháp và Đông Dương, chiếc tàu mang tên Chợ Lớn nhỏ hơn chạy bổ sung quanh năm.\n\nNgười Việt gọi Chargeurs Réunis là hãng Năm Sao, vì biểu trưng của hãng có năm ngôi sao vẽ trên ống khói tàu. Lá cờ hiệu của hãng là nền trắng với năm ngôi sao đỏ. Cách gọi ấy giúp phân biệt với hãng Messageries Maritimes, chủ tòa Nhà Rồng, mà dân gian gọi là hãng Đầu Ngựa. Theo nhà nghiên cứu Nguyễn Đình Đầu, đó là hai hãng tàu biển lớn nhất ở Sài Gòn khi ấy, mỗi hãng cho tàu cập bến riêng, không thể lẫn lộn.","doc":3},{"loai":"anh","src":"textures/ht/ht_anh_saigon_la_pointe_des_blagueurs_le_paul_lecat_sur.jpg","chu_thich":"Bến cảng Sài Gòn đầu thế kỷ XX, tàu viễn dương neo trên sông. Con tàu trong ảnh là tàu Paul-Lecat của hãng Messageries Maritimes, không phải tàu Amiral Latouche-Tréville.","credit":"Ảnh: Francis Alexandre Decoly · Public domain · Wikimedia Commons"},{"loai":"ban_co_biet","text":"Trong sách “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”, Trần Dân Tiên gọi chủ tàu là hãng “Vận tải hợp nhất” – một cách dịch sát nghĩa tên tiếng Pháp Chargeurs Réunis, nghĩa là “những nhà vận tải hợp nhất lại”.","nguon_ten":"Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”","doc":4},{"loai":"doan","tieu_de":"Người mang tên con tàu","text":"Chargeurs Réunis đặt tên cho một loạt tàu của hãng theo tên các đô đốc Pháp, với chữ Amiral, nghĩa là đô đốc, đứng đầu. Latouche-Tréville là một trong số đó. Louis-René Levassor de Latouche-Tréville sinh năm 1745 tại Rochefort, trong một gia đình nhiều đời đi biển. Năm 1759, khi còn là một thiếu niên, ông đã dự trận hải chiến ở vịnh Quiberon.\n\nTrong Chiến tranh giành độc lập của Mỹ, năm 1780, ông chỉ huy chiến hạm Hermione đưa hầu tước La Fayette sang châu Mỹ. Thời Cách mạng Pháp, ông được phong chuẩn đô đốc năm 1793, rồi bị bắt giam trong thời kỳ khủng bố vì xuất thân quý tộc, đến năm 1795 mới được phục chức. Năm 1801, được Napoléon Bonaparte giao chỉ huy đội tàu ở Boulogne, ông đã đẩy lui các cuộc tấn công của đô đốc Anh Horatio Nelson vào tháng 8 năm ấy. Ông mất ngày 19/8/1804 trên soái hạm Bucentaure tại cảng Toulon. Người kế nhiệm ông về sau dẫn hạm đội Pháp vào trận Trafalgar thảm bại.","doc":5},{"loai":"ban_co_biet","text":"Đô đốc Latouche-Tréville sinh ngày 3/6/1745. Đúng một trăm sáu mươi sáu năm sau, cũng vào ngày 3/6, người thanh niên Nguyễn Tất Thành được nhận làm phụ bếp trên con tàu mang tên ông.","nguon_ten":"Napoleon & Empire – Latouche-Tréville: https://www.napoleon-empire.org/en/personalities/latouche_treville.php ; Tạp chí Nghiên cứu Hồ Chí Minh","doc":6},{"loai":"doan","tieu_de":"Thuyền trưởng Maisen và những người trên tàu","text":"Tài liệu “Port de Commerce de Saigon” của Tổng nha Công chánh, in tại Sài Gòn năm 1912, được nhà nghiên cứu Nguyễn Đình Đầu dẫn lại, ghi rằng tàu Amiral Latouche-Tréville từ Hải Phòng vào cập bến Sài Gòn ngày 2/6/1911. Tạp chí Công nghiệp Tàu thủy Việt Nam cho biết tàu cập cảng vào buổi trưa. Tàu do thuyền trưởng Maisen chỉ huy, cùng đoàn thủy thủ sáu mươi chín người. Tạp chí Nghiên cứu Hồ Chí Minh ghi tên đầy đủ của thuyền trưởng là Louis Édouard Maisen. Chuẩn bị cho hải trình đi Marseille, hãng tuyển thêm người làm việc trên tàu. Khi tàu rời Sài Gòn ngày 5/6, đoàn thủy thủ đã là bảy mươi hai người. Người phụ bếp mới tên Văn Ba là một trong những người được nhận thêm ở Sài Gòn.\n\nTrên các tầng khách là những hành khách đủ hạng. Sách của Trần Dân Tiên ghi lời kể của ông Mai, một người Việt từng làm ở phòng ăn sĩ quan trên tàu. Theo ông, trong số hành khách có kỹ sư canh nông Bùi Quang Chiêu đi tàu hạng nhất cùng gia đình, đưa con sang Pháp học. Ông Mai còn kể về hai người lính trẻ giải ngũ về Pháp, đã giúp anh Ba nhặt rau và cho anh mượn sách.","doc":7},{"loai":"trich","text":"Nhà bếp lo cho bảy, tám trăm người cả nhân viên và hành khách. Có nhiều cái chảo bằng đồng lớn và nặng quá, đến nỗi anh Ba phải kéo lê trên sàn.","nguoi":"Ông Mai, người từng làm việc trên tàu, kể lại trong sách của Trần Dân Tiên","nguon_ten":"Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”","doc":8},{"loai":"anh","src":"textures/bang_w/G04_9_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tàu Amiral Latouche-Tréville”, nhìn từ trên cao."},{"loai":"doan","tieu_de":"Hải trình mùa hè năm 1911","text":"Với người phụ bếp, chuyến đi mở ra một thế giới mới. Với con tàu, đó là một chuyến quen thuộc trên tuyến Đông Dương – Pháp. Theo hồ sơ về con tàu và các sổ cập cảng được tạp chí Công nghiệp Tàu thủy Việt Nam giới thiệu, sau ba ngày rời Sài Gòn, ngày 8/6/1911, tàu cập cảng Keppel của Singapore. Từ đây, tàu vào Ấn Độ Dương, ghé Colombo trên đảo Tích Lan, rồi Djibouti ở cửa ngõ Biển Đỏ, qua kênh đào Suez, ghé Port Said phía bắc Ai Cập. Ngày 6/7/1911, tàu cập cảng Marseille.\n\nTàu không dừng lại ở Marseille. Nó đi tiếp qua eo biển Gibraltar, vòng quanh bán đảo Iberia để lên phía bắc nước Pháp, tới Le Havre ngày 15/7. Sổ nhập cảng ghi tàu tới Dunkerque ngày 26/7/1911, kết thúc hải trình. Theo lời ông Mai trong sách của Trần Dân Tiên, tàu lên Le Havre là để sửa chữa. Sau đó, theo Tạp chí Nghiên cứu Hồ Chí Minh, con tàu quay về Sài Gòn vào tháng 10/1911, rồi lại trở sang Le Havre. Vòng quay ấy lặp lại suốt những năm tàu còn chạy tuyến Đông Dương.","doc":9},{"loai":"moc","items":[["21/9/1903","Hãng đóng tàu Loire khởi đóng con tàu"],["2/1904","Tàu hạ thủy tại Nantes, sau đó đăng ký tại cảng Le Havre"],["1904","Hãng Chargeurs Réunis đưa tàu vào khai thác"],["2/6/1911","Tàu từ Hải Phòng vào Sài Gòn, thuyền trưởng Maisen, sáu mươi chín thủy thủ"],["3/6/1911","Văn Ba được nhận làm phụ bếp, lương 45 franc mỗi tháng"],["5/6/1911","Trưa, tàu rời Sài Gòn với bảy mươi hai thủy thủ"],["8/6/1911","Cập cảng Keppel, Singapore"],["6/7/1911","Cập cảng Marseille sau khi ghé Colombo, Djibouti, Port Said"],["15/7/1911","Tới cảng Le Havre"],["26/7/1911","Tới Dunkerque, kết thúc hải trình"],["10/1911","Tàu quay lại Sài Gòn"],["11/3/1929","Tàu ngừng hoạt động, bị tháo dỡ tại Dunkerque"]],"doc":10},{"loai":"doan","tieu_de":"Hai mươi lăm năm trên biển","text":"Amiral Latouche-Tréville phục vụ hãng Chargeurs Réunis từ năm 1904 đến năm 1929. Tư liệu tham khảo của Pháp cho biết tàu được bố trí trên tuyến Đông Dương ít nhất đến năm 1923. Trong những năm ấy, con tàu đi qua cả cuộc Chiến tranh thế giới thứ nhất, khi tàu buôn trên các tuyến biển thường xuyên bị tàu ngầm Đức săn đuổi. Không phải tàu nào cùng loạt “Amiral” của hãng cũng may mắn như vậy. Tàu Amiral-Hamelin bị tàu ngầm đối phương đánh chìm ở Địa Trung Hải ngày 7/10/1915. Tàu Amiral-de-Kersaint, cùng được đưa vào khai thác năm 1904, bị tàu ngầm Đức đánh chìm năm 1917.\n\nNgày 11/3/1929, Amiral Latouche-Tréville dừng hoạt động và được tháo dỡ tại Dunkerque, sau hai mươi lăm năm đi biển. Con tàu không còn nữa. Điều còn lại là giấy tờ: tài liệu của thương cảng Sài Gòn, các sổ cập cảng, sổ nhập cảng, và bản chụp sổ lĩnh lương của tàu có ghi tên Văn Ba, hiện lưu tại Bảo tàng Hồ Chí Minh. Cùng với đó là trí nhớ của những người từng làm việc với người phụ bếp tên Ba, được Trần Dân Tiên ghi lại.","doc":11},{"loai":"ban_co_biet","text":"Theo tư liệu nhà nghiên cứu Nguyễn Đình Đầu dẫn lại, tàu hãng Năm Sao từ Đông Dương đi Pháp có hai nơi khởi hành là Hải Phòng và Sài Gòn. Chuyến tàu tháng 6/1911 xuất phát từ Hải Phòng; theo lời ông Mai, tàu ghé Sài Gòn để lấy hàng và đón khách.","nguon_ten":"Nguyễn Đình Đầu, “Nơi Bác ra đi tìm đường cứu nước”, báo Thanh Niên, 10/10/2024; Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”","doc":12},{"loai":"anh","src":"textures/bang_w/G04_9_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Tàu Amiral Latouche-Tréville”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Vì sao một con tàu buôn được nhớ tên","text":"Trong lịch sử hàng hải Pháp, Amiral Latouche-Tréville chỉ là một cái tên giữa hàng trăm con tàu buôn. Nó không lập kỷ lục tốc độ, không tham gia trận đánh lớn nào. Ngay cả tên của nó cũng là tên mượn từ một vị đô đốc. Thế nhưng ở Việt Nam, tên con tàu được nhắc lại mỗi dịp tháng Sáu, được ghi trong sách giáo khoa và trong các bảo tàng về Chủ tịch Hồ Chí Minh.\n\nLý do nằm ở người phụ bếp lương 45 franc mỗi tháng. Con tàu ấy là phương tiện duy nhất mà một thanh niên không tiền, không người đỡ đầu có thể dùng để sang phương Tây. Nó chở anh qua nhiều biển và đại dương, qua những bến cảng thuộc địa của nhiều đế quốc, tới tận chính quốc của những người đang cai trị đất nước anh. Con tàu dựng trong không gian 3D của gian trưng bày này là hình minh họa, gợi dáng một tàu hơi nước đầu thế kỷ XX, không phải bản sao chính xác của Amiral Latouche-Tréville. Điều nó muốn gợi lại là khoảnh khắc một con tàu bình thường chở theo một con người phi thường.","doc":13}],"nguon":["Tạp chí Nghiên cứu Hồ Chí Minh (Học viện Chính trị quốc gia Hồ Chí Minh) – “Về một số con tàu trong những hải trình của Chủ tịch Hồ Chí Minh”, 2026 – https://tapchihochiminh.hcma.vn/Content/ve-mot-so-con-tau-trong-nhung-hai-trinh-cua-chu-tich-ho-chi-minh-01318","Nguyễn Đình Đầu, “Nơi Bác ra đi tìm đường cứu nước”, báo Thanh Niên, 10/10/2024 – https://thanhnien.vn/noi-bac-ra-di-tim-duong-cuu-nuoc-185241009213949499.htm","Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”","Công nghiệp Tàu thủy Việt Nam – “Hành trình của con tàu Amiral Latouche-Tréville đưa Nguyễn Tất Thành ra đi tìm đường cứu nước” – https://congnghieptauthuyvietnam.vn/new/hanh-trinh-cua-con-tau-amiral-latouche-treville-dua-nguyen-tat-thanh-ra-di-tim-duong-cuu-nuoc.html","Entreprises coloniales françaises – hồ sơ “Compagnie des Chargeurs Réunis” (tập hợp tư liệu báo chí Pháp) – https://www.entreprises-coloniales.fr/empire/Chargeurs_reunis.pdf","Napoleon & Empire – Latouche-Tréville – https://www.napoleon-empire.org/en/personalities/latouche_treville.php"],"doc":[{"t":"Amiral Latouche-Tréville: chân dung con tàu buôn của hãng Năm Sao. Nó dài gần một trăm hai mươi mét, chạy bằng hơi nước và mang tên một vị đô đốc từng đẩy lui Nelson. Suốt hai mươi lăm năm, nó chỉ là một trong nhiều con tàu buôn nối nước Pháp với Đông Dương. Thế nhưng chuyến rời Sài Gòn trưa 5/6/1911, với một người phụ bếp mới nhận việc tên Văn Ba, đã đưa tên con tàu vào lịch sử Việt Nam."},{"t":"Tấm ảnh trước giờ nhổ neo. Năm 2026, Tạp chí Nghiên cứu Hồ Chí Minh của Học viện Chính trị quốc gia Hồ Chí Minh giới thiệu một tấm ảnh cũ thuộc sưu tập của nhà sưu tầm Nguyễn Đại Hùng Lộc. Chú thích cho biết đó là tàu Amiral Latouche-Tréville chuẩn bị rời cảng Sài Gòn, kèm ảnh chụp mặt trước cầu tàu năm 1911. Theo bài viết, con tàu rời bến sông Sài Gòn vào trưa ngày 5/6/1911. Cái tên trên mạn tàu là tiếng Pháp, nghĩa là “Đô đốc Latouche-Tréville”. Với hành khách châu Âu thời ấy, đó là một con tàu bình thường trên tuyến Pháp – Đông Dương, vừa chở hàng vừa chở khách. Với người Việt Nam hôm nay, đó là con tàu đã đưa người thanh niên Nguyễn Tất Thành rời Tổ quốc. Những ngày làm phụ bếp của anh được kể trong một chuyên đề khác (xem chuyên đề “Người phụ bếp Văn Ba”). Ở đây, ta đi tìm chân dung của chính con tàu: nó được đóng ở đâu, thuộc về ai, mang tên ai, đã chở những ai và kết thúc cuộc đời ra sao."},{"t":"Ra đời ở xưởng đóng tàu Loire. Theo Tạp chí Nghiên cứu Hồ Chí Minh, con tàu do hãng đóng tàu Loire của Pháp khởi đóng ngày 21/9/1903 và hạ thủy tháng 2/1904 tại Nantes, thành phố cảng bên dòng sông Loire. Nhà nghiên cứu Nguyễn Đình Đầu cho biết thêm tàu được đăng ký tại cảng Le Havre năm 1904. Đó là cảng gắn bó với hãng chủ tàu từ những ngày đầu thành lập. Amiral Latouche-Tréville dài 118,7 m, rộng 15,2 m, trọng tải 5.572 tấn, tải trọng tối đa 7.200 tấn, vận hành bằng máy hơi nước. Sức chứa tối đa có thể lên tới khoảng 1.100 người, kể cả thủy thủ đoàn. Người Pháp xếp loại tàu này vào hạng “paquebot mixte”, tức tàu hỗn hợp: khoang dưới chở hàng hóa, các tầng trên dành cho hành khách với nhiều hạng vé khác nhau. Đầu thế kỷ XX, đó là cỡ tàu lớn trên các tuyến viễn dương. Ở bến Sài Gòn, thân tàu dài gần một trăm hai mươi mét hẳn nổi bật giữa những ghe thuyền nhỏ bé của dân bản xứ."},{"t":"Hãng Năm Sao. Chủ tàu là Công ty Chargeurs Réunis, thành lập năm 1872. Tháng 10/1872, con tàu đầu tiên của hãng rời cảng Le Havre đi vùng sông La Plata ở Nam Mỹ. Hãng dần mở thêm tuyến sang Tây Phi, rồi từ năm 1901 chạy tuyến thường kỳ giữa Pháp và Đông Dương, nối các cảng Pháp với Sài Gòn và Hải Phòng. Theo một báo cáo năm 1986 của giám đốc nhà máy Ba Son được nhà nghiên cứu Nguyễn Đình Đầu dẫn lại, đội tàu của hãng trên tuyến này gồm bảy chiếc. Sáu tàu lớn chia nhau chạy giữa các cảng Pháp và Đông Dương, chiếc tàu mang tên Chợ Lớn nhỏ hơn chạy bổ sung quanh năm. Người Việt gọi Chargeurs Réunis là hãng Năm Sao, vì biểu trưng của hãng có năm ngôi sao vẽ trên ống khói tàu. Lá cờ hiệu của hãng là nền trắng với năm ngôi sao đỏ. Cách gọi ấy giúp phân biệt với hãng Messageries Maritimes, chủ tòa Nhà Rồng, mà dân gian gọi là hãng Đầu Ngựa. Theo nhà nghiên cứu Nguyễn Đình Đầu, đó là hai hãng tàu biển lớn nhất ở Sài Gòn khi ấy, mỗi hãng cho tàu cập bến riêng, không thể lẫn lộn."},{"t":"Bạn có biết? Trong sách “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”, Trần Dân Tiên gọi chủ tàu là hãng “Vận tải hợp nhất” – một cách dịch sát nghĩa tên tiếng Pháp Chargeurs Réunis, nghĩa là “những nhà vận tải hợp nhất lại”."},{"t":"Người mang tên con tàu. Chargeurs Réunis đặt tên cho một loạt tàu của hãng theo tên các đô đốc Pháp, với chữ Amiral, nghĩa là đô đốc, đứng đầu. Latouche-Tréville là một trong số đó. Louis-René Levassor de Latouche-Tréville sinh năm 1745 tại Rochefort, trong một gia đình nhiều đời đi biển. Năm 1759, khi còn là một thiếu niên, ông đã dự trận hải chiến ở vịnh Quiberon. Trong Chiến tranh giành độc lập của Mỹ, năm 1780, ông chỉ huy chiến hạm Hermione đưa hầu tước La Fayette sang châu Mỹ. Thời Cách mạng Pháp, ông được phong chuẩn đô đốc năm 1793, rồi bị bắt giam trong thời kỳ khủng bố vì xuất thân quý tộc, đến năm 1795 mới được phục chức. Năm 1801, được Napoléon Bonaparte giao chỉ huy đội tàu ở Boulogne, ông đã đẩy lui các cuộc tấn công của đô đốc Anh Horatio Nelson vào tháng 8 năm ấy. Ông mất ngày 19/8/1804 trên soái hạm Bucentaure tại cảng Toulon. Người kế nhiệm ông về sau dẫn hạm đội Pháp vào trận Trafalgar thảm bại."},{"t":"Bạn có biết? Đô đốc Latouche-Tréville sinh ngày 3/6/1745. Đúng một trăm sáu mươi sáu năm sau, cũng vào ngày 3/6, người thanh niên Nguyễn Tất Thành được nhận làm phụ bếp trên con tàu mang tên ông."},{"t":"Thuyền trưởng Maisen và những người trên tàu. Tài liệu “Port de Commerce de Saigon” của Tổng nha Công chánh, in tại Sài Gòn năm 1912, được nhà nghiên cứu Nguyễn Đình Đầu dẫn lại, ghi rằng tàu Amiral Latouche-Tréville từ Hải Phòng vào cập bến Sài Gòn ngày 2/6/1911. Tạp chí Công nghiệp Tàu thủy Việt Nam cho biết tàu cập cảng vào buổi trưa. Tàu do thuyền trưởng Maisen chỉ huy, cùng đoàn thủy thủ sáu mươi chín người. Tạp chí Nghiên cứu Hồ Chí Minh ghi tên đầy đủ của thuyền trưởng là Louis Édouard Maisen. Chuẩn bị cho hải trình đi Marseille, hãng tuyển thêm người làm việc trên tàu. Khi tàu rời Sài Gòn ngày 5/6, đoàn thủy thủ đã là bảy mươi hai người. Người phụ bếp mới tên Văn Ba là một trong những người được nhận thêm ở Sài Gòn. Trên các tầng khách là những hành khách đủ hạng. Sách của Trần Dân Tiên ghi lời kể của ông Mai, một người Việt từng làm ở phòng ăn sĩ quan trên tàu. Theo ông, trong số hành khách có kỹ sư canh nông Bùi Quang Chiêu đi tàu hạng nhất cùng gia đình, đưa con sang Pháp học. Ông Mai còn kể về hai người lính trẻ giải ngũ về Pháp, đã giúp anh Ba nhặt rau và cho anh mượn sách."},{"t":"Nhà bếp lo cho bảy, tám trăm người cả nhân viên và hành khách. Có nhiều cái chảo bằng đồng lớn và nặng quá, đến nỗi anh Ba phải kéo lê trên sàn. — Ông Mai, người từng làm việc trên tàu, kể lại trong sách của Trần Dân Tiên"},{"t":"Hải trình mùa hè năm 1911. Với người phụ bếp, chuyến đi mở ra một thế giới mới. Với con tàu, đó là một chuyến quen thuộc trên tuyến Đông Dương – Pháp. Theo hồ sơ về con tàu và các sổ cập cảng được tạp chí Công nghiệp Tàu thủy Việt Nam giới thiệu, sau ba ngày rời Sài Gòn, ngày 8/6/1911, tàu cập cảng Keppel của Singapore. Từ đây, tàu vào Ấn Độ Dương, ghé Colombo trên đảo Tích Lan, rồi Djibouti ở cửa ngõ Biển Đỏ, qua kênh đào Suez, ghé Port Said phía bắc Ai Cập. Ngày 6/7/1911, tàu cập cảng Marseille. Tàu không dừng lại ở Marseille. Nó đi tiếp qua eo biển Gibraltar, vòng quanh bán đảo Iberia để lên phía bắc nước Pháp, tới Le Havre ngày 15/7. Sổ nhập cảng ghi tàu tới Dunkerque ngày 26/7/1911, kết thúc hải trình. Theo lời ông Mai trong sách của Trần Dân Tiên, tàu lên Le Havre là để sửa chữa. Sau đó, theo Tạp chí Nghiên cứu Hồ Chí Minh, con tàu quay về Sài Gòn vào tháng 10/1911, rồi lại trở sang Le Havre. Vòng quay ấy lặp lại suốt những năm tàu còn chạy tuyến Đông Dương."},{"t":"Các mốc thời gian. 21/9/1903: Hãng đóng tàu Loire khởi đóng con tàu. 2/1904: Tàu hạ thủy tại Nantes, sau đó đăng ký tại cảng Le Havre. 1904: Hãng Chargeurs Réunis đưa tàu vào khai thác. 2/6/1911: Tàu từ Hải Phòng vào Sài Gòn, thuyền trưởng Maisen, sáu mươi chín thủy thủ. 3/6/1911: Văn Ba được nhận làm phụ bếp, lương 45 franc mỗi tháng. 5/6/1911: Trưa, tàu rời Sài Gòn với bảy mươi hai thủy thủ. 8/6/1911: Cập cảng Keppel, Singapore. 6/7/1911: Cập cảng Marseille sau khi ghé Colombo, Djibouti, Port Said. 15/7/1911: Tới cảng Le Havre. 26/7/1911: Tới Dunkerque, kết thúc hải trình. 10/1911: Tàu quay lại Sài Gòn. 11/3/1929: Tàu ngừng hoạt động, bị tháo dỡ tại Dunkerque."},{"t":"Hai mươi lăm năm trên biển. Amiral Latouche-Tréville phục vụ hãng Chargeurs Réunis từ năm 1904 đến năm 1929. Tư liệu tham khảo của Pháp cho biết tàu được bố trí trên tuyến Đông Dương ít nhất đến năm 1923. Trong những năm ấy, con tàu đi qua cả cuộc Chiến tranh thế giới thứ nhất, khi tàu buôn trên các tuyến biển thường xuyên bị tàu ngầm Đức săn đuổi. Không phải tàu nào cùng loạt “Amiral” của hãng cũng may mắn như vậy. Tàu Amiral-Hamelin bị tàu ngầm đối phương đánh chìm ở Địa Trung Hải ngày 7/10/1915. Tàu Amiral-de-Kersaint, cùng được đưa vào khai thác năm 1904, bị tàu ngầm Đức đánh chìm năm 1917. Ngày 11/3/1929, Amiral Latouche-Tréville dừng hoạt động và được tháo dỡ tại Dunkerque, sau hai mươi lăm năm đi biển. Con tàu không còn nữa. Điều còn lại là giấy tờ: tài liệu của thương cảng Sài Gòn, các sổ cập cảng, sổ nhập cảng, và bản chụp sổ lĩnh lương của tàu có ghi tên Văn Ba, hiện lưu tại Bảo tàng Hồ Chí Minh. Cùng với đó là trí nhớ của những người từng làm việc với người phụ bếp tên Ba, được Trần Dân Tiên ghi lại."},{"t":"Bạn có biết? Theo tư liệu nhà nghiên cứu Nguyễn Đình Đầu dẫn lại, tàu hãng Năm Sao từ Đông Dương đi Pháp có hai nơi khởi hành là Hải Phòng và Sài Gòn. Chuyến tàu tháng 6/1911 xuất phát từ Hải Phòng; theo lời ông Mai, tàu ghé Sài Gòn để lấy hàng và đón khách."},{"t":"Vì sao một con tàu buôn được nhớ tên. Trong lịch sử hàng hải Pháp, Amiral Latouche-Tréville chỉ là một cái tên giữa hàng trăm con tàu buôn. Nó không lập kỷ lục tốc độ, không tham gia trận đánh lớn nào. Ngay cả tên của nó cũng là tên mượn từ một vị đô đốc. Thế nhưng ở Việt Nam, tên con tàu được nhắc lại mỗi dịp tháng Sáu, được ghi trong sách giáo khoa và trong các bảo tàng về Chủ tịch Hồ Chí Minh. Lý do nằm ở người phụ bếp lương 45 franc mỗi tháng. Con tàu ấy là phương tiện duy nhất mà một thanh niên không tiền, không người đỡ đầu có thể dùng để sang phương Tây. Nó chở anh qua nhiều biển và đại dương, qua những bến cảng thuộc địa của nhiều đế quốc, tới tận chính quốc của những người đang cai trị đất nước anh. Con tàu dựng trong không gian 3D của gian trưng bày này là hình minh họa, gợi dáng một tàu hơi nước đầu thế kỷ XX, không phải bản sao chính xác của Amiral Latouche-Tréville. Điều nó muốn gợi lại là khoảnh khắc một con tàu bình thường chở theo một con người phi thường."}],"so_chu":1824},{"i":10,"tieu_de_bang":"Hai bàn tay","tieu_de":"Hai bàn tay: những nghề Người đã làm suốt mười hai năm đi tìm đường cứu nước","sapo":"Ở Sài Gòn năm 1911, khi bạn hỏi lấy đâu ra tiền để đi, người thanh niên chỉ giơ hai bàn tay. Lời hứa ấy được giữ trọn trong hơn một thập kỷ sau đó: dưới bếp tàu, giữa tuyết lạnh và lò than ở London, trong gian bếp khách sạn, bên bàn sửa ảnh ở Paris. Bảng hiện vật này đi theo đôi bàn tay ấy qua từng nghề, từng thành phố.","bia":{"src":"textures/bai/G04_v3.jpg","credit":"Phục dựng 3D · Bảo tàng Hành trình","p3d":true},"khoi":[{"loai":"doan","tieu_de":"Một hiện vật không nằm trong tủ kính","text":"Trong số những hiện vật của gian trưng bày này, có một hiện vật đặc biệt. Nó không có chất liệu, không có niên đại chế tác, cũng không nằm trong bất cứ tủ kính nào. Đó là hai bàn tay. Câu chuyện bắt đầu ở Sài Gòn năm 1911, khi Nguyễn Tất Thành rủ một người bạn cùng sang Pháp. Bạn hỏi lấy đâu ra tiền, anh giơ hai bàn tay lên, nói rằng họ sẽ làm bất cứ việc gì để sống và để đi (xem chuyên đề Lời rủ ra đi và người bạn tên Lê).\n\nNhiều người trẻ từng nói những lời hăng hái như thế. Điều làm nên giá trị của câu chuyện này là lời nói ấy được thực hiện đến cùng, theo đúng nghĩa đen. Trong khoảng mười hai năm, từ ngày rời bến cảng Sài Gòn đến khi rời Paris sang Liên Xô năm 1923, người thanh niên ấy sống chủ yếu bằng sức lao động của chính mình. Anh làm phụ bếp, làm thuê trên tàu biển, cào tuyết, đốt lò, rửa bát, làm bánh, sửa ảnh, vẽ thuê. Không học bổng, không người bảo trợ, không khoản quyên góp nào đứng sau những năm tháng ấy.","doc":1},{"loai":"anh","src":"textures/bang_w/G04_10_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hai bàn tay”, nhìn từ xa."},{"loai":"doan","tieu_de":"Từ bếp tàu đến những hải cảng xa","text":"Nghề đầu tiên là phụ bếp trên tàu Amiral Latouche-Tréville, với cái tên Văn Ba. Những ngày làm việc từ bốn giờ sáng dưới bếp tàu đã được kể riêng (xem chuyên đề Người phụ bếp Văn Ba). Điều đáng chú ý là chuyện xảy ra sau đó. Ngày 15/9/1911, từ Marseille, anh viết đơn xin vào học Trường Thuộc địa ở Paris. Lá đơn không được chấp nhận. Con đường học hành chính quy khép lại, và đôi bàn tay trở thành chỗ dựa duy nhất.\n\nTheo các tài liệu tiểu sử, những năm 1911 – 1913, người thanh niên tiếp tục làm thuê trên tàu biển, qua nhiều hải cảng ở châu Âu, châu Phi và châu Mỹ. Mỗi chuyến đi là một lần đổi sức lao động lấy chỗ ngủ trên tàu và bữa ăn hằng ngày. Nhưng cũng nhờ thế, anh tận mắt thấy đời sống của nhiều dân tộc thuộc địa khác. Sách của Trần Dân Tiên kể một cảnh ở Dakar, hải cảng lớn của Tây Phi thuộc Pháp. Hôm ấy sóng to, tàu không cập bến được, người Pháp bắt những người châu Phi bơi ra tàu, và có người đã chết đuối giữa sóng. Nỗi khổ của người dân thuộc địa, anh hiểu ra, không chỉ có ở quê hương mình.","doc":2},{"loai":"doan","tieu_de":"Ở nước Mỹ","text":"Trong những năm đi biển, Người đã đến nước Mỹ, sống một thời gian ở New York và Boston. Tư liệu gốc về giai đoạn này còn lại rất ít. Các tài liệu tiểu sử chỉ cho biết người thanh niên châu Á ấy tiếp tục làm những công việc lao động phổ thông để sống, giữa một đất nước đông đảo người nhập cư từ khắp thế giới.\n\nỞ Boston, khách sạn Parker House, mở cửa từ năm 1855, đến nay vẫn giới thiệu với du khách rằng Người từng làm việc trong gian bếp làm bánh của khách sạn. Nước Mỹ khi ấy vừa có những tòa nhà chọc trời, những bến cảng sầm uất, vừa có nạn phân biệt chủng tộc nặng nề với người da đen. Năm 1924, Người viết bài báo “Hành hình kiểu Linsơ”, tố cáo những vụ hành hình người da đen ở nước Mỹ.","doc":3},{"loai":"anh","src":"textures/bang_w/G04_10_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hai bàn tay”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"London: tuyết trắng và lò than","text":"Khoảng năm 1913, Người sang nước Anh. Theo cuốn “Hồ Chí Minh – Tiểu sử”, cuối năm 1913, sau hai tuần nghỉ việc vì bị cảm, anh đến làm thuê ở khách sạn Drayton Court, rồi làm phụ bếp ở khách sạn Carlton. Sách của Trần Dân Tiên kể thêm những việc nặng nhọc khác ở London: cào tuyết cho một trường học, làm thợ đốt lò.\n\nNhững công việc ấy trả công ít ỏi, nhưng cho anh một thứ quý: được sống giữa thủ đô của đế quốc lớn nhất thế giới khi đó. London là trung tâm của một hệ thống thuộc địa trải khắp các châu lục. Ngoài giờ làm, anh học tiếng Anh, đọc báo, tìm hiểu đời sống chính trị ở xứ sở này. Việc học ngoại ngữ nằm trong kế hoạch từ đầu: muốn biết các nước “làm như thế nào”, trước hết phải đọc và nghe được tiếng nói của họ.","doc":4},{"loai":"doan","tieu_de":"Gian bếp của “vua đầu bếp”","text":"Khách sạn Carlton nằm trên phố Haymarket, là một trong những khách sạn sang trọng bậc nhất London. Gian bếp của khách sạn khi ấy do Auguste Escoffier điều khiển. Ông là đầu bếp người Pháp lừng danh, được giới ẩm thực châu Âu tôn là “vua của các đầu bếp”. Người thanh niên Việt Nam vào đây làm phụ bếp, công việc chủ yếu là rửa bát đĩa, dọn dẹp.\n\nSách của Trần Dân Tiên kể lại một chuyện nhỏ. Ông Escoffier để ý thấy người phụ bếp trẻ không đổ thức ăn thừa vào thùng rác như những người khác, mà cẩn thận để riêng những phần còn lành. Được hỏi vì sao, anh đáp rằng không nên vứt những thứ ấy đi, có thể đem cho người nghèo. Ông Escoffier hài lòng, chuyển anh sang bộ phận làm bánh với đồng lương cao hơn. Theo sách, ông còn khuyên anh gác chuyện cách mạng sang một bên để học cho thành nghề bếp, vì nghề ấy sẽ đem lại nhiều tiền. Người thanh niên vẫn giữ con đường mình đã chọn. Đôi bàn tay có thể học làm bánh, nhưng không đem đổi mục đích của chuyến đi.","doc":5},{"loai":"ban_co_biet","text":"Trên tường tòa New Zealand House ở phố Haymarket, London, nơi trước kia là khách sạn Carlton (1899 – 1940), có gắn một tấm biển tưởng niệm ghi nhớ rằng Hồ Chí Minh từng làm việc tại khách sạn này.","nguon_ten":"The Historical Marker Database – “Ho Chi Minh Historical Marker”; Open Plaques – “Ho Chi Minh plaque”","doc":6},{"loai":"doan","tieu_de":"Paris: người thợ sửa ảnh","text":"Cuối năm 1917, Người trở lại Pháp. Từ tháng 7/1919, Người ở số 6 Villa des Gobelins, quận 13, Paris, ngôi nhà của luật sư Phan Văn Trường. Từ tháng 7/1921, Người chuyển về một căn phòng nhỏ ở số 9 ngõ Compoint, quận 17. Theo cuốn “Hồ Chí Minh – Tiểu sử”, những năm này Người kiếm sống khi thì làm thuê cho một hiệu ảnh, khi thì vẽ thuê cho một xưởng đồ cổ mỹ nghệ Trung Hoa. Trần Dân Tiên nói rõ hơn: đó là những đồ mỹ nghệ “kiểu Trung Hoa” do chính một xưởng của người Pháp làm ra.\n\nNghề sửa ảnh thời ấy đòi hỏi đôi tay khéo và con mắt tinh. Ảnh chân dung phải được sửa bằng tay trên phim hoặc trên bản in: tẩy vết, tô lại đường nét, làm rõ khuôn mặt. Nhiều tài liệu kể rằng báo Đời sống thợ thuyền (La Vie Ouvrière) từng đăng một mẩu quảng cáo nhỏ, mời những ai muốn giữ kỷ niệm về gia đình hãy mang ảnh đến nhờ Nguyễn Ái Quốc sửa. Cái tên vừa làm dư luận Pháp chú ý với bản Yêu sách năm 1919 lại xuất hiện trên mặt báo trong vai một người thợ kiếm sống.","doc":7},{"loai":"anh","src":"textures/ht/ht_anh_tuong_nguyen_ai_quoc_nguyen_tat_thanh_nha_tuong_.jpg","chu_thich":"Tượng Nguyễn Tất Thành tại khu tưởng niệm Bến Nhà Rồng, khắc họa người thanh niên sắp lên đường năm 1911, khi hành trang chỉ có sức lao động và khát vọng tìm đường cứu nước.","credit":"Ảnh: vi:User:TDA · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Đồng lương nhỏ, những trang viết lớn","text":"Đồng tiền từ nghề sửa ảnh, vẽ thuê chỉ đủ cho một cuộc sống thanh đạm. Nhưng sống bằng hai bàn tay cho Người một điều không ai ban phát được: sự tự chủ. Không phụ thuộc vào ai về tiền bạc, Người có thể dành thời gian đến thư viện đọc sách, học tiếng Pháp, dự các buổi mít tinh và viết báo.\n\nNhững năm ở Paris, bài của Nguyễn Ái Quốc xuất hiện trên nhiều tờ báo tiến bộ của Pháp. Ngày 1/4/1922, số đầu tiên của báo Le Paria (Người cùng khổ), cơ quan của Hội Liên hiệp thuộc địa, ra đời. Nguyễn Ái Quốc vừa là chủ nhiệm kiêm chủ bút, vừa viết bài, tự tay vẽ tranh biếm họa và đi bán báo. Đôi bàn tay từng rửa bát, sửa ảnh giờ cầm bút và cọ vẽ để tố cáo chế độ thuộc địa. Tác phẩm “Bản án chế độ thực dân Pháp”, xuất bản ở Paris năm 1925, là kết tinh của những năm cầm bút ấy.","doc":8},{"loai":"ban_co_biet","text":"Theo Trần Dân Tiên, những năm ở trọ tại Paris, mỗi buổi sáng trước khi đi làm, Người để một viên gạch vào lò bếp của khách sạn. Chiều về, Người lấy viên gạch ra, bọc vào mấy tờ báo cũ rồi đặt xuống nệm cho đỡ rét.","nguon_ten":"Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”","doc":9},{"loai":"doan","tieu_de":"Nhìn thế giới từ gian bếp và xưởng thợ","text":"Nhiều người Việt Nam đầu thế kỷ XX sang Pháp để vào trường lớn, làm công chức hay buôn bán. Người thanh niên ra đi năm 1911 nhìn phương Tây từ một chỗ đứng khác: từ bếp tàu, hầm lò, gian bếp khách sạn và bàn thợ sửa ảnh. Chỗ đứng ấy cho anh thấy điều mà hành khách hạng nhất khó nhận ra. Theo cuốn “Hồ Chí Minh – Tiểu sử”, ngay những ngày đầu trên đất Pháp, anh đã thấy ở Pháp cũng có những người nghèo như ở Việt Nam.\n\nTừ những điều mắt thấy tai nghe ấy, nhận thức của Người dần vượt ra khỏi khuôn khổ một dân tộc. Kẻ thù không phải là người Pháp hay người Anh nói chung, mà là chủ nghĩa thực dân và sự áp bức. Bạn bè không chỉ là đồng bào mình, mà còn là những người lao động và những dân tộc bị áp bức ở khắp nơi. Chính nhận thức ấy chuẩn bị cho bước ngoặt tháng 7/1920, khi Người đọc bản Luận cương của Lênin về vấn đề dân tộc và thuộc địa, và tìm thấy con đường giải phóng cho dân tộc mình.","doc":10},{"loai":"trich","text":"Dù màu da có khác nhau, trên đời này chỉ có hai giống người: giống người bóc lột và giống người bị bóc lột. Mà cũng chỉ có một mối tình hữu ái là thật mà thôi: tình hữu ái vô sản.","nguoi":"Nguyễn Ái Quốc (theo Trần Dân Tiên)","nguon_ten":"Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”","doc":11},{"loai":"doan","tieu_de":"Từ hai bàn tay đến sức mạnh của cả dân tộc","text":"Hình ảnh hai bàn tay gắn liền với tư tưởng tự lực, tự cường mà Người theo đuổi suốt đời. Năm 1911, đó là lựa chọn của một cá nhân: không trông vào ai, tự nuôi mình bằng lao động để đi tìm đường. Ba mươi tư năm sau, tư tưởng ấy trở thành lời hiệu triệu của cả một dân tộc. Tháng 8/1945, trong Thư kêu gọi Tổng khởi nghĩa, Người kêu gọi toàn dân đứng dậy, dựa vào sức mình mà giành lấy độc lập. Khi ấy, Người mới trở về Tổ quốc được hơn bốn năm, sau ba mươi năm sống và hoạt động ở nước ngoài.\n\nTừ đôi bàn tay trắng của người phụ bếp năm 1911 đến lời hiệu triệu năm 1945 là một chặng đường dài. Xuyên suốt chặng đường ấy vẫn là một niềm tin: sức lao động và ý chí của con người có thể làm nên những điều tưởng như không thể.","doc":12},{"loai":"trich","text":"Giờ quyết định cho vận mệnh dân tộc ta đã đến. Toàn quốc đồng bào hãy đứng dậy đem sức ta mà tự giải phóng cho ta.","nguoi":"Hồ Chí Minh, Thư kêu gọi Tổng khởi nghĩa, tháng 8/1945","nguon_ten":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","doc":13},{"loai":"anh","src":"textures/bang_w/G04_10_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Hai bàn tay”, nhìn từ trên cao."},{"loai":"moc","items":[["3/6/1911","Nhận làm phụ bếp trên tàu Amiral Latouche-Tréville với tên Văn Ba"],["15/9/1911","Từ Marseille viết đơn xin học Trường Thuộc địa, không được chấp nhận"],["1911 – 1913","Làm thuê trên tàu biển, qua nhiều hải cảng châu Âu, châu Phi, châu Mỹ"],["Cuối năm 1913","Ở Anh, làm thuê ở khách sạn Drayton Court"],["Những năm ở London","Cào tuyết, đốt lò; phụ bếp rồi làm bánh ở khách sạn Carlton"],["Cuối năm 1917","Trở lại Pháp"],["7/1919","Ở số 6 Villa des Gobelins, Paris; sống bằng nghề sửa ảnh, vẽ thuê"],["7/1921","Chuyển về số 9 ngõ Compoint, quận 17"],["1/4/1922","Số đầu báo Le Paria ra đời"],["6/1923","Rời Paris sang Liên Xô"]],"doc":14},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Hai bàn tay không để lại hiện vật gốc, nhưng dấu vết của chúng còn ở nhiều nơi. Ở London, tấm biển trên tường tòa New Zealand House nhắc rằng người phụ bếp năm xưa từng làm việc ở khách sạn Carlton. Ở Boston, khách sạn Parker House vẫn kể câu chuyện về người thợ làm bánh Việt Nam. Còn tên Văn Ba trong sổ lĩnh lương của con tàu năm 1911 được giữ lại qua bản chụp lưu tại Bảo tàng Hồ Chí Minh (xem chuyên đề Tàu Amiral Latouche-Tréville).\n\nTrong gian trưng bày này, bảng “Hai bàn tay” đặt giữa không gian một bến cảng lao động, nơi người thanh niên từng lui tới tìm việc trên tàu. Đứng trước bảng, người xem có thể tự hỏi: mình sẽ mang theo gì khi bước vào một hành trình lớn? Người thanh niên năm 1911 chỉ mang theo hai thứ: đôi bàn tay và một câu hỏi về vận mệnh dân tộc.","doc":15}],"nguon":["Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”","Hồ Chí Minh – Tiểu sử (Bảo tàng Hồ Chí Minh, NXB Chính trị quốc gia), phần “Tìm đường cứu nước (1911 – 1920)” – https://thmyhue.hcm.edu.vn/cuoc-doi-va-su-nghiep/ho-chi-minh-tieu-su-tim-duong-cuu-nuoc-1911-1920/ctmb/129642/1162568","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia (Thư kêu gọi Tổng khởi nghĩa, tháng 8/1945)","Cổng thông tin điện tử về Chủ tịch Hồ Chí Minh – “Uncle Ho – A baker in America”; báo Nhân Dân – “Omni Parker Hotel and accounts of Uncle Ho”","The Historical Marker Database – “Ho Chi Minh Historical Marker” (New Zealand House, London)"],"doc":[{"t":"Hai bàn tay: những nghề Người đã làm suốt mười hai năm đi tìm đường cứu nước. Ở Sài Gòn năm 1911, khi bạn hỏi lấy đâu ra tiền để đi, người thanh niên chỉ giơ hai bàn tay. Lời hứa ấy được giữ trọn trong hơn một thập kỷ sau đó: dưới bếp tàu, giữa tuyết lạnh và lò than ở London, trong gian bếp khách sạn, bên bàn sửa ảnh ở Paris. Bảng hiện vật này đi theo đôi bàn tay ấy qua từng nghề, từng thành phố."},{"t":"Một hiện vật không nằm trong tủ kính. Trong số những hiện vật của gian trưng bày này, có một hiện vật đặc biệt. Nó không có chất liệu, không có niên đại chế tác, cũng không nằm trong bất cứ tủ kính nào. Đó là hai bàn tay. Câu chuyện bắt đầu ở Sài Gòn năm 1911, khi Nguyễn Tất Thành rủ một người bạn cùng sang Pháp. Bạn hỏi lấy đâu ra tiền, anh giơ hai bàn tay lên, nói rằng họ sẽ làm bất cứ việc gì để sống và để đi (xem chuyên đề Lời rủ ra đi và người bạn tên Lê). Nhiều người trẻ từng nói những lời hăng hái như thế. Điều làm nên giá trị của câu chuyện này là lời nói ấy được thực hiện đến cùng, theo đúng nghĩa đen. Trong khoảng mười hai năm, từ ngày rời bến cảng Sài Gòn đến khi rời Paris sang Liên Xô năm 1923, người thanh niên ấy sống chủ yếu bằng sức lao động của chính mình. Anh làm phụ bếp, làm thuê trên tàu biển, cào tuyết, đốt lò, rửa bát, làm bánh, sửa ảnh, vẽ thuê. Không học bổng, không người bảo trợ, không khoản quyên góp nào đứng sau những năm tháng ấy."},{"t":"Từ bếp tàu đến những hải cảng xa. Nghề đầu tiên là phụ bếp trên tàu Amiral Latouche-Tréville, với cái tên Văn Ba. Những ngày làm việc từ bốn giờ sáng dưới bếp tàu đã được kể riêng (xem chuyên đề Người phụ bếp Văn Ba). Điều đáng chú ý là chuyện xảy ra sau đó. Ngày 15/9/1911, từ Marseille, anh viết đơn xin vào học Trường Thuộc địa ở Paris. Lá đơn không được chấp nhận. Con đường học hành chính quy khép lại, và đôi bàn tay trở thành chỗ dựa duy nhất. Theo các tài liệu tiểu sử, những năm 1911 – 1913, người thanh niên tiếp tục làm thuê trên tàu biển, qua nhiều hải cảng ở châu Âu, châu Phi và châu Mỹ. Mỗi chuyến đi là một lần đổi sức lao động lấy chỗ ngủ trên tàu và bữa ăn hằng ngày. Nhưng cũng nhờ thế, anh tận mắt thấy đời sống của nhiều dân tộc thuộc địa khác. Sách của Trần Dân Tiên kể một cảnh ở Dakar, hải cảng lớn của Tây Phi thuộc Pháp. Hôm ấy sóng to, tàu không cập bến được, người Pháp bắt những người châu Phi bơi ra tàu, và có người đã chết đuối giữa sóng. Nỗi khổ của người dân thuộc địa, anh hiểu ra, không chỉ có ở quê hương mình."},{"t":"Ở nước Mỹ. Trong những năm đi biển, Người đã đến nước Mỹ, sống một thời gian ở New York và Boston. Tư liệu gốc về giai đoạn này còn lại rất ít. Các tài liệu tiểu sử chỉ cho biết người thanh niên châu Á ấy tiếp tục làm những công việc lao động phổ thông để sống, giữa một đất nước đông đảo người nhập cư từ khắp thế giới. Ở Boston, khách sạn Parker House, mở cửa từ năm 1855, đến nay vẫn giới thiệu với du khách rằng Người từng làm việc trong gian bếp làm bánh của khách sạn. Nước Mỹ khi ấy vừa có những tòa nhà chọc trời, những bến cảng sầm uất, vừa có nạn phân biệt chủng tộc nặng nề với người da đen. Năm 1924, Người viết bài báo “Hành hình kiểu Linsơ”, tố cáo những vụ hành hình người da đen ở nước Mỹ."},{"t":"London: tuyết trắng và lò than. Khoảng năm 1913, Người sang nước Anh. Theo cuốn “Hồ Chí Minh – Tiểu sử”, cuối năm 1913, sau hai tuần nghỉ việc vì bị cảm, anh đến làm thuê ở khách sạn Drayton Court, rồi làm phụ bếp ở khách sạn Carlton. Sách của Trần Dân Tiên kể thêm những việc nặng nhọc khác ở London: cào tuyết cho một trường học, làm thợ đốt lò. Những công việc ấy trả công ít ỏi, nhưng cho anh một thứ quý: được sống giữa thủ đô của đế quốc lớn nhất thế giới khi đó. London là trung tâm của một hệ thống thuộc địa trải khắp các châu lục. Ngoài giờ làm, anh học tiếng Anh, đọc báo, tìm hiểu đời sống chính trị ở xứ sở này. Việc học ngoại ngữ nằm trong kế hoạch từ đầu: muốn biết các nước “làm như thế nào”, trước hết phải đọc và nghe được tiếng nói của họ."},{"t":"Gian bếp của “vua đầu bếp”. Khách sạn Carlton nằm trên phố Haymarket, là một trong những khách sạn sang trọng bậc nhất London. Gian bếp của khách sạn khi ấy do Auguste Escoffier điều khiển. Ông là đầu bếp người Pháp lừng danh, được giới ẩm thực châu Âu tôn là “vua của các đầu bếp”. Người thanh niên Việt Nam vào đây làm phụ bếp, công việc chủ yếu là rửa bát đĩa, dọn dẹp. Sách của Trần Dân Tiên kể lại một chuyện nhỏ. Ông Escoffier để ý thấy người phụ bếp trẻ không đổ thức ăn thừa vào thùng rác như những người khác, mà cẩn thận để riêng những phần còn lành. Được hỏi vì sao, anh đáp rằng không nên vứt những thứ ấy đi, có thể đem cho người nghèo. Ông Escoffier hài lòng, chuyển anh sang bộ phận làm bánh với đồng lương cao hơn. Theo sách, ông còn khuyên anh gác chuyện cách mạng sang một bên để học cho thành nghề bếp, vì nghề ấy sẽ đem lại nhiều tiền. Người thanh niên vẫn giữ con đường mình đã chọn. Đôi bàn tay có thể học làm bánh, nhưng không đem đổi mục đích của chuyến đi."},{"t":"Bạn có biết? Trên tường tòa New Zealand House ở phố Haymarket, London, nơi trước kia là khách sạn Carlton (1899 – 1940), có gắn một tấm biển tưởng niệm ghi nhớ rằng Hồ Chí Minh từng làm việc tại khách sạn này."},{"t":"Paris: người thợ sửa ảnh. Cuối năm 1917, Người trở lại Pháp. Từ tháng 7/1919, Người ở số 6 Villa des Gobelins, quận 13, Paris, ngôi nhà của luật sư Phan Văn Trường. Từ tháng 7/1921, Người chuyển về một căn phòng nhỏ ở số 9 ngõ Compoint, quận 17. Theo cuốn “Hồ Chí Minh – Tiểu sử”, những năm này Người kiếm sống khi thì làm thuê cho một hiệu ảnh, khi thì vẽ thuê cho một xưởng đồ cổ mỹ nghệ Trung Hoa. Trần Dân Tiên nói rõ hơn: đó là những đồ mỹ nghệ “kiểu Trung Hoa” do chính một xưởng của người Pháp làm ra. Nghề sửa ảnh thời ấy đòi hỏi đôi tay khéo và con mắt tinh. Ảnh chân dung phải được sửa bằng tay trên phim hoặc trên bản in: tẩy vết, tô lại đường nét, làm rõ khuôn mặt. Nhiều tài liệu kể rằng báo Đời sống thợ thuyền (La Vie Ouvrière) từng đăng một mẩu quảng cáo nhỏ, mời những ai muốn giữ kỷ niệm về gia đình hãy mang ảnh đến nhờ Nguyễn Ái Quốc sửa. Cái tên vừa làm dư luận Pháp chú ý với bản Yêu sách năm 1919 lại xuất hiện trên mặt báo trong vai một người thợ kiếm sống."},{"t":"Đồng lương nhỏ, những trang viết lớn. Đồng tiền từ nghề sửa ảnh, vẽ thuê chỉ đủ cho một cuộc sống thanh đạm. Nhưng sống bằng hai bàn tay cho Người một điều không ai ban phát được: sự tự chủ. Không phụ thuộc vào ai về tiền bạc, Người có thể dành thời gian đến thư viện đọc sách, học tiếng Pháp, dự các buổi mít tinh và viết báo. Những năm ở Paris, bài của Nguyễn Ái Quốc xuất hiện trên nhiều tờ báo tiến bộ của Pháp. Ngày 1/4/1922, số đầu tiên của báo Le Paria (Người cùng khổ), cơ quan của Hội Liên hiệp thuộc địa, ra đời. Nguyễn Ái Quốc vừa là chủ nhiệm kiêm chủ bút, vừa viết bài, tự tay vẽ tranh biếm họa và đi bán báo. Đôi bàn tay từng rửa bát, sửa ảnh giờ cầm bút và cọ vẽ để tố cáo chế độ thuộc địa. Tác phẩm “Bản án chế độ thực dân Pháp”, xuất bản ở Paris năm 1925, là kết tinh của những năm cầm bút ấy."},{"t":"Bạn có biết? Theo Trần Dân Tiên, những năm ở trọ tại Paris, mỗi buổi sáng trước khi đi làm, Người để một viên gạch vào lò bếp của khách sạn. Chiều về, Người lấy viên gạch ra, bọc vào mấy tờ báo cũ rồi đặt xuống nệm cho đỡ rét."},{"t":"Nhìn thế giới từ gian bếp và xưởng thợ. Nhiều người Việt Nam đầu thế kỷ XX sang Pháp để vào trường lớn, làm công chức hay buôn bán. Người thanh niên ra đi năm 1911 nhìn phương Tây từ một chỗ đứng khác: từ bếp tàu, hầm lò, gian bếp khách sạn và bàn thợ sửa ảnh. Chỗ đứng ấy cho anh thấy điều mà hành khách hạng nhất khó nhận ra. Theo cuốn “Hồ Chí Minh – Tiểu sử”, ngay những ngày đầu trên đất Pháp, anh đã thấy ở Pháp cũng có những người nghèo như ở Việt Nam. Từ những điều mắt thấy tai nghe ấy, nhận thức của Người dần vượt ra khỏi khuôn khổ một dân tộc. Kẻ thù không phải là người Pháp hay người Anh nói chung, mà là chủ nghĩa thực dân và sự áp bức. Bạn bè không chỉ là đồng bào mình, mà còn là những người lao động và những dân tộc bị áp bức ở khắp nơi. Chính nhận thức ấy chuẩn bị cho bước ngoặt tháng 7/1920, khi Người đọc bản Luận cương của Lênin về vấn đề dân tộc và thuộc địa, và tìm thấy con đường giải phóng cho dân tộc mình."},{"t":"Dù màu da có khác nhau, trên đời này chỉ có hai giống người: giống người bóc lột và giống người bị bóc lột. Mà cũng chỉ có một mối tình hữu ái là thật mà thôi: tình hữu ái vô sản. — Nguyễn Ái Quốc (theo Trần Dân Tiên)"},{"t":"Từ hai bàn tay đến sức mạnh của cả dân tộc. Hình ảnh hai bàn tay gắn liền với tư tưởng tự lực, tự cường mà Người theo đuổi suốt đời. Năm 1911, đó là lựa chọn của một cá nhân: không trông vào ai, tự nuôi mình bằng lao động để đi tìm đường. Ba mươi tư năm sau, tư tưởng ấy trở thành lời hiệu triệu của cả một dân tộc. Tháng 8/1945, trong Thư kêu gọi Tổng khởi nghĩa, Người kêu gọi toàn dân đứng dậy, dựa vào sức mình mà giành lấy độc lập. Khi ấy, Người mới trở về Tổ quốc được hơn bốn năm, sau ba mươi năm sống và hoạt động ở nước ngoài. Từ đôi bàn tay trắng của người phụ bếp năm 1911 đến lời hiệu triệu năm 1945 là một chặng đường dài. Xuyên suốt chặng đường ấy vẫn là một niềm tin: sức lao động và ý chí của con người có thể làm nên những điều tưởng như không thể."},{"t":"Giờ quyết định cho vận mệnh dân tộc ta đã đến. Toàn quốc đồng bào hãy đứng dậy đem sức ta mà tự giải phóng cho ta. — Hồ Chí Minh, Thư kêu gọi Tổng khởi nghĩa, tháng 8/1945"},{"t":"Các mốc thời gian. 3/6/1911: Nhận làm phụ bếp trên tàu Amiral Latouche-Tréville với tên Văn Ba. 15/9/1911: Từ Marseille viết đơn xin học Trường Thuộc địa, không được chấp nhận. 1911 – 1913: Làm thuê trên tàu biển, qua nhiều hải cảng châu Âu, châu Phi, châu Mỹ. Cuối năm 1913: Ở Anh, làm thuê ở khách sạn Drayton Court. Những năm ở London: Cào tuyết, đốt lò; phụ bếp rồi làm bánh ở khách sạn Carlton. Cuối năm 1917: Trở lại Pháp. 7/1919: Ở số 6 Villa des Gobelins, Paris; sống bằng nghề sửa ảnh, vẽ thuê. 7/1921: Chuyển về số 9 ngõ Compoint, quận 17. 1/4/1922: Số đầu báo Le Paria ra đời. 6/1923: Rời Paris sang Liên Xô."},{"t":"Dấu tích hôm nay. Hai bàn tay không để lại hiện vật gốc, nhưng dấu vết của chúng còn ở nhiều nơi. Ở London, tấm biển trên tường tòa New Zealand House nhắc rằng người phụ bếp năm xưa từng làm việc ở khách sạn Carlton. Ở Boston, khách sạn Parker House vẫn kể câu chuyện về người thợ làm bánh Việt Nam. Còn tên Văn Ba trong sổ lĩnh lương của con tàu năm 1911 được giữ lại qua bản chụp lưu tại Bảo tàng Hồ Chí Minh (xem chuyên đề Tàu Amiral Latouche-Tréville). Trong gian trưng bày này, bảng “Hai bàn tay” đặt giữa không gian một bến cảng lao động, nơi người thanh niên từng lui tới tìm việc trên tàu. Đứng trước bảng, người xem có thể tự hỏi: mình sẽ mang theo gì khi bước vào một hành trình lớn? Người thanh niên năm 1911 chỉ mang theo hai thứ: đôi bàn tay và một câu hỏi về vận mệnh dân tộc."}],"so_chu":2071},{"i":11,"tieu_de_bang":"Bến cảng Sài Gòn","tieu_de":"Bến cảng Sài Gòn năm 1911 – và câu hỏi: con tàu đã rời bến ở đâu?","sapo":"Mỗi dịp tháng Sáu, Bến Nhà Rồng được nhắc đến như nơi người thanh niên Nguyễn Tất Thành xuống tàu ra đi. Nhưng một tài liệu của thương cảng Sài Gòn in năm 1912 lại gợi ý một cầu tàu khác, ở bên kia cửa rạch Bến Nghé. Đi tìm lời giải cho câu hỏi nhỏ ấy, ta gặp lại cả một bến cảng thuộc địa: cầu tàu, kho hàng, cột neo, và những con người lao động quanh đó.","bia":{"src":"textures/ht/ht_anh_saigon_la_pointe_des_blagueurs_le_paul_lecat_sur.jpg","credit":"Ảnh: Francis Alexandre Decoly · Public domain · Wikimedia Commons"},"khoi":[{"loai":"doan","tieu_de":"Hai bờ một cửa rạch","text":"Hãy hình dung bờ sông Sài Gòn vào trưa ngày 5/6/1911. Một con tàu hơi nước dài gần một trăm hai mươi mét, mang tên Amiral Latouche-Tréville, chuẩn bị nhổ neo đi Marseille. Trong số người làm việc trên tàu có một phụ bếp mới nhận việc hai hôm trước, tên là Văn Ba. Con tàu nằm ở đâu trên dòng sông ấy? Câu hỏi tưởng đơn giản, nhưng đến nay vẫn được các nhà nghiên cứu bàn luận.\n\nMuốn trả lời, trước hết phải hình dung địa thế bến cảng. Ở đoạn này, rạch Bến Nghé đổ vào sông Sài Gòn, chia bờ sông thành hai phía. Phía bắc cửa rạch là trung tâm thành phố, nơi những con đường lớn như Catinat, Charner chạy thẳng ra bờ sông. Phía nam cửa rạch là vùng Khánh Hội, nơi tòa Nhà Rồng của hãng Messageries Maritimes đứng ngay mũi đất. Ghe thuyền từ Chợ Lớn theo rạch Bến Nghé ra vào, chở lúa gạo và hàng hóa. Tàu biển thì từ cửa biển ngược dòng lên, tìm chỗ cập cầu tàu hoặc thả neo giữa dòng.","doc":1},{"loai":"doan","tieu_de":"Bến cảng trong tài liệu năm 1912","text":"Nhà nghiên cứu Nguyễn Đình Đầu đã tìm lời giải trong một tài liệu hành chính thời thuộc địa. Đó là tập “Port de Commerce de Saigon”, tức Thương cảng Sài Gòn, do Tổng nha Công chánh in năm 1912. Theo tài liệu này, cảng Sài Gòn khi ấy gồm hai phần chính, mỗi phần dài chừng sáu trăm mét.\n\nBên bờ trung tâm thành phố là thương cảng, với năm cầu tàu. Ba cầu tàu nhỏ ở đầu đường Catinat, nay là đường Đồng Khởi, dành cho hãng chuyên chở đường sông. Một cầu tàu lớn ở đầu đường Charner, nay là đường Nguyễn Huệ, dành cho những tàu viễn dương lớn. Bên Khánh Hội là bến Nhà Rồng, dành riêng cho tàu của hãng Messageries Maritimes. Hãng này đã lập bến từ những năm 1860, cùng lúc dựng tòa trụ sở có đôi rồng trên nóc (xem chuyên đề Nhà Rồng). Theo tư liệu của Bảo tàng Thành phố Hồ Chí Minh, ngay từ năm 1864, đoạn sông trước bến Nhà Rồng đã sâu khoảng tám mét khi mực nước trung bình. Khi triều lên, độ sâu tới mười mét, đủ cho tàu ba nghìn tấn ra vào.","doc":2},{"loai":"anh","src":"textures/bang_w/G04_11_1.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bến cảng Sài Gòn”, nhìn theo hướng ngược lại."},{"loai":"doan","tieu_de":"Con tàu hãng Năm Sao cập cầu nào?","text":"Từ tài liệu ấy, nhà nghiên cứu Nguyễn Đình Đầu đưa ra một lập luận rõ ràng. Năm 1911, hai hãng tàu biển lớn nhất ở Sài Gòn là Messageries Maritimes, người Việt gọi là hãng Đầu Ngựa, và Chargeurs Réunis, người Việt gọi là hãng Năm Sao. Mỗi hãng có chỗ cập bến riêng. Bến Nhà Rồng dành riêng cho tàu hãng Đầu Ngựa. Còn Amiral Latouche-Tréville là tàu viễn dương của hãng Năm Sao. Vì vậy, theo ông, con tàu đã cập cầu tàu lớn của thương cảng ở đầu đường Charner, tức đầu đường Nguyễn Huệ phía bờ sông ngày nay.\n\nNếu lập luận ấy đúng, thì hôm 5/6/1911, người phụ bếp trẻ đã bước lên tàu ở bờ bên này cửa rạch, và từ cầu tàu có thể nhìn sang tòa Nhà Rồng ở bờ bên kia. Tuy vậy, vị trí chính xác nơi con tàu neo đậu hôm ấy vẫn được giới nghiên cứu bàn luận. Điều chắc chắn là cuộc ra đi diễn ra từ bến cảng Sài Gòn, trên đoạn sông ngắn giữa những cầu tàu này. Hai địa điểm được nhắc tới chỉ cách nhau một cửa rạch.","doc":3},{"loai":"ban_co_biet","text":"Theo nhà nghiên cứu Nguyễn Đình Đầu, văn phòng hãng tàu nơi Nguyễn Tất Thành xin việc nằm trên lầu một quán cà phê La Rotonde, số 2 đường Catinat, nay là đường Đồng Khởi. Đầu đường Catinat và đầu đường Charner cùng nhìn ra bờ sông, chỉ cách nhau một dãy phố.","nguon_ten":"Nguyễn Đình Đầu, “Nơi Bác ra đi tìm đường cứu nước”, báo Thanh Niên, 10/10/2024 – https://thanhnien.vn/noi-bac-ra-di-tim-duong-cuu-nuoc-185241009213949499.htm","doc":4},{"loai":"doan","tieu_de":"Vì sao Bến Nhà Rồng trở thành biểu tượng","text":"Nếu con tàu có thể đã không neo ở bến Nhà Rồng, vì sao Bến Nhà Rồng lại trở thành biểu tượng của cuộc ra đi? Có nhiều lý do đan xen. Trước hết, tòa Nhà Rồng là công trình nổi bật nhất bên bờ sông, với đôi rồng trên nóc nhìn ra cửa rạch, và từ lâu được coi là biểu tượng của cảng Sài Gòn. Hơn một thế kỷ trôi qua, nhiều cầu tàu, kho bãi thời ấy đã thay đổi hoặc không còn, nhưng tòa nhà vẫn đứng nguyên chỗ cũ.\n\nThứ hai, vùng Khánh Hội không xa lạ với người thanh niên năm 1911. Anh từng ở tạm tại một chi nhánh của Liên Thành ở Khánh Hội, và lui tới các bến tàu để dò hỏi việc làm (xem chuyên đề Sài Gòn – Bến Nhà Rồng). Thứ ba, sau ngày đất nước thống nhất, tòa nhà được chọn làm nơi lưu niệm Chủ tịch Hồ Chí Minh từ năm 1979, rồi trở thành bảo tàng năm 1995. Từ đó, những hoạt động kỷ niệm ngày 5/6 hằng năm gắn với nơi này. Một biểu tượng lịch sử không nhất thiết trùng với một tọa độ chính xác đến từng mét. Nó là nơi một cộng đồng chọn để gửi gắm ký ức chung.","doc":5},{"loai":"anh","src":"textures/ht/ht_anh_saigon_la_pointe_des_blagueurs_le_paul_lecat_sur.jpg","chu_thich":"Bưu ảnh sông Sài Gòn đoạn mũi Pointe des Blagueurs, tàu viễn dương Paul-Lecat của hãng Messageries Maritimes neo giữa dòng; thông tin lưu trữ ghi năm 1919. Tàu biển đến Sài Gòn thời ấy có khi cập cầu tàu, có khi thả neo giữa sông.","credit":"Ảnh: Francis Alexandre Decoly · Public domain · Wikimedia Commons"},{"loai":"doan","tieu_de":"Những người làm nên bến cảng","text":"Bến cảng Sài Gòn năm 1911 không chỉ có tàu và kho hàng. Nó vận hành nhờ sức lao động của rất nhiều người Việt. Người phu khuân vác đưa những bao gạo nặng từ kho xuống tàu, từ tàu lên bờ. Người chèo ghe, kéo xà lan chở lúa gạo từ Chợ Lớn theo rạch Bến Nghé ra sông. Người thợ máy sửa nồi hơi, máy tàu. Người kéo xe chở khách và hàng từ bến vào phố. Trên chính các con tàu Pháp, người Việt làm bồi phòng, phụ bếp, đốt lò, những việc nặng nhọc nhất với đồng lương thấp nhất.\n\nNguyễn Tất Thành đã sống giữa những người lao động ấy trong bốn tháng ở Sài Gòn, và cuối cùng chính anh cũng trở thành một người trong số họ khi xin làm phụ bếp. Chỗ đứng ấy về sau định hình cách anh nhìn thế giới (xem chuyên đề Hai bàn tay). Những tấm bưu ảnh thời ấy thường chỉ chụp dòng sông rộng và những con tàu lớn; người phu, người thợ hiếm khi là nhân vật chính. Nhưng không có họ, bến cảng không thể vận hành, và những con tàu không thể rời bến.","doc":6},{"loai":"doan","tieu_de":"Từ bến cảng đến phong trào thợ thuyền","text":"Ngược lên phía thượng lưu, cách Nhà Rồng không xa, là xưởng Ba Son, nơi sửa chữa và đóng tàu lớn nhất Sài Gòn thời ấy. Người Pháp lập xưởng từ những năm 1860, trên nền Xưởng Thủy cũ của nhà Nguyễn. Cùng với bến cảng, xưởng Ba Son tập trung một đội ngũ đông đảo công nhân người Việt, những người thợ quen với máy móc, kỷ luật lao động và cả sự bất công của chế độ thuộc địa.\n\nChính từ bến cảng và xưởng thợ ấy, phong trào công nhân Sài Gòn lớn lên. Tháng 8/1925, công nhân Ba Son bãi công, dưới sự lãnh đạo của người thợ máy Tôn Đức Thắng. Cuộc bãi công kéo dài việc sửa chữa, khiến chiến hạm Michelet không thể rời bến đúng hạn để chở quân sang đàn áp phong trào cách mạng Trung Quốc. Sự kiện được đánh giá là bước tiến mới, đánh dấu giai cấp công nhân Việt Nam bước đầu đi vào đấu tranh tự giác. Cũng năm 1925, ở Quảng Châu, Nguyễn Ái Quốc thành lập Hội Việt Nam Cách mạng Thanh niên. Người phụ bếp rời bến năm 1911 và những người thợ ở lại bên bến cảng, sau mười bốn năm, đã đi về cùng một hướng.","doc":7},{"loai":"ban_co_biet","text":"Đường Charner xưa, nay là đường Nguyễn Huệ, nối bờ sông với trụ sở chính quyền thành phố. Từ ngày 19/5/2015, trước trụ sở Ủy ban nhân dân Thành phố ở đầu kia con đường có tượng đài Chủ tịch Hồ Chí Minh. Nếu theo lập luận của nhà nghiên cứu Nguyễn Đình Đầu, con đường ấy nối nơi Người xuống tàu năm 1911 với nơi đặt tượng Người hôm nay.","nguon_ten":"VOV – “Khánh thành Tượng đài Chủ tịch Hồ Chí Minh tại TP.HCM”; báo Thanh Niên – “Khánh thành tượng đài Chủ tịch Hồ Chí Minh trên phố đi bộ Nguyễn Huệ”; Nguyễn Đình Đầu, “Nơi Bác ra đi tìm đường cứu nước”, báo Thanh Niên, 10/10/2024 – https://thanhnien.vn/noi-bac-ra-di-tim-duong-cuu-nuoc-185241009213949499.htm","doc":8},{"loai":"doan","tieu_de":"Bến cảng trong không gian phục dựng","text":"Không gian 3D của gian trưng bày tái hiện một bến cảng đầu thế kỷ XX: dãy kho hàng mái tôn nối dài bờ sông, những cột neo bằng gang, đèn treo trong lồng sắt, thùng gỗ, thùng phuy và xe kéo. Mỗi chi tiết gợi một nhịp lao động. Kho mái tôn che mưa nắng cho hàng hóa chờ xuống tàu. Cột neo gang, thấp và chắc, là nơi thủy thủ quấn những sợi dây chão lớn để giữ tàu sát cầu. Đèn treo có lồng bảo vệ soi sáng lối đi và những giờ làm việc lúc trời tối. Thùng gỗ, thùng phuy là cách đóng gói quen thuộc của hàng hóa đi biển thời ấy.\n\nCần nói rõ: đây là phần dựng minh họa, không phải bản sao chính xác của một cầu tàu cụ thể, dù là bến Nhà Rồng hay cầu tàu đầu đường Charner. Không gian ấy chọn những yếu tố tiêu biểu để gợi không khí chung của một thương cảng thuộc địa: tấp nập hàng hóa nhưng nặng nhọc với người làm thuê. Khi đi dưới dãy đèn treo trong gian, người xem bước trên một bến cảng tưởng tượng. Nhưng những con người từng làm việc trên những bến cảng như thế là có thật.","doc":9},{"loai":"anh","src":"textures/bang_w/G04_11_2.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bến cảng Sài Gòn”, nhìn sang bên phải."},{"loai":"doan","tieu_de":"Bến cảng sau năm 1911","text":"Bến cảng Sài Gòn còn đổi thay nhiều sau ngày con tàu hãng Năm Sao rời bến. Theo tư liệu của Bảo tàng Thành phố Hồ Chí Minh, đến năm 1930, hai cầu tàu cốt sắt của hãng Messageries Maritimes đã hư hỏng nặng. Thay thế chúng là một cầu tàu bê tông cốt sắt dài hơn bốn trăm hai mươi mét. Cảng tiếp tục mở rộng về phía Khánh Hội, và trong nhiều thập kỷ là cửa ngõ đường biển quan trọng bậc nhất của miền Nam.\n\nCòn người thanh niên ra đi năm 1911 thì không có dịp trở lại Sài Gòn. Ba mươi lăm năm sau, ngày 31/5/1946, trước khi lên đường sang Pháp, Chủ tịch Hồ Chí Minh viết thư gửi đồng bào Nam Bộ, khi miền Nam đang kháng chiến chống thực dân Pháp trở lại xâm lược. Ngày 2/7/1976, Quốc hội nước Việt Nam thống nhất quyết định đặt tên Thành phố Hồ Chí Minh cho Sài Gòn – Gia Định. Thành phố cảng mà Người rời đi năm 1911 từ đó mang tên Người.","doc":10},{"loai":"trich","text":"Đồng bào Nam Bộ là dân nước Việt Nam. Sông có thể cạn, núi có thể mòn, song chân lý đó không bao giờ thay đổi!","nguoi":"Hồ Chí Minh, Thư gửi đồng bào Nam Bộ, 31/5/1946","nguon_ten":"Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia","doc":11},{"loai":"anh","src":"textures/bang_w/G04_11_3.jpg","p3d":true,"credit":"Phục dựng 3D · Bảo tàng Hành trình","chu_thich":"Không gian 3D tái hiện góc “Bến cảng Sài Gòn”, nhìn sang bên trái."},{"loai":"doan","tieu_de":"Dấu tích hôm nay","text":"Người muốn tìm lại bến cảng năm 1911 hôm nay có thể bắt đầu từ đầu đường Nguyễn Huệ phía bờ sông, khu vực Bến Bạch Đằng. Theo lập luận của nhà nghiên cứu Nguyễn Đình Đầu, cầu tàu lớn năm xưa nằm ở khu vực này. Đứng quay mặt ra sông, nhìn sang bên phải, bên kia cửa rạch Bến Nghé là tòa Nhà Rồng với đôi rồng trên nóc. Bên này cửa rạch, cột cờ Thủ Ngữ vẫn đứng trên mũi đất năm xưa (xem chuyên đề Bến cảng Sài Gòn đầu thế kỷ XX).\n\nHoạt động bốc xếp hàng hóa của cảng Sài Gòn ở khu Nhà Rồng – Khánh Hội đã được di dời dần về khu cảng Hiệp Phước ở phía nam thành phố. Bờ sông năm xưa đang nhường chỗ cho những không gian công cộng mới (xem chuyên đề Bến Nhà Rồng ngày nay). Ngày 5/6 hằng năm vẫn được kỷ niệm là Ngày Bác Hồ ra đi tìm đường cứu nước. Dù con tàu năm ấy cập cầu tàu nào, dòng sông trước mặt vẫn là dòng sông đã đưa người phụ bếp trẻ ra biển lớn.","doc":12}],"nguon":["Nguyễn Đình Đầu, “Nơi Bác ra đi tìm đường cứu nước”, báo Thanh Niên, 10/10/2024 – https://thanhnien.vn/noi-bac-ra-di-tim-duong-cuu-nuoc-185241009213949499.htm","Bảo tàng Thành phố Hồ Chí Minh – Thương cảng, thương mại dịch vụ Sài Gòn – Thành phố Hồ Chí Minh – https://hcmc-museum.edu.vn/luu-tru/4008","Bảo tàng Hồ Chí Minh – Chi nhánh TP. Hồ Chí Minh: Giới thiệu bảo tàng – https://bennharong.vn/gioi-thieu-bao-tang","Tạp chí Hồ Chí Minh học – “Về một số con tàu trong những hải trình của Chủ tịch Hồ Chí Minh” – https://tapchihochiminh.hcma.vn/Content/ve-mot-so-con-tau-trong-nhung-hai-trinh-cua-chu-tich-ho-chi-minh-01318","Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","Hồ Chí Minh Toàn tập, NXB Chính trị quốc gia (Thư gửi đồng bào Nam Bộ, 31/5/1946)"],"doc":[{"t":"Bến cảng Sài Gòn năm 1911 – và câu hỏi: con tàu đã rời bến ở đâu?. Mỗi dịp tháng Sáu, Bến Nhà Rồng được nhắc đến như nơi người thanh niên Nguyễn Tất Thành xuống tàu ra đi. Nhưng một tài liệu của thương cảng Sài Gòn in năm 1912 lại gợi ý một cầu tàu khác, ở bên kia cửa rạch Bến Nghé. Đi tìm lời giải cho câu hỏi nhỏ ấy, ta gặp lại cả một bến cảng thuộc địa: cầu tàu, kho hàng, cột neo, và những con người lao động quanh đó."},{"t":"Hai bờ một cửa rạch. Hãy hình dung bờ sông Sài Gòn vào trưa ngày 5/6/1911. Một con tàu hơi nước dài gần một trăm hai mươi mét, mang tên Amiral Latouche-Tréville, chuẩn bị nhổ neo đi Marseille. Trong số người làm việc trên tàu có một phụ bếp mới nhận việc hai hôm trước, tên là Văn Ba. Con tàu nằm ở đâu trên dòng sông ấy? Câu hỏi tưởng đơn giản, nhưng đến nay vẫn được các nhà nghiên cứu bàn luận. Muốn trả lời, trước hết phải hình dung địa thế bến cảng. Ở đoạn này, rạch Bến Nghé đổ vào sông Sài Gòn, chia bờ sông thành hai phía. Phía bắc cửa rạch là trung tâm thành phố, nơi những con đường lớn như Catinat, Charner chạy thẳng ra bờ sông. Phía nam cửa rạch là vùng Khánh Hội, nơi tòa Nhà Rồng của hãng Messageries Maritimes đứng ngay mũi đất. Ghe thuyền từ Chợ Lớn theo rạch Bến Nghé ra vào, chở lúa gạo và hàng hóa. Tàu biển thì từ cửa biển ngược dòng lên, tìm chỗ cập cầu tàu hoặc thả neo giữa dòng."},{"t":"Bến cảng trong tài liệu năm 1912. Nhà nghiên cứu Nguyễn Đình Đầu đã tìm lời giải trong một tài liệu hành chính thời thuộc địa. Đó là tập “Port de Commerce de Saigon”, tức Thương cảng Sài Gòn, do Tổng nha Công chánh in năm 1912. Theo tài liệu này, cảng Sài Gòn khi ấy gồm hai phần chính, mỗi phần dài chừng sáu trăm mét. Bên bờ trung tâm thành phố là thương cảng, với năm cầu tàu. Ba cầu tàu nhỏ ở đầu đường Catinat, nay là đường Đồng Khởi, dành cho hãng chuyên chở đường sông. Một cầu tàu lớn ở đầu đường Charner, nay là đường Nguyễn Huệ, dành cho những tàu viễn dương lớn. Bên Khánh Hội là bến Nhà Rồng, dành riêng cho tàu của hãng Messageries Maritimes. Hãng này đã lập bến từ những năm 1860, cùng lúc dựng tòa trụ sở có đôi rồng trên nóc (xem chuyên đề Nhà Rồng). Theo tư liệu của Bảo tàng Thành phố Hồ Chí Minh, ngay từ năm 1864, đoạn sông trước bến Nhà Rồng đã sâu khoảng tám mét khi mực nước trung bình. Khi triều lên, độ sâu tới mười mét, đủ cho tàu ba nghìn tấn ra vào."},{"t":"Con tàu hãng Năm Sao cập cầu nào?. Từ tài liệu ấy, nhà nghiên cứu Nguyễn Đình Đầu đưa ra một lập luận rõ ràng. Năm 1911, hai hãng tàu biển lớn nhất ở Sài Gòn là Messageries Maritimes, người Việt gọi là hãng Đầu Ngựa, và Chargeurs Réunis, người Việt gọi là hãng Năm Sao. Mỗi hãng có chỗ cập bến riêng. Bến Nhà Rồng dành riêng cho tàu hãng Đầu Ngựa. Còn Amiral Latouche-Tréville là tàu viễn dương của hãng Năm Sao. Vì vậy, theo ông, con tàu đã cập cầu tàu lớn của thương cảng ở đầu đường Charner, tức đầu đường Nguyễn Huệ phía bờ sông ngày nay. Nếu lập luận ấy đúng, thì hôm 5/6/1911, người phụ bếp trẻ đã bước lên tàu ở bờ bên này cửa rạch, và từ cầu tàu có thể nhìn sang tòa Nhà Rồng ở bờ bên kia. Tuy vậy, vị trí chính xác nơi con tàu neo đậu hôm ấy vẫn được giới nghiên cứu bàn luận. Điều chắc chắn là cuộc ra đi diễn ra từ bến cảng Sài Gòn, trên đoạn sông ngắn giữa những cầu tàu này. Hai địa điểm được nhắc tới chỉ cách nhau một cửa rạch."},{"t":"Bạn có biết? Theo nhà nghiên cứu Nguyễn Đình Đầu, văn phòng hãng tàu nơi Nguyễn Tất Thành xin việc nằm trên lầu một quán cà phê La Rotonde, số 2 đường Catinat, nay là đường Đồng Khởi. Đầu đường Catinat và đầu đường Charner cùng nhìn ra bờ sông, chỉ cách nhau một dãy phố."},{"t":"Vì sao Bến Nhà Rồng trở thành biểu tượng. Nếu con tàu có thể đã không neo ở bến Nhà Rồng, vì sao Bến Nhà Rồng lại trở thành biểu tượng của cuộc ra đi? Có nhiều lý do đan xen. Trước hết, tòa Nhà Rồng là công trình nổi bật nhất bên bờ sông, với đôi rồng trên nóc nhìn ra cửa rạch, và từ lâu được coi là biểu tượng của cảng Sài Gòn. Hơn một thế kỷ trôi qua, nhiều cầu tàu, kho bãi thời ấy đã thay đổi hoặc không còn, nhưng tòa nhà vẫn đứng nguyên chỗ cũ. Thứ hai, vùng Khánh Hội không xa lạ với người thanh niên năm 1911. Anh từng ở tạm tại một chi nhánh của Liên Thành ở Khánh Hội, và lui tới các bến tàu để dò hỏi việc làm (xem chuyên đề Sài Gòn – Bến Nhà Rồng). Thứ ba, sau ngày đất nước thống nhất, tòa nhà được chọn làm nơi lưu niệm Chủ tịch Hồ Chí Minh từ năm 1979, rồi trở thành bảo tàng năm 1995. Từ đó, những hoạt động kỷ niệm ngày 5/6 hằng năm gắn với nơi này. Một biểu tượng lịch sử không nhất thiết trùng với một tọa độ chính xác đến từng mét. Nó là nơi một cộng đồng chọn để gửi gắm ký ức chung."},{"t":"Những người làm nên bến cảng. Bến cảng Sài Gòn năm 1911 không chỉ có tàu và kho hàng. Nó vận hành nhờ sức lao động của rất nhiều người Việt. Người phu khuân vác đưa những bao gạo nặng từ kho xuống tàu, từ tàu lên bờ. Người chèo ghe, kéo xà lan chở lúa gạo từ Chợ Lớn theo rạch Bến Nghé ra sông. Người thợ máy sửa nồi hơi, máy tàu. Người kéo xe chở khách và hàng từ bến vào phố. Trên chính các con tàu Pháp, người Việt làm bồi phòng, phụ bếp, đốt lò, những việc nặng nhọc nhất với đồng lương thấp nhất. Nguyễn Tất Thành đã sống giữa những người lao động ấy trong bốn tháng ở Sài Gòn, và cuối cùng chính anh cũng trở thành một người trong số họ khi xin làm phụ bếp. Chỗ đứng ấy về sau định hình cách anh nhìn thế giới (xem chuyên đề Hai bàn tay). Những tấm bưu ảnh thời ấy thường chỉ chụp dòng sông rộng và những con tàu lớn; người phu, người thợ hiếm khi là nhân vật chính. Nhưng không có họ, bến cảng không thể vận hành, và những con tàu không thể rời bến."},{"t":"Từ bến cảng đến phong trào thợ thuyền. Ngược lên phía thượng lưu, cách Nhà Rồng không xa, là xưởng Ba Son, nơi sửa chữa và đóng tàu lớn nhất Sài Gòn thời ấy. Người Pháp lập xưởng từ những năm 1860, trên nền Xưởng Thủy cũ của nhà Nguyễn. Cùng với bến cảng, xưởng Ba Son tập trung một đội ngũ đông đảo công nhân người Việt, những người thợ quen với máy móc, kỷ luật lao động và cả sự bất công của chế độ thuộc địa. Chính từ bến cảng và xưởng thợ ấy, phong trào công nhân Sài Gòn lớn lên. Tháng 8/1925, công nhân Ba Son bãi công, dưới sự lãnh đạo của người thợ máy Tôn Đức Thắng. Cuộc bãi công kéo dài việc sửa chữa, khiến chiến hạm Michelet không thể rời bến đúng hạn để chở quân sang đàn áp phong trào cách mạng Trung Quốc. Sự kiện được đánh giá là bước tiến mới, đánh dấu giai cấp công nhân Việt Nam bước đầu đi vào đấu tranh tự giác. Cũng năm 1925, ở Quảng Châu, Nguyễn Ái Quốc thành lập Hội Việt Nam Cách mạng Thanh niên. Người phụ bếp rời bến năm 1911 và những người thợ ở lại bên bến cảng, sau mười bốn năm, đã đi về cùng một hướng."},{"t":"Bạn có biết? Đường Charner xưa, nay là đường Nguyễn Huệ, nối bờ sông với trụ sở chính quyền thành phố. Từ ngày 19/5/2015, trước trụ sở Ủy ban nhân dân Thành phố ở đầu kia con đường có tượng đài Chủ tịch Hồ Chí Minh. Nếu theo lập luận của nhà nghiên cứu Nguyễn Đình Đầu, con đường ấy nối nơi Người xuống tàu năm 1911 với nơi đặt tượng Người hôm nay."},{"t":"Bến cảng trong không gian phục dựng. Không gian 3D của gian trưng bày tái hiện một bến cảng đầu thế kỷ XX: dãy kho hàng mái tôn nối dài bờ sông, những cột neo bằng gang, đèn treo trong lồng sắt, thùng gỗ, thùng phuy và xe kéo. Mỗi chi tiết gợi một nhịp lao động. Kho mái tôn che mưa nắng cho hàng hóa chờ xuống tàu. Cột neo gang, thấp và chắc, là nơi thủy thủ quấn những sợi dây chão lớn để giữ tàu sát cầu. Đèn treo có lồng bảo vệ soi sáng lối đi và những giờ làm việc lúc trời tối. Thùng gỗ, thùng phuy là cách đóng gói quen thuộc của hàng hóa đi biển thời ấy. Cần nói rõ: đây là phần dựng minh họa, không phải bản sao chính xác của một cầu tàu cụ thể, dù là bến Nhà Rồng hay cầu tàu đầu đường Charner. Không gian ấy chọn những yếu tố tiêu biểu để gợi không khí chung của một thương cảng thuộc địa: tấp nập hàng hóa nhưng nặng nhọc với người làm thuê. Khi đi dưới dãy đèn treo trong gian, người xem bước trên một bến cảng tưởng tượng. Nhưng những con người từng làm việc trên những bến cảng như thế là có thật."},{"t":"Bến cảng sau năm 1911. Bến cảng Sài Gòn còn đổi thay nhiều sau ngày con tàu hãng Năm Sao rời bến. Theo tư liệu của Bảo tàng Thành phố Hồ Chí Minh, đến năm 1930, hai cầu tàu cốt sắt của hãng Messageries Maritimes đã hư hỏng nặng. Thay thế chúng là một cầu tàu bê tông cốt sắt dài hơn bốn trăm hai mươi mét. Cảng tiếp tục mở rộng về phía Khánh Hội, và trong nhiều thập kỷ là cửa ngõ đường biển quan trọng bậc nhất của miền Nam. Còn người thanh niên ra đi năm 1911 thì không có dịp trở lại Sài Gòn. Ba mươi lăm năm sau, ngày 31/5/1946, trước khi lên đường sang Pháp, Chủ tịch Hồ Chí Minh viết thư gửi đồng bào Nam Bộ, khi miền Nam đang kháng chiến chống thực dân Pháp trở lại xâm lược. Ngày 2/7/1976, Quốc hội nước Việt Nam thống nhất quyết định đặt tên Thành phố Hồ Chí Minh cho Sài Gòn – Gia Định. Thành phố cảng mà Người rời đi năm 1911 từ đó mang tên Người."},{"t":"Đồng bào Nam Bộ là dân nước Việt Nam. Sông có thể cạn, núi có thể mòn, song chân lý đó không bao giờ thay đổi! — Hồ Chí Minh, Thư gửi đồng bào Nam Bộ, 31/5/1946"},{"t":"Dấu tích hôm nay. Người muốn tìm lại bến cảng năm 1911 hôm nay có thể bắt đầu từ đầu đường Nguyễn Huệ phía bờ sông, khu vực Bến Bạch Đằng. Theo lập luận của nhà nghiên cứu Nguyễn Đình Đầu, cầu tàu lớn năm xưa nằm ở khu vực này. Đứng quay mặt ra sông, nhìn sang bên phải, bên kia cửa rạch Bến Nghé là tòa Nhà Rồng với đôi rồng trên nóc. Bên này cửa rạch, cột cờ Thủ Ngữ vẫn đứng trên mũi đất năm xưa (xem chuyên đề Bến cảng Sài Gòn đầu thế kỷ XX). Hoạt động bốc xếp hàng hóa của cảng Sài Gòn ở khu Nhà Rồng – Khánh Hội đã được di dời dần về khu cảng Hiệp Phước ở phía nam thành phố. Bờ sông năm xưa đang nhường chỗ cho những không gian công cộng mới (xem chuyên đề Bến Nhà Rồng ngày nay). Ngày 5/6 hằng năm vẫn được kỷ niệm là Ngày Bác Hồ ra đi tìm đường cứu nước. Dù con tàu năm ấy cập cầu tàu nào, dòng sông trước mặt vẫn là dòng sông đã đưa người phụ bếp trẻ ra biển lớn."}],"so_chu":2038}],"do_vat":[{"id":"caged_hanging_light@-2.8,7.2","x":-2.8,"y":5.1,"z":7.22,"loai":"caged_hanging_light","ten":"Đèn treo kho cảng","tieu_de":"Ánh đèn bên những dãy kho","text":"Chiếc đèn treo có lồng sắt bảo vệ bóng đèn là đồ vật minh họa, không phải hiện vật gốc, gợi lại kiểu chiếu sáng quen thuộc trong những dãy kho, xưởng bên bến cảng Sài Gòn đầu thế kỷ XX — nơi ánh sáng phải đủ chắc chắn để chịu được va chạm của người khuân vác, xe kéo hàng qua lại suốt ngày đêm. Dưới thứ ánh đèn ấy, hàng hóa được xếp dỡ, kiểm đếm rồi chất lên những chuyến tàu viễn dương chờ sẵn ngoài sông.\n\nSài Gòn – Chợ Lớn những năm đầu thế kỷ XX là thương cảng lớn nhất Đông Dương thuộc Pháp. Lúa gạo từ khắp đồng bằng sông Cửu Long đổ về, được xay xát tại các nhà máy ở Chợ Lớn, đóng bao rồi chở ra bến sông để xuất đi các nước. Dọc theo bờ sông là những dãy kho hàng, xưởng thợ, nơi hàng vạn phu bốc vác, thợ máy, người làm thuê lao động nặng nhọc để đổi lấy đồng lương ít ỏi, sống trong những xóm thợ nghèo ở gần cảng.\n\nTháng 2 năm 1911, rời Phan Thiết, Nguyễn Tất Thành đến Sài Gòn. Người tạm trú tại Liên Thành phân cuộc — chi nhánh của hội Liên Thành ở Chợ Lớn, nay là ngôi nhà số 5 đường Châu Văn Liêm, cũng là nơi gặp gỡ của nhiều nhà yêu nước trong phong trào Duy Tân. Suốt khoảng thời gian ở đây, Người sống giữa những người lao động bến cảng, học nghề tại một trường kỹ thuật gần đó và thường lui tới khu vực bến tàu để quan sát. Tận mắt chứng kiến cảnh cực nhọc của phu phen, cảnh giàu nghèo cách biệt giữa người lao động bản xứ và giới chủ, thương nhân ngoại quốc, chàng thanh niên hai mươi mốt tuổi càng nung nấu quyết tâm phải ra nước ngoài để tìm hiểu vì sao các dân tộc khác giàu mạnh, còn dân tộc mình lại chịu cảnh nô lệ, để từ đó tìm con đường giải phóng cho đồng bào.\n\nTrong bốn tháng ngắn ngủi ở Sài Gòn, ngoài giờ học nghề, Người còn dành thời gian lui tới các bến tàu, nhà kho để tìm hiểu về những chuyến hải trình, hỏi thăm cách thức xin việc trên tàu viễn dương — những dãy kho có ánh đèn treo như trong không gian phục dựng chính là nơi anh thường quan sát nhịp sống của cảng thị. Không có tiền bạc, không có người quen giới thiệu, con đường thực tế nhất để ra nước ngoài, với một thanh niên chỉ có sức lao động, là tìm được một chỗ làm ngay trên chính những con tàu ấy.\n\nChỉ ít lâu sau, ngày 5 tháng 6 năm 1911, quyết tâm ấy trở thành hành động: Người bước lên con tàu Amiral Latouche-Tréville rời bến, khởi đầu ba mươi năm bôn ba tìm đường cứu nước (xem chuyên đề Bến Nhà Rồng, Người phụ bếp Văn Ba).\n\nKhu vực bến cảng, nhà kho năm xưa nay đã đổi thay nhiều so với hơn một trăm năm trước; tòa nhà Nhà Rồng ở gần đó, từng là trụ sở hãng tàu, nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh, nơi trưng bày nhiều tư liệu về những năm tháng Sài Gòn của Người. Ngôi nhà số 5 Châu Văn Liêm, nơi Người từng tạm trú, đã được công nhận là di tích lịch sử quốc gia từ ngày 16 tháng 11 năm 1988, còn chiếc đèn treo trong không gian phục dựng chỉ là hình ảnh gợi nhớ không khí lao động của bến cảng năm ấy.","nguon":"Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia; Bảo tàng Hồ Chí Minh","doc":[{"t":"Ánh đèn bên những dãy kho. Chiếc đèn treo có lồng sắt bảo vệ bóng đèn là đồ vật minh họa, không phải hiện vật gốc, gợi lại kiểu chiếu sáng quen thuộc trong những dãy kho, xưởng bên bến cảng Sài Gòn đầu thế kỷ XX — nơi ánh sáng phải đủ chắc chắn để chịu được va chạm của người khuân vác, xe kéo hàng qua lại suốt ngày đêm. Dưới thứ ánh đèn ấy, hàng hóa được xếp dỡ, kiểm đếm rồi chất lên những chuyến tàu viễn dương chờ sẵn ngoài sông."},{"t":"Sài Gòn – Chợ Lớn những năm đầu thế kỷ XX là thương cảng lớn nhất Đông Dương thuộc Pháp. Lúa gạo từ khắp đồng bằng sông Cửu Long đổ về, được xay xát tại các nhà máy ở Chợ Lớn, đóng bao rồi chở ra bến sông để xuất đi các nước. Dọc theo bờ sông là những dãy kho hàng, xưởng thợ, nơi hàng vạn phu bốc vác, thợ máy, người làm thuê lao động nặng nhọc để đổi lấy đồng lương ít ỏi, sống trong những xóm thợ nghèo ở gần cảng."},{"t":"Tháng 2 năm 1911, rời Phan Thiết, Nguyễn Tất Thành đến Sài Gòn. Người tạm trú tại Liên Thành phân cuộc — chi nhánh của hội Liên Thành ở Chợ Lớn, nay là ngôi nhà số 5 đường Châu Văn Liêm, cũng là nơi gặp gỡ của nhiều nhà yêu nước trong phong trào Duy Tân. Suốt khoảng thời gian ở đây, Người sống giữa những người lao động bến cảng, học nghề tại một trường kỹ thuật gần đó và thường lui tới khu vực bến tàu để quan sát. Tận mắt chứng kiến cảnh cực nhọc của phu phen, cảnh giàu nghèo cách biệt giữa người lao động bản xứ và giới chủ, thương nhân ngoại quốc, chàng thanh niên hai mươi mốt tuổi càng nung nấu quyết tâm phải ra nước ngoài để tìm hiểu vì sao các dân tộc khác giàu mạnh, còn dân tộc mình lại chịu cảnh nô lệ, để từ đó tìm con đường giải phóng cho đồng bào."},{"t":"Trong bốn tháng ngắn ngủi ở Sài Gòn, ngoài giờ học nghề, Người còn dành thời gian lui tới các bến tàu, nhà kho để tìm hiểu về những chuyến hải trình, hỏi thăm cách thức xin việc trên tàu viễn dương — những dãy kho có ánh đèn treo như trong không gian phục dựng chính là nơi anh thường quan sát nhịp sống của cảng thị. Không có tiền bạc, không có người quen giới thiệu, con đường thực tế nhất để ra nước ngoài, với một thanh niên chỉ có sức lao động, là tìm được một chỗ làm ngay trên chính những con tàu ấy."},{"t":"Chỉ ít lâu sau, ngày 5 tháng 6 năm 1911, quyết tâm ấy trở thành hành động: Người bước lên con tàu Amiral Latouche-Tréville rời bến, khởi đầu ba mươi năm bôn ba tìm đường cứu nước (xem chuyên đề Bến Nhà Rồng, Người phụ bếp Văn Ba)."},{"t":"Khu vực bến cảng, nhà kho năm xưa nay đã đổi thay nhiều so với hơn một trăm năm trước; tòa nhà Nhà Rồng ở gần đó, từng là trụ sở hãng tàu, nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh, nơi trưng bày nhiều tư liệu về những năm tháng Sài Gòn của Người. Ngôi nhà số 5 Châu Văn Liêm, nơi Người từng tạm trú, đã được công nhận là di tích lịch sử quốc gia từ ngày 16 tháng 11 năm 1988, còn chiếc đèn treo trong không gian phục dựng chỉ là hình ảnh gợi nhớ không khí lao động của bến cảng năm ấy."},{"t":"Bạn có biết? Ngôi nhà Liên Thành phân cuộc ở Chợ Lớn, nơi Nguyễn Tất Thành từng tạm trú năm 1911, nay là số 5 đường Châu Văn Liêm, được công nhận di tích lịch sử quốc gia ngày 16/11/1988."}],"ban_co_biet":"Ngôi nhà Liên Thành phân cuộc ở Chợ Lớn, nơi Nguyễn Tất Thành từng tạm trú năm 1911, nay là số 5 đường Châu Văn Liêm, được công nhận di tích lịch sử quốc gia ngày 16/11/1988."},{"id":"caged_hanging_light@-2.8,-7.2","x":-2.8,"y":5.1,"z":-7.22,"loai":"caged_hanging_light","ten":"Đèn xưởng","tieu_de":"Nhớ xưởng học nghề trường Bá Nghệ","text":"Ánh đèn treo có lồng sắt trong không gian phục dựng là đồ vật minh họa, gợi nhắc những xưởng máy của Sài Gòn thời thuộc Pháp — nơi tiếng búa, tiếng máy tiện, mùi dầu mỡ hòa lẫn trong ánh sáng vàng vọt của những ngọn đèn treo trên cao, chiếu xuống các dãy bàn nguội, bàn tiện cho thợ học việc.\n\nTrong khoảng ba tháng đầu năm 1911, sau khi đến Sài Gòn, Nguyễn Tất Thành theo học tại Trường Cơ khí Á châu (École des Mécaniciens Asiatiques) — người Sài Gòn quen gọi là trường Bá Nghệ. Trường do người Pháp lập năm 1906, với mục đích đào tạo thợ máy và nhân viên hàng hải phục vụ cho các hãng tàu, xưởng cơ khí thuộc địa. Học trò ở đây được rèn luyện những kỹ năng cơ bản của nghề cơ khí: nguội, tiện, rèn, hàn — những công việc đòi hỏi đôi tay khéo léo và sức chịu đựng bên cạnh lò lửa, máy móc suốt nhiều giờ liền.\n\nKhoảng thời gian ngắn ngủi học nghề ấy có một ý nghĩa đặc biệt: nó cho Nguyễn Tất Thành cơ hội sống gần, làm việc cùng những người thợ nghèo, hiểu thêm về đời sống lao động dưới chế độ thuộc địa, đồng thời có thêm một nghề tay chân — thứ về sau sẽ giúp anh tự nuôi sống bản thân trong suốt hành trình bôn ba qua nhiều nước, từ phụ bếp trên tàu viễn dương đến làm thuê ở London, Paris.\n\nĐiều đáng chú ý là ngôi trường nhỏ bé này về sau còn gắn với một học trò khác cũng trở thành nguyên thủ quốc gia: người thợ máy Tôn Đức Thắng, sinh năm 1888 tại An Giang, cũng từng theo học tại đây trước khi trở thành công nhân, nhà cách mạng, và sau này là Chủ tịch nước Việt Nam Dân chủ Cộng hòa rồi Chủ tịch nước Cộng hòa Xã hội chủ nghĩa Việt Nam. Hai người học trò của cùng một xưởng cơ khí nhỏ ở Sài Gòn, cách nhau không nhiều năm trên ghế học nghề, sau này đều đứng ở vị trí cao nhất của đất nước — một sự trùng hợp mà những người làm công tác bảo tàng, nghiên cứu lịch sử sau này vẫn nhắc tới như một minh chứng cho việc những con người làm nên lịch sử từng khởi đầu bằng công việc lao động chân tay bình dị nhất.\n\nVới riêng Nguyễn Tất Thành, ba tháng học nghề tại trường Bá Nghệ không giúp anh trở thành một thợ máy chuyên nghiệp, nhưng đã cho anh một chút vốn liếng kỹ thuật và, quan trọng hơn, cơ hội tiếp xúc gần với môi trường bến cảng, nơi các hãng tàu tuyển người — mối liên hệ sẽ dẫn anh tới quyết định xin làm phụ bếp trên một con tàu viễn dương chỉ ít tháng sau đó.\n\nTrường Cơ khí Á châu ngày nay chính là Trường Cao đẳng Kỹ thuật Cao Thắng, vẫn hoạt động tại Thành phố Hồ Chí Minh, được xem là một trong những cơ sở đào tạo kỹ thuật lâu đời nhất Việt Nam. Xưởng thực hành xưa không còn nguyên vẹn dấu tích của những năm 1911, nên ngọn đèn trong không gian 3D chỉ là hình ảnh minh họa, giúp gợi lại bầu không khí học nghề của một xưởng cơ khí thời thuộc địa.","nguon":"Báo Nhân Dân — “Ngôi trường có hai Chủ tịch nước từng theo học”; Hồ Chí Minh – Biên niên tiểu sử, tập 1","doc":[{"t":"Nhớ xưởng học nghề trường Bá Nghệ. Ánh đèn treo có lồng sắt trong không gian phục dựng là đồ vật minh họa, gợi nhắc những xưởng máy của Sài Gòn thời thuộc Pháp — nơi tiếng búa, tiếng máy tiện, mùi dầu mỡ hòa lẫn trong ánh sáng vàng vọt của những ngọn đèn treo trên cao, chiếu xuống các dãy bàn nguội, bàn tiện cho thợ học việc."},{"t":"Trong khoảng ba tháng đầu năm 1911, sau khi đến Sài Gòn, Nguyễn Tất Thành theo học tại Trường Cơ khí Á châu (École des Mécaniciens Asiatiques) — người Sài Gòn quen gọi là trường Bá Nghệ. Trường do người Pháp lập năm 1906, với mục đích đào tạo thợ máy và nhân viên hàng hải phục vụ cho các hãng tàu, xưởng cơ khí thuộc địa. Học trò ở đây được rèn luyện những kỹ năng cơ bản của nghề cơ khí: nguội, tiện, rèn, hàn — những công việc đòi hỏi đôi tay khéo léo và sức chịu đựng bên cạnh lò lửa, máy móc suốt nhiều giờ liền."},{"t":"Khoảng thời gian ngắn ngủi học nghề ấy có một ý nghĩa đặc biệt: nó cho Nguyễn Tất Thành cơ hội sống gần, làm việc cùng những người thợ nghèo, hiểu thêm về đời sống lao động dưới chế độ thuộc địa, đồng thời có thêm một nghề tay chân — thứ về sau sẽ giúp anh tự nuôi sống bản thân trong suốt hành trình bôn ba qua nhiều nước, từ phụ bếp trên tàu viễn dương đến làm thuê ở London, Paris."},{"t":"Điều đáng chú ý là ngôi trường nhỏ bé này về sau còn gắn với một học trò khác cũng trở thành nguyên thủ quốc gia: người thợ máy Tôn Đức Thắng, sinh năm 1888 tại An Giang, cũng từng theo học tại đây trước khi trở thành công nhân, nhà cách mạng, và sau này là Chủ tịch nước Việt Nam Dân chủ Cộng hòa rồi Chủ tịch nước Cộng hòa Xã hội chủ nghĩa Việt Nam. Hai người học trò của cùng một xưởng cơ khí nhỏ ở Sài Gòn, cách nhau không nhiều năm trên ghế học nghề, sau này đều đứng ở vị trí cao nhất của đất nước — một sự trùng hợp mà những người làm công tác bảo tàng, nghiên cứu lịch sử sau này vẫn nhắc tới như một minh chứng cho việc những con người làm nên lịch sử từng khởi đầu bằng công việc lao động chân tay bình dị nhất."},{"t":"Với riêng Nguyễn Tất Thành, ba tháng học nghề tại trường Bá Nghệ không giúp anh trở thành một thợ máy chuyên nghiệp, nhưng đã cho anh một chút vốn liếng kỹ thuật và, quan trọng hơn, cơ hội tiếp xúc gần với môi trường bến cảng, nơi các hãng tàu tuyển người — mối liên hệ sẽ dẫn anh tới quyết định xin làm phụ bếp trên một con tàu viễn dương chỉ ít tháng sau đó."},{"t":"Trường Cơ khí Á châu ngày nay chính là Trường Cao đẳng Kỹ thuật Cao Thắng, vẫn hoạt động tại Thành phố Hồ Chí Minh, được xem là một trong những cơ sở đào tạo kỹ thuật lâu đời nhất Việt Nam. Xưởng thực hành xưa không còn nguyên vẹn dấu tích của những năm 1911, nên ngọn đèn trong không gian 3D chỉ là hình ảnh minh họa, giúp gợi lại bầu không khí học nghề của một xưởng cơ khí thời thuộc địa."},{"t":"Bạn có biết? Người thợ máy Tôn Đức Thắng — sau này là Chủ tịch nước — cũng từng theo học tại Trường Cơ khí Á châu (trường Bá Nghệ), nơi Nguyễn Tất Thành học nghề đầu năm 1911."}],"ban_co_biet":"Người thợ máy Tôn Đức Thắng — sau này là Chủ tịch nước — cũng từng theo học tại Trường Cơ khí Á châu (trường Bá Nghệ), nơi Nguyễn Tất Thành học nghề đầu năm 1911."},{"id":"caged_hanging_light@-2.8,-14.1","x":-2.8,"y":5.1,"z":-14.13,"loai":"caged_hanging_light","ten":"Đèn khoang tàu","tieu_de":"Những ngày làm phụ bếp dưới khoang tàu","text":"Loại đèn có lồng bảo vệ chắc chắn thường gặp trong kho hàng và khoang tàu biển; trong không gian phục dựng, nó là đồ vật minh họa, gợi lại nơi làm việc của người phụ bếp trẻ mang tên Văn Ba dưới hầm tàu — nơi ánh sáng ban ngày gần như không lọt tới, chỉ có ánh đèn treo soi giữa những dãy thùng than, sọt rau, tủ ướp lạnh đựng thịt cá.\n\nNgày 3 tháng 6 năm 1911, tại văn phòng đại diện của hãng tàu Chargeurs Réunis ở Sài Gòn, Nguyễn Tất Thành — khi ấy mang tên Văn Ba — được nhận làm phụ bếp trên tàu Amiral Latouche-Tréville, với đồng lương 45 franc mỗi tháng. Đây là tàu chở hàng kiêm chở khách, hạ thủy năm 1904, trọng tải 5.572 tấn, chạy tuyến Pháp – Đông Dương, còn hoạt động đến năm 1929; người Việt thời ấy quen gọi hãng chủ tàu là \"hãng Năm Sao\".\n\nTheo lời kể của Trần Dân Tiên trong \"Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch\", công việc của người phụ bếp trên tàu bắt đầu từ bốn giờ sáng và kéo dài suốt ngày: quét dọn nhà bếp, nhóm lò, khuân than, rồi xuống tận hầm tàu — nơi chiếc đèn lồng sắt như trong không gian phục dựng từng soi sáng — để lấy rau, thịt, cá và nước đá mang lên cho nhà bếp chính. Đó là công việc nặng nhọc, đơn điệu, nhưng với một thanh niên hai mươi mốt tuổi không tiền bạc, không người đỡ đầu, đó là con đường duy nhất để có thể rời quê hương, đặt chân tới những vùng đất mới và tận mắt nhìn xem \"các dân tộc khác làm như thế nào\" trước khi trở về giúp đồng bào mình.\n\nHai ngày sau khi nhận việc, ngày 5 tháng 6 năm 1911, tàu Amiral Latouche-Tréville rời bến Sài Gòn. Sau ba mươi mốt ngày lênh đênh qua Singapore, Colombo (Tích Lan, nay là Sri Lanka), vượt kênh đào Suez, ghé Port Said của Ai Cập, tàu cập cảng Marseille ngày 6 tháng 7 năm 1911, rồi vòng lên Le Havre, mở đầu chặng đường ba mươi năm Người bôn ba khắp năm châu tìm đường cứu nước.\n\nSuốt hải trình dài ấy, những giờ nghỉ hiếm hoi của người phụ bếp trẻ thường diễn ra ngay trong khoang tàu chật hẹp, dưới thứ ánh đèn lồng sắt tương tự vật minh họa này — khác hẳn không gian trên boong tàu dành cho hành khách hạng nhất. Chính sự tương phản ấy, giữa cảnh sống xa hoa trên boong và công việc lao động dưới hầm tàu, càng khiến người thanh niên thêm thấm thía về thân phận của người lao động thuộc địa trên chính con tàu của \"mẫu quốc\".\n\nCon tàu Amiral Latouche-Tréville không còn tồn tại đến ngày nay; nơi nó từng rời bến — khu vực Bến Nhà Rồng bên sông Sài Gòn — nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh, còn lưu giữ nhiều tư liệu, hình ảnh về con tàu và chuyến đi lịch sử ấy. Chiếc đèn khoang tàu trong không gian 3D, vì thế, chỉ là vật minh họa cho một góc lao động thầm lặng nhưng mang ý nghĩa mở đầu cho cả một hành trình.","nguon":"Trần Dân Tiên, “Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch”; Hồ Chí Minh – Biên niên tiểu sử, NXB Chính trị quốc gia","doc":[{"t":"Những ngày làm phụ bếp dưới khoang tàu. Loại đèn có lồng bảo vệ chắc chắn thường gặp trong kho hàng và khoang tàu biển; trong không gian phục dựng, nó là đồ vật minh họa, gợi lại nơi làm việc của người phụ bếp trẻ mang tên Văn Ba dưới hầm tàu — nơi ánh sáng ban ngày gần như không lọt tới, chỉ có ánh đèn treo soi giữa những dãy thùng than, sọt rau, tủ ướp lạnh đựng thịt cá."},{"t":"Ngày 3 tháng 6 năm 1911, tại văn phòng đại diện của hãng tàu Chargeurs Réunis ở Sài Gòn, Nguyễn Tất Thành — khi ấy mang tên Văn Ba — được nhận làm phụ bếp trên tàu Amiral Latouche-Tréville, với đồng lương 45 franc mỗi tháng. Đây là tàu chở hàng kiêm chở khách, hạ thủy năm 1904, trọng tải 5.572 tấn, chạy tuyến Pháp – Đông Dương, còn hoạt động đến năm 1929; người Việt thời ấy quen gọi hãng chủ tàu là \"hãng Năm Sao\"."},{"t":"Theo lời kể của Trần Dân Tiên trong \"Những mẩu chuyện về đời hoạt động của Hồ Chủ tịch\", công việc của người phụ bếp trên tàu bắt đầu từ bốn giờ sáng và kéo dài suốt ngày: quét dọn nhà bếp, nhóm lò, khuân than, rồi xuống tận hầm tàu — nơi chiếc đèn lồng sắt như trong không gian phục dựng từng soi sáng — để lấy rau, thịt, cá và nước đá mang lên cho nhà bếp chính. Đó là công việc nặng nhọc, đơn điệu, nhưng với một thanh niên hai mươi mốt tuổi không tiền bạc, không người đỡ đầu, đó là con đường duy nhất để có thể rời quê hương, đặt chân tới những vùng đất mới và tận mắt nhìn xem \"các dân tộc khác làm như thế nào\" trước khi trở về giúp đồng bào mình."},{"t":"Hai ngày sau khi nhận việc, ngày 5 tháng 6 năm 1911, tàu Amiral Latouche-Tréville rời bến Sài Gòn. Sau ba mươi mốt ngày lênh đênh qua Singapore, Colombo (Tích Lan, nay là Sri Lanka), vượt kênh đào Suez, ghé Port Said của Ai Cập, tàu cập cảng Marseille ngày 6 tháng 7 năm 1911, rồi vòng lên Le Havre, mở đầu chặng đường ba mươi năm Người bôn ba khắp năm châu tìm đường cứu nước."},{"t":"Suốt hải trình dài ấy, những giờ nghỉ hiếm hoi của người phụ bếp trẻ thường diễn ra ngay trong khoang tàu chật hẹp, dưới thứ ánh đèn lồng sắt tương tự vật minh họa này — khác hẳn không gian trên boong tàu dành cho hành khách hạng nhất. Chính sự tương phản ấy, giữa cảnh sống xa hoa trên boong và công việc lao động dưới hầm tàu, càng khiến người thanh niên thêm thấm thía về thân phận của người lao động thuộc địa trên chính con tàu của \"mẫu quốc\"."},{"t":"Con tàu Amiral Latouche-Tréville không còn tồn tại đến ngày nay; nơi nó từng rời bến — khu vực Bến Nhà Rồng bên sông Sài Gòn — nay là Bảo tàng Hồ Chí Minh – Chi nhánh Thành phố Hồ Chí Minh, còn lưu giữ nhiều tư liệu, hình ảnh về con tàu và chuyến đi lịch sử ấy. Chiếc đèn khoang tàu trong không gian 3D, vì thế, chỉ là vật minh họa cho một góc lao động thầm lặng nhưng mang ý nghĩa mở đầu cho cả một hành trình."},{"t":"Bạn có biết? Tàu Amiral Latouche-Tréville mang tên đô đốc Pháp Louis-René Levassor de Latouche-Tréville (1745–1804); tàu hạ thủy năm 1904 và hoạt động tuyến Pháp – Đông Dương đến năm 1929."}],"ban_co_biet":"Tàu Amiral Latouche-Tréville mang tên đô đốc Pháp Louis-René Levassor de Latouche-Tréville (1745–1804); tàu hạ thủy năm 1904 và hoạt động tuyến Pháp – Đông Dương đến năm 1929."}]};
